import{a as e}from"./jsx-runtime-Bzw2jH9X.js";var t=e({default:()=>n}),n=JSON.parse(`[{"id":"qx-a2-001","clusterId":"A","werkstueckRef":"A.12","stufe":1,"question":"Maja sagt: „Stell dir mal vor, die Geheimdienste hätten alles von langer Hand geplant, und dann passiert genau das, was man jetzt in den Nachrichten sieht. Passt doch alles zusammen, also muss es so gewesen sein.“ Woran erkennst du, dass das keine tragfähige Überlegung ist?","options":["Sie legt weder Annahmen noch Spielregeln fest und kreist um eine bereits feststehende Überzeugung, statt prüfbare Folgen herzuleiten.","Sie geht von einer bloß ausgedachten Annahme aus, und ein frei erfundenes Szenario kann über die tatsächlichen Ereignisse kaum etwas aussagen.","Sie hält den Plan für die Ursache, nur weil die Ereignisse danach so eintraten, und verwechselt damit eine zeitliche Folge mit einer Ursache.","Sie nennt keine Quelle für ihre Vermutung, und eine Überlegung, die sich auf keinen Beleg aus Nachrichten oder Fachliteratur stützt, trägt nicht."],"correctIndex":0,"explanation":"Ein Gedankenexperiment legt die Annahme und die Spielregeln vorab fest und folgt dann konsequent der Logik, um Stimmigkeit und Folgen zu prüfen. Majas Überlegung tut das Gegenteil: Sie beginnt beim gewünschten Ergebnis und schmückt es aus. Dass „alles zusammenpasst“, ist bei einer frei erzählten Geschichte kein Wunder, denn sie lässt sich beliebig anpassen. Entscheidend ist, ob Regeln gelten und ob sich daraus Schlüsse ziehen lassen, die man nachprüfen kann; ein erfundenes Szenario ist dagegen nicht das Problem, auch Einstein stellte sich vor, einem Lichtstrahl hinterherzujagen. Und selbst ein sauber durchgeführtes Gedankenexperiment liefert keinen Befund über die Wirklichkeit, sondern prüft nur, ob eine Idee in sich stimmig ist.","coreRule":"⚡ Ein Gedankenexperiment braucht klare Anfangsbedingungen und Regeln und leitet prüfbare Folgen her. Eine Geschichte, die nur eine fertige Überzeugung ausschmückt, ist kein Test.","quote":"","quoteLabel":"","beleg":"Werkstück A.12 (Kontext & Tiefe; Red Flag „Unstrukturierte Fantasie“; Der Kipppunkt)","status":"entwurf","scenario":"","kurz":"Maja legt weder Annahmen noch Spielregeln fest, sondern beginnt beim gewünschten Ergebnis und schmückt es aus. Dass „alles zusammenpasst“, ist bei einer frei erzählten Geschichte kein Wunder, denn sie lässt sich beliebig anpassen.","prueffrage":"Hätte Maja dieselbe Geschichte auch erzählen können, wenn in den Nachrichten etwas ganz anderes passiert wäre?","rueckmeldung":[{"option":1,"text":"Dass Majas Szenario ausgedacht ist, stimmt. Das allein ist aber kein Fehler: Auch Einstein stellte sich vor, einem Lichtstrahl hinterherzujagen. Entscheidend ist, ob Annahmen und Regeln feststehen und Folgen prüfbar sind."},{"option":2,"text":"Das wäre ein typischer Fehler bei Ursachenbehauptungen. Maja behauptet aber keine Reihenfolge von Ereignissen, sondern sagt nur, alles „passe zusammen“. Der Mangel liegt im Vorgehen: Sie geht vom Wunschergebnis aus und fragt nicht nach prüfbaren Folgen."},{"option":3,"text":"Fehlende Belege wiegen bei Behauptungen über die Wirklichkeit tatsächlich schwer. Ein Gedankenexperiment braucht aber keine Quelle, sondern festgelegte Annahmen und Regeln und daraus prüfbare Schlüsse. Genau das lässt Majas Überlegung vermissen."}],"familie":"zu-ende-denken","fertigkeit":"F1","quellen":[{"typ":"url","kurz":"Stanford Encyclopedia of Philosophy: Thought Experiments (überarb. 28.11.2023)","oeffentlich":true,"url":"https://plato.stanford.edu/entries/thought-experiment/","abruf":"2026-10-12"}],"thema":"Netz und Medien","pruefung":{"lauf":"quiz-audit-v8","modell":"claude-sonnet-5-5","datum":"2026-10-15","urteil":"ok","pruefsumme":"1243c16ababb924a"}},{"id":"qx-a2-002","clusterId":"A","werkstueckRef":"A.12","stufe":2,"question":"Welcher Prüfschritt deckt am besten auf, ob diese Behauptung in sich stimmig ist?","scenario":"Eine Bekannte erklärt dir beim Kaffee: „Deine Gedanken erschaffen deine Realität. Wer fest genug an etwas denkt, bekommt es auch.“ Du willst die Behauptung prüfen, ohne gleich ein aufwendiges Experiment zu planen.","options":["Du nimmst an, sie gelte für alle Menschen gleichzeitig, und suchst nach Widersprüchen, etwa wenn zwei Menschen sich denselben einmaligen Lottogewinn vorstellen.","Du vergleichst eine Gruppe, die fest an etwas denkt, mit einer Kontrollgruppe, die das nicht tut, und zählst nach, in welcher Gruppe sich mehr Wünsche erfüllen.","Du fragst, ob die Bekannte an ihrer Aussage verdient oder sonst ein Eigeninteresse hat, und gewichtest ihre Behauptung danach, wem sie nützen würde.","Du prüfst, ob sich berichtete Erfolgsgeschichten einfacher durch Zufall oder Auswahl erklären lassen, und ziehst die einfachste passende Erklärung vor."],"correctIndex":0,"explanation":"Ein Gedankenexperiment macht eine Behauptung testbar, ohne dass man sie in der Wirklichkeit ausprobieren muss: Man setzt sie als wahr voraus und spielt durch, was daraus folgt. Gilt der Satz für alle 8 Milliarden Menschen, müsste derselbe einmalige Lottogewinn mehreren Menschen zufallen. Ein Diktator, der sich den Gehorsam aller wünscht, und ein Freiheitskämpfer, der sich die Freiheit aller wünscht, würden unvereinbare Realitäten erzeugen. Eine Behauptung, die im Maßstab in Widersprüche gerät, ist in sich nicht stimmig. Die anderen Schritte sind in anderer Lage nützlich, beantworten hier aber nicht die Frage nach der inneren Stimmigkeit: Eine Kontrollgruppe wäre genau das aufwendige Experiment, das du vermeiden willst. Das Eigeninteresse der Bekannten sagt nichts darüber, ob ihr Satz in sich stimmt, und ob sich Erfolge durch Zufall erklären ließen, zeigt nichts über die Logik der Behauptung.","coreRule":"⚡ Prüfe eine Behauptung, indem du sie als wahr annimmst und im großen Maßstab durchspielst: Bleibt sie widerspruchsfrei?","beleg":"Werkstück A.12 (Anwendung: Esoterik & New Age, „Gesetz der Anziehung“)","status":"entwurf","kurz":"Setzt du den Satz als wahr voraus und spielst durch, was für alle Menschen zugleich folgt, geraten die Wünsche in Konflikt, etwa beim einmaligen Lottogewinn. Das deckt die innere Unstimmigkeit auf, ohne dass du etwas ausprobieren musst.","prueffrage":"Erfährst du aus gezählten Erfolgen oder aus dem Ruf einer Person, ob der Satz sich selbst widerspricht?","rueckmeldung":[{"option":1,"text":"Ein Vergleich mit Kontrollgruppe wäre ein gutes Mittel, um die Wirkung zu testen. Du wolltest aber gerade kein aufwendiges Experiment planen, und er sagt auch nichts darüber, ob der Satz in sich stimmig ist."},{"option":2,"text":"Ein Eigeninteresse kann misstrauisch machen und ist in anderen Situationen ein brauchbarer Hinweis. Ob ein Satz in sich stimmig ist, zeigt es nicht, denn auch eine interessengeleitete Behauptung kann wahr sein."},{"option":3,"text":"Zufall und Auswahl erklären Erfolgsgeschichten oft einfacher, das ist ein nützlicher Gedanke. Hier liegen aber gar keine Berichte vor, und die Frage nach der Logik der Behauptung beantwortet dieser Schritt nicht."}],"familie":"zu-ende-denken","fertigkeit":"F1","quellen":[{"typ":"url","kurz":"Stanford Encyclopedia of Philosophy: Thought Experiments (überarb. 28.11.2023)","oeffentlich":true,"url":"https://plato.stanford.edu/entries/thought-experiment/","abruf":"2026-10-12"}],"thema":"Psychologie","pruefung":{"lauf":"quiz-audit-v4","modell":"claude-sonnet-5-5","datum":"2026-10-14","urteil":"ok","pruefsumme":"a9b3ea2e7fa2bc22"}},{"id":"qx-a2-003","clusterId":"A","werkstueckRef":"A.12","stufe":3,"question":"Ein Redner sagt: „Mein Gedankenexperiment zeigt, dass Wasser ein Gedächtnis hat, denn man kann es widerspruchsfrei durchspielen.“ Was ist an diesem Schluss fehlerhaft?","options":["Er schließt von der Widerspruchsfreiheit auf die Wirklichkeit, doch das Durchspielen zeigt nur, dass die Idee denkbar und stimmig ist, nicht dass sie zutrifft.","Er stützt sich auf ein einziges Gedankenexperiment, doch tragfähig wäre sein Schluss erst, wenn mehrere unabhängige Durchspiele zum selben Ergebnis kämen.","Er drückt sich nur zu stark aus, doch im Kern stimmt es: Das widerspruchsfreie Durchspielen ist ein erster bestandener Test, der die Idee vorläufig stützt.","Er schließt im Grunde zulässig, doch müsste er das ergänzen: Solange niemand einen Widerspruch aufzeigt, liegt die Beweislast bei denen, die die Idee bestreiten."],"correctIndex":0,"explanation":"Ein Gedankenexperiment prüft die logische Stimmigkeit einer Annahme, mehr nicht. Fällt eine Idee dabei durch, weil sie sich selbst widerspricht, muss man sie gar nicht erst an der Wirklichkeit testen. Besteht sie die Prüfung, ist sie damit noch nicht wahr: Nur weil eine Idee ein Gedankenexperiment überlebt, heißt das noch lange nicht, dass sie wahr ist. Ob Wasser ein Gedächtnis hat, entscheidet am Ende die Realität, nicht die Vorstellungskraft. Dabei sind Annahmen, die der Wirklichkeit widersprechen, durchaus erlaubt (Einstein ließ sich auf einem Lichtstrahl reiten), solange sie als Annahmen kenntlich bleiben und das Ergebnis nicht mit einem Beweis verwechselt wird.","coreRule":"⚡ Überleben im Gedankenexperiment heißt „möglich“, nicht „wahr“; entscheiden muss die Realität.","beleg":"Werkstück A.12 (Red Flags; Der Kipppunkt)","status":"entwurf","kurz":"Ein Gedankenexperiment prüft nur, ob eine Idee in sich stimmig ist. Der Fehler liegt darin, aus „denkbar und widerspruchsfrei“ auf „trifft zu“ zu schließen; ob Wasser ein Gedächtnis hat, entscheidet die Wirklichkeit.","prueffrage":"Welche Messung oder Beobachtung könnte zeigen, dass der Redner mit seiner Behauptung danebenliegt?","rueckmeldung":[{"option":1,"text":"Ein einzelnes Experiment wirkt dünn, mehr Durchspiele klingen nach mehr Sicherheit. Auch hundert stimmige Durchspiele prüfen aber nur die Denkbarkeit, nie die Wirklichkeit. Die Anzahl ist nicht das Problem."},{"option":2,"text":"Wer eine Idee durchspielt und keinen Widerspruch findet, hat immerhin geprüft, dass sie nicht in sich zusammenfällt. Das ist aber nur eine Mindestbedingung, kein Stützen der Behauptung: Aus der Stimmigkeit folgt nicht, dass die Idee zutrifft."},{"option":3,"text":"Eine Idee, die sich selbst widerspricht, scheidet tatsächlich aus. Daraus folgt aber nicht, dass jede stimmige Idee gilt, bis jemand sie widerlegt: Die Beweislast trägt, wer eine Behauptung über die Wirklichkeit aufstellt."}],"familie":"zu-ende-denken","fertigkeit":"F1","quellen":[{"typ":"url","kurz":"Stanford Encyclopedia of Philosophy: Thought Experiments (überarb. 28.11.2023)","oeffentlich":true,"url":"https://plato.stanford.edu/entries/thought-experiment/","abruf":"2026-10-12"}],"thema":"Natur und Klima","pruefung":{"lauf":"quiz-audit-v9","modell":"claude-sonnet-5-5","datum":"2026-10-15","urteil":"ok","pruefsumme":"ac4fd36ad7aa36b2"}},{"id":"qx-a2-004","clusterId":"A","werkstueckRef":"A.12","stufe":4,"question":"Wie belastbar ist das Ergebnis einer solchen Rechnung mit offengelegten, aber geschätzten Annahmen?","options":["Die Rechnung widerlegt die behauptete Täuschung, sofern das Ergebnis deutlich ausfällt und die Zahlen plausibel klingen.","Sie zeigt, welche Konsequenzen die Behauptung unter den genannten Annahmen hätte; weil die Annahmen offenliegen, kann jeder sie nachrechnen, ändern und angreifen.","Sie ist kaum aussagekräftig, weil geschätzte Zahlen zu ungenau sind, um daraus eine Schlussfolgerung zu ziehen.","Sie wird erst belastbar, wenn die Schätzungen durch gemessene Werte ersetzt sind und keine Annahme mehr offen ist."],"correctIndex":1,"explanation":"Eine Rechnung mit Schätzwerten ist kein Beweis, aber auch nicht wertlos. Sie macht aus einer vagen Vorstellung ein Modell: Die Annahmen stehen offen auf dem Tisch, und jeder kann prüfen, ob sie vernünftig sind, und sie verändern. Dass die Zahlen Schätzungen sind, entwertet die Rechnung nicht, solange die Annahmen sichtbar sind und überprüft werden können. Ein reales Beispiel: Der Forscher David Robert Grimes rechnete 2016 die Mondlandungsverschwörung so durch. Er setzte rund 411.000 Mitwissende an (die NASA-Beschäftigten im Spitzenjahr 1965) und schätzte das Risiko des Verrats bewusst niedrig. Selbst dann wäre der Schwindel nach knapp vier Jahren mit über 95 Prozent Wahrscheinlichkeit aufgeflogen. Grimes selbst nennt die Zahlen grobe Größenordnungen, und das Modell nimmt an, alle Gezählten wären eingeweiht. Der Wert liegt in der Nachprüfbarkeit der Annahmen, nicht in einem Beweis.","coreRule":"⚡ Ein Gedankenexperiment wird zum Modell, wenn seine Annahmen offenliegen und angreifbar sind.","beleg":"Werkstück A.12 (Anwendung: Verschwörungsmythen); Fn. ga-grimes (Grimes 2016, PLOS ONE 11(1), e0147905, S. 8 und S. 11)","status":"freigegeben","freigabe":{"datum":"2026-10-13","pruefsumme":"880871099472401a","vermerk":"Prüfpult"},"scenario":"Eine Forscherin schätzt für eine angebliche Jahrzehnte alte Täuschung grob die Zahl der Eingeweihten und das Risiko ein, dass jemand das Geheimnis ausplaudert. Sie rechnet beide Annahmen durch und legt sie in der Veröffentlichung offen. Ein Kritiker wendet ein: „Das sind doch nur geschätzte Zahlen, also ist die ganze Rechnung wertlos.“","kurz":"Die Rechnung ist kein Beweis, aber auch nicht wertlos: Sie zeigt, was die Behauptung unter den genannten Annahmen bedeuten würde. Weil diese offenliegen, kann jeder sie prüfen und ändern. Geschätzt heißt nicht wertlos, sondern angreifbar.","prueffrage":"Welche Zahlen stehen in der Rechnung, und würde sich das Ergebnis ändern, wenn man sie großzügig verschiebt?","rueckmeldung":[{"option":0,"text":"Ein deutliches Ergebnis wirkt wie ein Urteil. Doch die Rechnung zeigt nur, was unter den gewählten Annahmen folgt, und ist kein Beweis. Dass sie Zweifel begründet, heißt nicht, dass sie die Täuschung widerlegt."},{"option":2,"text":"Der Einwand hat einen wahren Kern: Schätzungen sind ungenau, und ein Beweis entsteht so nicht. Ungenau ist aber nicht wertlos, solange offenliegt, was angenommen wurde. Dann lässt sich prüfen, ob das Ergebnis auch bei anderen Zahlen hält."},{"option":3,"text":"Gemessene Werte wären natürlich besser. Wer Belastbarkeit aber erst ohne jede offene Annahme zugesteht, verlangt etwas, das kaum ein Modell erfüllt. Entscheidend ist, dass die Annahmen sichtbar und nachprüfbar sind, nicht dass sie gemessen sind."}],"familie":"zu-ende-denken","fertigkeit":"F1","quellen":[{"typ":"doi","kurz":"Grimes, D. R. (2016): On the Viability of Conspiratorial Beliefs. PLOS ONE 11(1), e0147905","oeffentlich":true,"doi":"10.1371/journal.pone.0147905"},{"typ":"doi","kurz":"Grimes, D. R. (2016): Correction: On the Viability of Conspiratorial Beliefs. PLOS ONE 11(3), e0151003","oeffentlich":true,"doi":"10.1371/journal.pone.0151003"}],"thema":"Geschichte und Wissenschaft","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"ok","pruefsumme":"880871099472401a"}},{"id":"qx-a2-005","clusterId":"A","werkstueckRef":"A.13","stufe":1,"question":"Was würdest du als Nächstes tun?","options":["Genau beobachten, wohin die Leute beim Hinuntergehen schauen und was sie auf ihrem Weg erreichen wollen.","Die Stufenkanten farbig markieren lassen, damit sie beim Hinuntergehen noch deutlicher zu erkennen sind.","Eine Schulung zum sicheren Treppengehen anbieten, damit die Leute lernen, bewusst auf die Stufen zu achten.","Eine Prämie für unfallfreie Monate ausloben, damit die Leute einen Anreiz haben, aufmerksamer zu sein."],"correctIndex":0,"explanation":"Wenn ein Verhalten unerklärlich wirkt, ist „dumm und unachtsam“ die bequeme, aber leere Erklärung: Sie prüft nichts und erklärt nicht, warum drei Maßnahmen nichts geändert haben. Wer Menschen als vernünftig Handelnde annimmt, fragt stattdessen, welches Ziel ihr Verhalten sinnvoll macht, und beobachtet es. Naheliegend ist hier etwa, dass die Leute beim Hinuntergehen schon die belebte Kreuzung am Treppenende im Blick haben, um eine Lücke zu finden, und deshalb nicht auf die Stufen achten. Erst wenn man das Ziel kennt, lässt sich das System ändern, statt die Menschen ändern zu wollen.","coreRule":"⚡ Bevor du Menschen als dumm abstempelst, frag nach dem unsichtbaren Ziel hinter ihrem Verhalten.","quote":"Das Problem war nicht der Mensch, sondern die Treppe im Verhältnis zum Flur.","quoteLabel":"Merksatz:","beleg":"Werkstück A.13 (Einstiegsgeschichte „Die verfluchte Treppe“; Kernidee; Kontext & Tiefe)","status":"entwurf","scenario":"In einem Bürogebäude häufen sich die Unfälle auf einer steilen Treppe. Am Fuß der Treppe kreuzen sich zwei stark befahrene Hauptflure. Vorsicht-Schilder, hellere Beleuchtung und rutschfeste Streifen haben nichts geändert, die Unfallrate ist seit Monaten unverändert hoch. Ein Manager sagt: „Unsere Leute sind einfach zu dumm und unachtsam für eine Treppe.“","kurz":"Wer „dumm und unachtsam“ sagt, erklärt nichts und prüft nichts. Sinnvoller ist, zu beobachten, welches Ziel das Verhalten für die Leute vernünftig macht. Erst dann lässt sich das System ändern statt die Menschen.","prueffrage":"Was haben Schilder, Beleuchtung und Streifen gemeinsam, und wurde vorher herausgefunden, warum die Leute gerade auf dieser Treppe stürzen?","rueckmeldung":[{"option":1,"text":"Deutlichere Kanten wirken wie eine naheliegende Verbesserung. Es ist aber dieselbe Art Maßnahme wie Schilder, Licht und Streifen, die nichts bewirkt haben, und sie geht davon aus, dass die Stufen schlecht zu sehen sind."},{"option":2,"text":"Eine Schulung nimmt an, dass den Leuten Wissen oder Achtsamkeit fehlt. Das ist im Kern die Erklärung des Managers in freundlicherer Form und prüft nicht, was die Leute auf der Treppe eigentlich im Blick haben."},{"option":3,"text":"Eine Prämie klingt nach einem Hebel, der Verhalten verändert. Sie setzt aber voraus, dass es an Motivation fehlt, und das ist nicht belegt. Offen bleibt, warum drei Maßnahmen schon wirkungslos waren."}],"familie":"wohlwollend-verstehen","fertigkeit":"F3","quellen":[{"typ":"url","kurz":"Gilbert, D. T.; Malone, P. S. (1995): The Correspondence Bias. Psychological Bulletin 117(1), 21–38 (Autorenkopie, Harvard)","oeffentlich":true,"url":"https://dtg.sites.fas.harvard.edu/Gilbert%20%26%20Malone%20%28CORRESPONDENCE%20BIAS%29.pdf","seite":"21","abruf":"2026-10-12"}],"thema":"Zusammenleben","pruefung":{"lauf":"quiz-audit-v8","modell":"claude-sonnet-5-5","datum":"2026-10-15","urteil":"korrigieren","pruefsumme":"3e597253fea6dacf"}},{"id":"qx-a2-006","clusterId":"A","werkstueckRef":"A.13","stufe":2,"question":"Welche Frage bringt dich am ehesten zu einer brauchbaren Erklärung seines Verhaltens?","scenario":"Dein Onkel lässt sich seit Monaten bei einem Energieheiler behandeln und geht für diese Beschwerden nicht mehr zum Arzt. Er ist sonst ein nüchterner, vernünftiger Mensch. Du willst verstehen, warum er so handelt.","options":["„Welche Belege gibt es für die Wirkung solcher Behandlungen, etwa Studien, Übersichtsarbeiten und Erfahrungsberichte?“","„Was verdient der Heiler an ihm, etwa durch Honorare, Zusatzverkäufe und Folgetermine, und was treibt ihn an?“","„Welche Wissenslücke hindert ihn, die fehlende Wirkung zu erkennen, etwa bei Placebo, Spontanheilung und Risiken?“","„Welches Problem löst der Heiler für ihn, etwa durch Zeit, Zuwendung, eine einfache Erzählung und Hoffnung?“"],"correctIndex":3,"explanation":"Wer ein Verhalten nur als Dummheit oder Charakterschwäche abtut, hat noch nichts erklärt. Die Frage nach dem Problem, das das Verhalten für die Person löst, macht sichtbar, was sie tatsächlich antreibt. Ein Heiler bietet oft ungeteilte Aufmerksamkeit, Empathie, eine verständliche Erzählung ohne Fachjargon und Hoffnung, wo die „Schulmedizin“ vielleicht nur noch von „Management“ spricht. Dann ist die Entscheidung des Onkels eher emotional und sozial rational als medizinisch dumm. Verstehen heißt dabei nicht gutheißen: Das Verständnis der Anreize ist der Schlüssel zu einem wirksamen Umgang mit dem Verhalten. Die Frage nach den Belegen klingt nach Sachlichkeit, klärt aber nur, ob die Methode wirkt, nicht, warum er sie wählt. Die Frage nach dem Verdienst des Heilers klingt nach gesundem Misstrauen, beschreibt aber dessen Motive, nicht die deines Onkels. Die Frage nach einer Wissenslücke klingt nach Aufklärung, übersieht aber, dass er sich sonst nüchtern und vernünftig verhält.","coreRule":"⚡ Frag, welches Bedürfnis ein Verhalten erfüllt, nicht, wie jemand so etwas glauben kann.","beleg":"Werkstück A.13 (Anwendung: Pseudomedizin; Aktivierungs-Frage)","status":"entwurf","kurz":"Wer sein Verhalten nur als Dummheit abtut, hat nichts erklärt. Fragst du, welches Problem der Heiler für deinen Onkel löst, etwa Zuwendung, Hoffnung und eine verständliche Erzählung, wird sichtbar, was ihn tatsächlich antreibt.","prueffrage":"Seit wann geht dein Onkel zum Heiler statt zum Arzt, und was hat sich für ihn damals verändert?","rueckmeldung":[{"option":0,"text":"Belege zu prüfen ist sinnvoll und sachlich. Sie zeigen aber nur, ob die Methode wirkt, nicht, warum dein Onkel sie wählt. Dafür musst du bei ihm und seiner Lage ansetzen."},{"option":1,"text":"Misstrauen gegenüber dem Heiler kann berechtigt sein. Seine Einnahmen und Motive erklären aber das Handeln des Heilers, nicht das deines Onkels. Gefragt ist, was ihn selbst antreibt."},{"option":2,"text":"Aufklärung kann hilfreich sein. Diese Frage unterstellt aber, dass es ihm an Wissen fehlt, und das passt schlecht zu einem sonst nüchternen, vernünftigen Menschen. So lässt sich sein Verhalten nicht erklären."}],"familie":"wohlwollend-verstehen","fertigkeit":"F3","quellen":[{"typ":"url","kurz":"Mercer, S. W.; Reilly, D.; Watt, G. C. M. (2002): The importance of empathy in the enablement of patients attending the Glasgow Homoeopathic Hospital. Br J Gen Pract 52(484), 901–905 (Abstract, PubMed)","oeffentlich":true,"url":"https://pubmed.ncbi.nlm.nih.gov/12434958/","abruf":"2026-10-12"},{"typ":"url","kurz":"Gilbert, D. T.; Malone, P. S. (1995): The Correspondence Bias. Psychological Bulletin 117(1), 21–38 (Autorenkopie, Harvard)","oeffentlich":true,"url":"https://dtg.sites.fas.harvard.edu/Gilbert%20%26%20Malone%20%28CORRESPONDENCE%20BIAS%29.pdf","seite":"21","abruf":"2026-10-12"}],"thema":"Gesundheit","pruefung":{"lauf":"quiz-audit-v4","modell":"claude-sonnet-5-5","datum":"2026-10-14","urteil":"korrigieren","pruefsumme":"b1de01a47e73850e"}},{"id":"qx-a2-007","clusterId":"A","werkstueckRef":"A.13","stufe":3,"question":"Ein Kollege wirft dir vor: „Wenn du erklärst, warum Menschen extremistischen Ideologien folgen, entschuldigst du sie.“ Welche Antwort trifft den Denkfehler in diesem Vorwurf am besten?","options":["Der Vorwurf setzt Erklären mit Entschuldigen gleich; eine Erklärung nennt Ursachen, eine Entschuldigung spricht frei, und wer Ursachen kennt, kann Verhalten gezielter bekämpfen.","Der Vorwurf verwechselt Wirkung und Absicht; eine Erklärung kann zwar entlastend wirken, entschuldigen würdest du die Menschen aber erst, wenn du genau das auch beabsichtigst.","Der Vorwurf übersieht den Zweck; eine Erklärung mag die Menschen ein Stück weit entschuldigen, doch dieser Preis lohnt sich, weil sie hilft, Extremismus wirksam vorzubeugen.","Der Vorwurf trifft nur einseitige Erklärungen; wer allein die Umstände nennt und die eigene Entscheidung ausblendet, entschuldigt tatsächlich, wer beides nennt, dagegen nicht."],"correctIndex":0,"explanation":"Der Vorwurf verwechselt zwei verschiedene Dinge: Verstehen, wie ein Verhalten zustande kommt, und Gutheißen, dass es richtig ist. Wer Anreize und Ursachen analysiert, beantwortet eine Sachfrage („Wie kommt es dazu?“), keine Wertungsfrage („Ist es in Ordnung?“). Man kann die systemischen Gründe für Rassismus untersuchen und ihn zugleich unmissverständlich bekämpfen. Ohne Verständnis der Ursachen bleibt die Gegenwehr dagegen oft wirkungslos, weil sie an den eigentlichen Anreizen vorbeigeht.","coreRule":"⚡ Anreize zu verstehen heißt nicht, das Verhalten gutzuheißen.","beleg":"Werkstück A.13 (Der Kipppunkt)","status":"entwurf","scenario":"","kurz":"Der Vorwurf mischt Sach- und Wertungsfrage: Wer erklärt, wie es zu Extremismus kommt, beantwortet nicht, ob er in Ordnung ist. Ursachen zu kennen spricht niemanden frei und hilft sogar, gezielter dagegen vorzugehen.","prueffrage":"Heißt eine Ärztin, die erklärt, wie eine Sucht entsteht, die Sucht damit gut?","rueckmeldung":[{"option":1,"text":"Dass eine Erklärung entlastend wirken kann, stimmt als Eindruck beim Zuhören. Entschuldigt wird dadurch aber nichts, auch nicht bei entsprechender Absicht: Eine Erklärung beantwortet die Frage nach dem Wie, nicht die nach dem Ob es in Ordnung ist."},{"option":2,"text":"Der Nutzen für die Vorbeugung ist real. Aber die Antwort lässt den Vorwurf in seinem Kern stehen: Erklären kostet hier keinen „Preis“, denn es entschuldigt gar nicht, auch nicht ein Stück weit."},{"option":3,"text":"Eine Erklärung, die Entscheidungen und Verantwortung ausblendet, ist unvollständig und kann so wirken, als entlaste sie. Trotzdem ist selbst die einseitige Erklärung keine Entschuldigung; der Fehler liegt schon in der Gleichsetzung von Erklären und Entschuldigen."}],"familie":"wohlwollend-verstehen","fertigkeit":"F3","quellen":[{"typ":"url","kurz":"Miller, A. G.; Gordon, A. K.; Buddie, A. M. (1999): Accounting for evil and cruelty: is to explain to condone? Personality and Social Psychology Review 3(3), 254–268 (Abstract, PubMed)","oeffentlich":true,"doi":"10.1207/s15327957pspr0303_8","url":"https://pubmed.ncbi.nlm.nih.gov/15661676/","abruf":"2026-10-12"}],"thema":"Zusammenleben","pruefung":{"lauf":"quiz-audit-v8","modell":"claude-sonnet-5-5","datum":"2026-10-15","urteil":"korrigieren","pruefsumme":"0016c58aa8518a70"}},{"id":"qx-a2-008","clusterId":"A","werkstueckRef":"A.13","stufe":4,"question":"Was ist an dieser Überlegung fehlerhaft, und was wäre der bessere nächste Schritt?","options":["Er schließt aus „Ich kenne den Zweck nicht“ auf „Es gibt keinen Zweck“; besser wäre, zuerst herauszufinden, wozu der Ablauf eingeführt wurde, und dann zu entscheiden.","Er begründet die Abschaffung nur mit seinem Eindruck; besser wäre, zuerst zu messen, wie viel Arbeitszeit der dreifache Formularlauf kostet, und dann zu entscheiden.","Er will den Formularlauf sofort ganz abschaffen; besser wäre, ihn zuerst einige Wochen probeweise auszusetzen und zu beobachten, ob etwas fehlt, und dann zu entscheiden.","Er entscheidet als Neuer zu früh; besser wäre, zuerst einige Monate in der Abteilung mitzuarbeiten, bis er die Abläufe aus eigener Erfahrung kennt, und dann zu entscheiden."],"correctIndex":0,"explanation":"Dass niemand den Zweck nennen kann, zeigt nur, dass er nicht bekannt ist, nicht dass es keinen gibt. Ein Ablauf, der aufwendig und lästig wirkt, kann trotzdem ein Problem lösen, das man von außen nicht sieht (zum Beispiel eine frühere Panne oder eine Prüfpflicht; das sind hier nur denkbare Beispiele, über den konkreten Fall ist nichts bekannt). Wer ihn abschafft, ohne das zu klären, riskiert, genau dieses Problem zurückzuholen. Das ist die Logik von Chestertons Zaun: Man reißt einen Zaun quer über dem Weg erst ein, wenn man weiß, wozu er gebaut wurde. Das ist kein Verbot der Änderung, sondern die Forderung, zuerst den Zweck zu verstehen. Chesterton sprach von Einrichtungen und Gesetzen; die Übertragung auf Arbeitsabläufe ist eine Erweiterung.","coreRule":"⚡ Aus „Ich sehe den Zweck nicht“ folgt nicht „Es gibt keinen“: Kläre erst, wozu etwas da ist, dann entscheide.","beleg":"Werkstück A.13 (Kontext & Tiefe); Fn. ga-chesterton (Chesterton 1929, The Thing, Nachdruck 1946, S. 29)","status":"entwurf","scenario":"Ein neuer Abteilungsleiter findet in seiner Abteilung einen dreifachen Formularlauf für jede Bestellung. Niemand kann ihm sagen, wozu er gut ist. Er sagt: „Das ist offensichtlich sinnloser Aufwand, ich schaffe das ab diese Woche ab.“","kurz":"Dass niemand den Zweck kennt, zeigt nur, dass er unbekannt ist, nicht dass es keinen gibt. Wer den Ablauf abschafft, ohne zu klären, wozu er eingeführt wurde, riskiert, ein unsichtbares Problem zurückzuholen.","prueffrage":"Seit wann arbeitet der Abteilungsleiter in dieser Abteilung, und wie viel von ihrer Geschichte kann er kennen?","rueckmeldung":[{"option":1,"text":"Eine Zeitmessung liefert zwar echte Zahlen und ist besser als ein bloßer Eindruck. Sie zeigt aber nur die Kosten; was der Ablauf bringt, bleibt unbekannt, und ohne diese Gegenseite lässt sich nichts abwägen."},{"option":2,"text":"Ein befristeter Test ist vorsichtiger als eine sofortige Abschaffung. Das Aussetzen ist aber selbst schon der Eingriff, und eine Panne oder fehlende Prüfung kann selten oder spät auftreten, sodass wenige Wochen sie womöglich nicht zeigen."},{"option":3,"text":"Geduld und Erfahrung helfen, einen Betrieb zu verstehen. Allgemeines Mitarbeiten garantiert aber nicht, dass der Zweck sichtbar wird, und ein Ablauf, der ihn nicht preisgibt, bleibt auch nach Monaten rätselhaft. Gezielt nachzuforschen, wozu er eingeführt wurde, führt direkter ans Ziel."}],"familie":"vorstellung-ist-kein-massstab","fertigkeit":"F2","quellen":[{"typ":"literatur","kurz":"Chesterton, G. K. (1929): The Thing. London: Sheed & Ward, Essay „The Drift from Domesticity“","oeffentlich":false}],"thema":"Zusammenleben","pruefung":{"lauf":"quiz-audit-v8","modell":"claude-sonnet-5-5","datum":"2026-10-15","urteil":"korrigieren","pruefsumme":"4f897135c9362d8a"}},{"id":"qx-a2-009","clusterId":"A","werkstueckRef":"A.14","stufe":2,"question":"Was ist an dieser Begründung fürs Weitermachen fehlerhaft, und welche Frage prüft stattdessen, ob du weitermachen solltest?","scenario":"Seit drei Jahren pflegst du die Website eines Vereins, die kaum jemand besucht. Du hast schon rund 400 Stunden hineingesteckt. Auf der nächsten Sitzung sagt ein Mitglied: „Nach all der Arbeit wäre es doch schade, jetzt aufzuhören. Mach weiter, dann hat sich alles gelohnt.“","options":["Sie stützt sich auf bereits geleistete Stunden, die sich nicht zurückholen lassen. Besser prüft die Frage: „Würde ich heute, ohne diese Vorgeschichte, mit dem Projekt anfangen?“","Sie stützt sich auf ein Gefühl statt auf Zahlen. Besser prüft die Frage: „Wie viele Besucher hatte die Seite im Schnitt pro Monat in den letzten drei Jahren?“","Sie stützt sich auf die Meinung eines einzelnen Mitglieds. Besser prüft die Frage: „Wie viele Mitglieder des Vereins wünschen sich, dass ich mit der Website weitermache?“","Sie stützt sich auf bloßes Durchhalten statt auf Verbesserung. Besser prüft die Frage: „Was müsste ich an der Seite ändern, damit sie endlich mehr Besucher anzieht?“"],"correctIndex":0,"explanation":"Das Argument begründet das Weitermachen mit dem, was schon investiert wurde: „Nach all der Arbeit …“. Das ist ein Red Flag der Versunkene-Kosten-Falle, denn die Begründung ist rückwärtsgewandt statt vorwärtsgewandt. Die Frage „Würde ich heute damit anfangen?“ blendet die Vergangenheit bewusst aus und bewertet ausschließlich die gegenwärtigen und zukünftigen Vor- und Nachteile. Lautet die Antwort „Nein“, ist das ein starkes Signal, dass dich nur die Vorgeschichte hält.","coreRule":"⚡ Frag nicht „Wie viel habe ich schon investiert?“, sondern „Würde ich heute damit anfangen?“","beleg":"Werkstück A.14 (Kernidee; Red Flags)","status":"entwurf","kurz":"Das Argument sagt nur, was schon investiert wurde, und blickt damit zurück. Ob Weitermachen sinnvoll ist, zeigt die Frage, ob du heute ohne die Vorgeschichte anfangen würdest. Antwortest du „Nein“, hält dich vermutlich nur das Bisherige.","prueffrage":"Was würde dem Verein fehlen, wenn die Website ab morgen nicht mehr gepflegt würde, und wer würde es bemerken?","rueckmeldung":[{"option":1,"text":"Zahlen helfen, die Lage einzuschätzen, und Besucherzahlen zählen dazu. Sie beschreiben aber nur die Vergangenheit. Der Fehler liegt in der rückwärtsgewandten Begründung, und die lässt sich mit diesen Zahlen nicht beheben."},{"option":2,"text":"Wie die Mitglieder zur Website stehen, ist durchaus interessant, ändert aber den Fehler nicht. Auch bei breiter Zustimmung bliebe das Argument rückwärtsgewandt, denn es verweist auf geleistete Stunden statt auf künftigen Nutzen."},{"option":3,"text":"Nach vorn zu schauen und Verbesserungen zu suchen, geht in die richtige Richtung. Die Frage setzt aber schon voraus, dass sich das Weitermachen lohnt. Ob es sich heute noch lohnt, prüft sie nicht."}],"familie":"versunkene-kosten","fertigkeit":"F4","quellen":[{"typ":"url","kurz":"Arkes, H. R.; Blumer, C. (1985): The Psychology of Sunk Cost. OBHDP 35(1), 124–140 (Kopie auf einem Kursserver der Universität Klagenfurt, nicht die Verlagsfassung)","oeffentlich":true,"doi":"10.1016/0749-5978(85)90049-4","url":"https://cognition.aau.at/bg/BA/Arkes%20%26%20Blumer%201985.pdf","seite":"124–125","abruf":"2026-10-12"}],"thema":"Zusammenleben","pruefung":{"lauf":"quiz-audit-v7","modell":"claude-sonnet-5-5","datum":"2026-10-14","urteil":"ok","pruefsumme":"ab2efdccd5e6fb42"}},{"id":"qx-a2-010","clusterId":"A","werkstueckRef":"A.14","stufe":3,"question":"Wer wendet die Null-Basis-Frage falsch an?","scenario":"Im vierten Jahr deines Medizinstudiums wird die Prüfungsphase hart. Du bist erschöpft und überlegst, ob du dir die sogenannte Null-Basis-Frage stellen solltest: „Würde ich heute, ohne meine bisherige Zeit zu zählen, noch einmal mit diesem Studium anfangen?“ Vier Kommilitonen schildern, wie sie die Frage nutzen.","options":["Jule bricht ab, weil ihr die Prüfungsphase zu anstrengend ist, obwohl sich an Ziel und Aussichten nichts geändert hat.","Tom wägt bei der Frage ausdrücklich auch die künftigen Vor- und Nachteile einer Fortsetzung ab.","Lena stellt die Frage auch einem Bekannten, der seit Jahren Geld in ein Hobbyprojekt steckt und überlegt, ob es sich künftig noch lohnt.","Jonas gibt eine liebgewonnene Gewohnheit auf, weil er auf die Frage ehrlich „Nein“ antwortet."],"correctIndex":0,"explanation":"Die Null-Basis-Frage soll versunkene Kosten und bloße Trägheit ausblenden und prüfen, ob eine Fortsetzung zu den heutigen Umständen und dem heutigen Wissen passt. Sie ist kein Freibrief, bei der ersten Anstrengung aufzugeben. Wer ein langes, schwieriges Vorhaben abbricht, obwohl sich nur die Mühe und nicht die Lage oder das Wissen geändert haben, wendet sie falsch an. Ausdauer ist für langfristige Ziele nötig. Tom, Lena und Jonas nutzen die Frage so, wie sie gedacht ist: Sie beurteilen die Zukunft statt der Vergangenheit und ziehen ehrlich Konsequenzen.","coreRule":"⚡ Der Check prüft veränderte Umstände, er ersetzt nicht Ausdauer bei Anstrengung.","beleg":"Werkstück A.14 (Der Kipppunkt)","status":"entwurf","quote":"","quoteLabel":"","kurz":"Die Null-Basis-Frage prüft, ob eine Fortsetzung zu heutigen Umständen und heutigem Wissen passt. Wer abbricht, nur weil es anstrengender wird, obwohl sich Lage und Wissen nicht geändert haben, verwechselt Mühe mit einem Grund zum Aufhören.","prueffrage":"Was weiß jede Person heute über ihr Vorhaben, das sie zu Beginn noch nicht wusste, und worauf stützt sie ihre Entscheidung?","rueckmeldung":[{"option":1,"text":"Die Frage blendet bereits investierte Zeit und Mühe aus, nicht die Zukunft. Gerade der Blick auf künftige Vor- und Nachteile ist ihr Zweck; wer so abwägt wie Tom, nutzt sie richtig."},{"option":2,"text":"Dass Lena die Frage auf das Hobbyprojekt eines Bekannten überträgt, wirkt zunächst ungewöhnlich. Die Frage zielt dort aber genau auf den künftigen Nutzen und lässt das bisher hineingesteckte Geld außen vor; das ist ihr Sinn."},{"option":3,"text":"Ein ehrliches „Nein“ ernst zu nehmen, ist gewollt, besonders bei Gewohnheiten, die oft nur aus Trägheit weiterlaufen. Dass Jonas Konsequenzen zieht, ist daher kein Fehler, sondern der Zweck der Frage."}],"familie":"versunkene-kosten","fertigkeit":"F4","quellen":[{"typ":"url","kurz":"Arkes, H. R.; Blumer, C. (1985): The Psychology of Sunk Cost. OBHDP 35(1), 124–140 (Kopie auf einem Kursserver der Universität Klagenfurt, nicht die Verlagsfassung)","oeffentlich":true,"doi":"10.1016/0749-5978(85)90049-4","url":"https://cognition.aau.at/bg/BA/Arkes%20%26%20Blumer%201985.pdf","seite":"125","abruf":"2026-10-12"}],"thema":"Psychologie","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"ok","pruefsumme":"65ba6fd81e60baf8"}},{"id":"qx-a2-011","clusterId":"A","werkstueckRef":"A.14","stufe":4,"question":"Eine Frau hängt seit zehn Jahren einer Lehre an, in die sie viel Geld und Lebenszeit gesteckt hat. Ein Freund fragt sie: „Stell dir vor, du hörtest heute zum ersten Mal davon. Würden dich die Beweise, die dir jetzt präsentiert werden, überzeugen, dein Leben dafür umzukrempeln?“ Warum ist diese Frage hier hilfreich, aber für sie zugleich besonders schwer zu beantworten?","options":["Sie prüft die Lehre allein anhand heutiger Beweise ohne Vorgeschichte; ein „Nein“ würde aber heißen, dass sie zehn Jahre lang falsch entschieden hat.","Sie prüft die Lehre allein anhand heutiger Beweise ohne Vorgeschichte; nach zehn Jahren kann sie sich aber kaum vorstellen, zum ersten Mal davon zu hören.","Sie prüft die Lehre allein anhand heutiger Beweise; schwer fällt das, weil ihre lange Treue zur Lehre dann nicht mehr als Beleg für sie zählen dürfte.","Sie prüft die Lehre allein anhand heutiger Beweise; ein „Nein“ verlangte aber, ihr Leben sofort umzukrempeln, und das ist nach zehn Jahren kaum machbar."],"correctIndex":0,"explanation":"Die Frage löscht die Vergangenheit aus der Entscheidungs-Gleichung: Nur heutige Belege und künftiger Nutzen zählen, bisherige Investitionen nicht mehr. Genau das macht sie stark gegen die Versunkene-Kosten-Falle. Bei lange gehegten Überzeugungen ist sie aber schwer anzuwenden, denn ein „Nein“ hieße, jahrelang an einer schlechten Entscheidung festgehalten zu haben. Das erzeugt kognitive Dissonanz, und um ihr Selbstbild als gute Entscheiderin zu schützen, suchen Menschen in dieser Lage oft lieber Gründe, an der Lehre festzuhalten.","coreRule":"⚡ Der Null-Basis-Check fragt: „Würde ich heute damit anfangen?“ Bei festgefahrenen Überzeugungen ist er kraftvoll, aber schwer anzuwenden.","beleg":"Werkstück A.14 (Anwendung: festgefahrene Überzeugungen; Verbindungen: Kognitive Dissonanz)","status":"entwurf","scenario":"","kurz":"Die Frage blendet die Vergangenheit aus und zählt nur heutige Belege, das macht sie stark gegen die Versunkene-Kosten-Falle. Schwer fällt sie, weil ein „Nein“ hieße, zehn Jahre lang falsch entschieden zu haben, und dagegen wehrt sich das Selbstbild.","prueffrage":"Was soll die Frau nach der Frage ihres Freundes in ihre Antwort einbeziehen, und was ausdrücklich nicht?","rueckmeldung":[{"option":1,"text":"Sich vorzustellen, zum ersten Mal von etwas zu hören, ist eine Denkübung und bleibt auch nach zehn Jahren möglich. Schwer ist nicht die Fantasie, sondern was ein „Nein“ über ihre frühere Entscheidung bedeuten würde."},{"option":2,"text":"Dass ihre Treue nicht als Beleg zählt, ist genau der Zweck der Frage, nicht die Hürde. Das eigentliche Hindernis ist, dass ein „Nein“ ihr Bild von sich als guter Entscheiderin erschüttert."},{"option":3,"text":"Die Frage ist eine Gedankenprobe und verlangt keinen sofortigen Umbruch. Wie schwer ein Ausstieg praktisch wäre, ist eine spätere Sorge. Hier erschwert schon das ehrliche Antworten selbst, weil ein „Nein“ jahrelanges Festhalten an einer schlechten Entscheidung einräumt."}],"familie":"versunkene-kosten","fertigkeit":"F4","quellen":[{"typ":"url","kurz":"Harmon-Jones, E.; Mills, J. (2019): An Introduction to Cognitive Dissonance Theory and an Overview of Current Perspectives on the Theory. In: Harmon-Jones, E. (Hg.): Cognitive Dissonance, 2. Aufl., APA (Leseprobe auf apa.org)","oeffentlich":true,"doi":"10.1037/0000135-001","url":"https://www.apa.org/pubs/books/Cognitive-Dissonance-Intro-Sample.pdf","seite":"3; 6–7","abruf":"2026-10-12"},{"typ":"url","kurz":"Arkes, H. R.; Blumer, C. (1985): The Psychology of Sunk Cost. OBHDP 35(1), 124–140 (Kopie auf einem Kursserver der Universität Klagenfurt, nicht die Verlagsfassung)","oeffentlich":true,"doi":"10.1016/0749-5978(85)90049-4","url":"https://cognition.aau.at/bg/BA/Arkes%20%26%20Blumer%201985.pdf","seite":"124","abruf":"2026-10-12"},{"typ":"doi","kurz":"Festinger, L. (1957): A Theory of Cognitive Dissonance. Stanford University Press","oeffentlich":false,"doi":"10.1515/9781503620766"}],"thema":"Psychologie","pruefung":{"lauf":"quiz-audit-v8","modell":"claude-sonnet-5-5","datum":"2026-10-15","urteil":"ok","pruefsumme":"5bcc4276d4920523"}},{"id":"qx-a2-012","clusterId":"A","werkstueckRef":"A.15","stufe":1,"question":"Eine Kollegin sagt: „Ein Schluss ist genau dann deduktiv, wenn er vom Allgemeinen zum Besonderen geht, und genau dann induktiv, wenn er vom Besonderen zum Allgemeinen geht.“ Du sollst prüfen, ob das stimmt. Welche Frage trennt deduktive und induktive Schlüsse am besten?","options":["Geht der Schluss von „alle A“ auf einen Einzelfall oder von mehreren Einzelfällen auf alle, also vom Allgemeinen zum Besonderen oder umgekehrt? Daran erkennt man zuverlässig die Schlussart.","Muss die Konklusion bei wahren Prämissen wahr sein (wie bei A, B und C) oder bleibt sie nur wahrscheinlich (wie bei der nächsten Spinne)? Daran erkennt man zuverlässig die Schlussart.","Stützt sich der Schluss auf Allaussagen mit „alle“ (wie bei A, B und C) oder auf einzelne Beobachtungen (wie bei den zehn Spinnen)? Daran erkennt man zuverlässig die Schlussart.","Arbeitet der Schluss mit abstrakten Begriffen (wie bei A, B und C) oder mit Erfahrungen aus der Wirklichkeit (wie bei den Spinnen)? Daran erkennt man zuverlässig die Schlussart."],"correctIndex":1,"explanation":"Die Richtungsregel scheitert an beiden Beispielen. Schluss (1) ist deduktiv, bleibt aber zwischen allgemeinen Sätzen. Schluss (2) ist induktiv, bleibt aber bei Einzelfällen, nämlich von bisher untersuchten Spinnen auf die nächste. Verlässlich trennt etwas anderes: Bei einem deduktiven Schluss muss die Konklusion wahr sein, wenn die Prämissen wahr sind. Bei einem induktiven Schluss bleibt sie auch bei wahren Prämissen nur wahrscheinlich, denn die nächste Spinne könnte eine Ausnahme sein. Die Richtung ist deshalb nur eine Faustregel.","coreRule":"⚡ Deduktion zwingt, Induktion macht wahrscheinlich; die Richtung ist nur eine Faustregel.","beleg":"Werkstück A.15 (Kernidee); Fn. ga-deduktion-richtung (Shanahan, Internet Encyclopedia of Philosophy, Abschn. 9)","status":"entwurf","scenario":"Zwei Schlüsse zur Prüfung:\\n(1) „Alle A sind B, alle B sind C, also sind alle A auch C.“\\n(2) „Die zehn Spinnen, die ich bisher untersucht habe, haben acht Beine. Also hat auch die nächste Spinne, die ich finde, acht Beine.“","kurz":"Deduktiv ist ein Schluss, wenn die Konklusion bei wahren Prämissen wahr sein muss, induktiv, wenn sie nur wahrscheinlich bleibt. Die Richtung ist nur eine Faustregel und scheitert an beiden Beispielen.","prueffrage":"Wovon handeln Prämissen und Konklusion in Schluss (1) und in Schluss (2): von allen Fällen einer Art oder von einzelnen Dingen?","rueckmeldung":[{"option":0,"text":"Das ist die Regel der Kollegin selbst, und sie trifft oft zu. Doch Schluss (1) bleibt zwischen allgemeinen Sätzen und ist deduktiv, Schluss (2) geht von Einzelfällen auf einen Einzelfall und ist induktiv."},{"option":2,"text":"In den beiden Beispielen passt das zufällig. Aus Allaussagen lässt sich aber auch bloß wahrscheinlich schließen, und aus Einzelfällen zwingend. Die Satzform sagt nicht, ob die Konklusion folgen muss."},{"option":3,"text":"Ob ein Schluss von Begriffen oder von Erfahrung handelt, betrifft nur seinen Inhalt. Ein zwingender Schluss kann von Spinnen handeln, ein bloß wahrscheinlicher von abstrakten Größen. Die Art des Schlusses hängt daran nicht."}],"familie":"schluss-pruefen","fertigkeit":"F2","quellen":[{"typ":"url","kurz":"Shanahan, T.: Deductive and Inductive Arguments. Internet Encyclopedia of Philosophy","oeffentlich":true,"url":"https://iep.utm.edu/deductive-inductive-arguments/","abruf":"2026-10-07"}],"thema":"Geschichte und Wissenschaft","pruefung":{"lauf":"quiz-audit-v8","modell":"claude-sonnet-5-5","datum":"2026-10-15","urteil":"ok","pruefsumme":"d70b0e5ad8660178"}},{"id":"qx-a2-013","clusterId":"A","werkstueckRef":"A.15","stufe":2,"question":"Was ist an diesem Schluss falsch?","scenario":"Dein Mitbewohner kommt nass nach Hause. Du denkst: „Wenn es regnet, wird man nass. Er ist nass. Also hat es geregnet.“","options":["Er ist ungültig, weil er den Regen schon voraussetzt: Die Regel beginnt mit dem Regen, und am Ende steht wieder nur der Regen als Ergebnis.","Er ist ungültig, weil dein Mitbewohner auch aus anderem Grund nass sein kann und „Es hat geregnet“ daher nicht zwingend folgt.","Er ist ungültig, weil ein Anzeichen allein nicht reicht; wäre auch die Straße vor dem Haus nass, folgte „Es hat geregnet“ zwingend.","Er ist ungültig, weil schon die Regel nicht stimmt: Wer bei Regen einen Schirm dabeihat, bleibt trocken, also trägt auch der Schluss nicht."],"correctIndex":1,"explanation":"„Wenn es regnet, wird man nass“ und „Er ist nass“ erlauben nicht den Schluss „Es hat geregnet“: Das ist der klassische Fehlschluss der Bejahung der Folge. Nass kann auch jemand sein, den ein Rasensprenger getroffen hat oder der mit einem Eimer übergossen wurde. Eine gültige Deduktion wäre zwingend; diese ist es nicht. Verallgemeinert wird hier nichts, denn der Schluss geht von einer Regel auf einen Einzelfall. Ein Zirkelschluss liegt auch nicht vor, denn „Es hat geregnet“ steht in der ersten Aussage nicht als Behauptung, sondern nur als Bedingung. Und von ausbleibendem Regen ist gar nicht die Rede.","coreRule":"⚡ Aus „Wenn A, dann B“ und „B“ folgt nicht „A“.","beleg":"Werkstück A.15 (Denkweg 1); Fn. ga-bejahung (Dowden, Internet Encyclopedia of Philosophy, „Affirming the Consequent“)","status":"entwurf","kurz":"Aus „Bei Regen wird man nass“ und „Er ist nass“ folgt nicht zwingend „Es hat geregnet“. Nass werden kann man auch durch einen Rasensprenger oder einen Eimer Wasser; die Regel läuft nur in eine Richtung.","prueffrage":"Ist die Straße vor der Tür nass, und sind andere, die gerade von draußen kommen, ebenfalls nass?","rueckmeldung":[{"option":0,"text":"Der Regen kommt in der Regel und im Schluss vor, daher wirkt es wie eine Runde. In der Regel steht er aber nur als Bedingung, nicht als Behauptung; der Schluss ist ungültig, weil man die Regel nicht umkehren darf."},{"option":2,"text":"Ein einzelnes Anzeichen bringt noch keine Sicherheit, das stimmt. Auch eine nasse Straße ließe sich aber anders erklären, etwa durch eine Straßenreinigung. Weitere Indizien machen den Regen wahrscheinlicher, zwingend machen sie ihn nie."},{"option":3,"text":"Ein Schirm kann tatsächlich trocken halten, doch hier gilt die Regel als Voraussetzung. Selbst wenn sie ausnahmslos stimmte, bliebe der Schluss ungültig, denn er kehrt die Regel um: Aus „Regen führt zu nass“ folgt nicht „nass führt zu Regen“."}],"familie":"schluss-pruefen","fertigkeit":"F2","quellen":[{"typ":"url","kurz":"Dowden, B.: Fallacies, Eintrag „Affirming the Consequent“. Internet Encyclopedia of Philosophy","oeffentlich":true,"url":"https://iep.utm.edu/fallacy/","abruf":"2026-10-07"}],"thema":"Zusammenleben","pruefung":{"lauf":"quiz-audit-v8","modell":"claude-sonnet-5-5","datum":"2026-10-15","urteil":"korrigieren","pruefsumme":"02df9fd0fc1a8a3d"}},{"id":"qx-a2-014","clusterId":"A","werkstueckRef":"A.15","stufe":3,"question":"Ein Mitglied einer Gruppe argumentiert: „Alles, was unser Anführer sagt, ist wahr. Der Anführer sagt, die Welt gehe nächste Woche unter. Also geht sie unter.“ Du sollst die Schwachstelle benennen. Wo setzt du an?","options":["Bei der Form des Schlusses: Aus „Der Anführer sagt es“ folgt nicht, dass es wahr ist, also ist der Schluss logisch ungültig.","Bei der Konklusion: Ein Weltuntergang nächste Woche ist so unwahrscheinlich, dass der Schluss schon an seinem Ergebnis scheitert.","Beim Mitglied selbst: Wer seinem Anführer so bedingungslos folgt, ist befangen, also muss man sein Argument kaum inhaltlich prüfen.","Bei der ersten Aussage: Der Schluss folgt sauber aus ihr, aber niemand hat belegt, dass der Anführer immer recht hat."],"correctIndex":3,"explanation":"Formal ist der Schluss gültig: Wenn wirklich alles wahr ist, was der Anführer sagt, und er den Weltuntergang ankündigt, dann folgt der Weltuntergang zwingend. Der Aufbau entspricht dem klassischen „Alle Menschen sind sterblich, Sokrates ist ein Mensch, also ist Sokrates sterblich“. Ein gültiger Schluss ist aber nur so verlässlich wie seine Ausgangsaussage, und genau die ist hier unbelegt und in dieser Absolutheit kaum haltbar: Kein Mensch irrt nie. Wer nur die Form prüft, findet keinen Fehler und lässt das Gedankengebäude unangetastet. Die Prüfung muss bei der Prämisse ansetzen: Woher weiß man, dass der Anführer immer recht hat, und gibt es Belege für das Gegenteil, etwa frühere Vorhersagen, die nicht eingetroffen sind?","coreRule":"⚡ Prüfe bei einem logischen Argument immer auch die Prämissen, nicht nur die Form.","beleg":"Werkstück A.15 (Anwendung: Sekten & Kulte; Red Flags; Der Kipppunkt)","status":"entwurf","scenario":"","kurz":"Der Schluss ist formal gültig, trägt aber nur so weit wie seine Ausgangsaussage. Wer bloß die Form prüft, findet keinen Fehler. Prüfen muss man, ob der Anführer wirklich immer recht hat.","prueffrage":"Wenn die erste und die zweite Aussage stimmen, muss dann auch die dritte stimmen?","rueckmeldung":[{"option":0,"text":"Dass „Der Anführer sagt es“ noch keine Wahrheit beweist, ist richtig. Der Schluss ist aber trotzdem gültig: Wenn die erste Aussage stimmte, folgte der Rest zwingend. Gerade diese Aussage ist unbelegt."},{"option":1,"text":"Dass ein Weltuntergang nächste Woche äußerst unwahrscheinlich ist, ist ein berechtigtes Warnsignal. Aber ein unplausibles Ergebnis zeigt nicht, wo der Fehler steckt. Das lässt sich nur an der Ausgangsaussage über den Anführer klären."},{"option":2,"text":"Bedingungslose Gefolgschaft macht ein Argument verdächtig, aber noch nicht falsch. Ob die Behauptung hält, zeigt nur ihre inhaltliche Prüfung. Wer sie überspringt, bewertet die Person statt das Argument."}],"familie":"schluss-pruefen","fertigkeit":"F2","quellen":[{"typ":"url","kurz":"Shanahan, T.: Deductive and Inductive Arguments. Internet Encyclopedia of Philosophy","oeffentlich":true,"url":"https://iep.utm.edu/deductive-inductive-arguments/","abruf":"2026-10-07"}],"thema":"Zusammenleben","pruefung":{"lauf":"quiz-audit-v8","modell":"claude-sonnet-5-5","datum":"2026-10-15","urteil":"ok","pruefsumme":"fae9b0c4ab10dfbc"}},{"id":"qx-a2-015","clusterId":"A","werkstueckRef":"A.15","stufe":4,"question":"Welche Aussage über den Schluss der Ärztin ist richtig?","options":["Sie schließt auf die beste Erklärung aller Beobachtungen; das Ergebnis ist nur wahrscheinlich und kann durch weitere Befunde widerlegt werden.","Sie verallgemeinert aus vielen beobachteten Fällen eine neue Regel (Induktion); je mehr Fälle vorliegen, desto besser ist die Regel gestützt.","Sie wendet eine bekannte Regel auf diesen Einzelfall an (Deduktion); dabei steckt die Schlussfolgerung schon vollständig in den Prämissen.","Sie lässt sich von den Grippefällen in der Nachbarschaft leiten (Verfügbarkeitsfehler); dadurch überschätzt sie, wie wahrscheinlich Grippe ist."],"correctIndex":0,"explanation":"Der Schluss geht von mehreren Beobachtungen auf die Erklärung, die sie am besten verbindet. Er liefert nur Wahrscheinliches: Fieber, Husten und Gliederschmerzen passen auch zu anderen Erkrankungen, und ein weiterer Befund, etwa ein negativer Test, könnte die Diagnose kippen. Man nennt das einen Schluss auf die beste Erklärung; er ist eng verwandt mit dem, was der Philosoph Charles S. Peirce Abduktion nannte. Eine Induktion bildet aus vielen Fällen eine Regel, hier wird aber eine Diagnose für einen einzelnen Patienten gestellt. Bei einer Deduktion läge die Diagnose schon in den Prämissen, hier steht sie aber nirgends fest.","coreRule":"⚡ Frag bei einem Schluss auf eine Ursache: Ist er zwingend oder nur wahrscheinlich, und welche Erklärung passt zu allen Beobachtungen am besten?","beleg":"Werkstück A.15 (Denkweg 2); Fn. ga-abduktion (Douven, Stanford Encyclopedia of Philosophy, „Abduction“, Abschn. 1.1)","status":"entwurf","scenario":"Eine Ärztin sieht einen Patienten mit Fieber, Husten und Gliederschmerzen. In der Nachbarschaft sind mehrere Grippefälle bekannt. Sie schließt: „Das ist sehr wahrscheinlich Grippe.“","kurz":"Die Ärztin sucht die Erklärung, die Fieber, Husten, Gliederschmerzen und die Grippefälle ringsum am besten verbindet. Das ergibt nur Wahrscheinliches, denn die Symptome passen auch zu anderem, und ein negativer Test könnte die Diagnose kippen.","prueffrage":"Worauf stützt die Ärztin ihr Urteil im Einzelnen, und was davon hat sie selbst gezählt oder getestet?","rueckmeldung":[{"option":1,"text":"Dass mehr Fälle eine Regel besser stützen, stimmt. Hier entsteht aber keine neue Regel, sondern eine Diagnose für einen einzelnen Patienten: Gesucht wird die Erklärung für seine Symptome, nicht ein Gesetz über alle Fälle."},{"option":2,"text":"Eine bekannte Regel auf einen Einzelfall anzuwenden, klingt nach sicherer Diagnose. Doch Fieber, Husten und Gliederschmerzen passen auch zu anderen Erkrankungen, die Diagnose steht also in keiner Prämisse fest, und ein negativer Test könnte sie kippen."},{"option":3,"text":"Auffällige Fälle in der Umgebung können das Urteil tatsächlich verzerren, deshalb liegt der Gedanke nah. Im Szenario stützen aber drei passende Symptome die Diagnose, und die Ärztin sagt nur „sehr wahrscheinlich“. Für eine Überschätzung gibt es dort keinen Anhaltspunkt."}],"familie":"sparsamste-erklaerung","fertigkeit":"F4","quellen":[{"typ":"url","kurz":"Douven, I.: Abduction. Stanford Encyclopedia of Philosophy (überarb. 2025)","oeffentlich":true,"url":"https://plato.stanford.edu/entries/abduction/","abruf":"2026-10-07"}],"thema":"Gesundheit","pruefung":{"lauf":"quiz-audit-v8","modell":"claude-sonnet-5-5","datum":"2026-10-15","urteil":"korrigieren","pruefsumme":"d0e1deaf7552482c"}},{"id":"qx-a2-016","clusterId":"A","werkstueckRef":"A.16","stufe":1,"question":"Zwei Menschen streiten heftig darüber, ob ein bestimmtes Nahrungsergänzungsmittel Krebs heilt. Die eine Person verweist auf mehrere unabhängige Studien, die andere sagt: „Mein Bauchgefühl und der Rat meines Gurus sagen mir, dass es wirkt.“ Der Streit dreht sich im Kreis. Was ist die hilfreichste Reaktion?","options":["Beide tragen weitere Studien und Einzelberichte zum Mittel zusammen, bis die Faktenlage auf einer Seite so erdrückend ist, dass die andere sie nicht mehr ablehnen kann.","Beide klären zuerst, mit welchem Verfahren sich bei einem angeblichen Krebsmittel zuverlässig zwischen Wirkung und Einbildung unterscheiden lässt.","Beide prüfen zuerst, ob hinter den Studien finanzielle Interessen stehen, weil Geldgeber Ergebnisse beeinflussen können, und werten sie danach neu aus.","Beide einigen sich auf eine Mittelposition, etwa dass das Mittel vielleicht ein wenig wirkt, damit sich jede Seite im Ergebnis wiederfinden kann."],"correctIndex":1,"explanation":"Wenn zwei Seiten ihre Behauptungen mit völlig unterschiedlichen Verfahren rechtfertigen (hier: überprüfbare Daten gegen Bauchgefühl und Autorität), führt ein Streit über Einzelfakten selten weiter, denn jede Seite lässt andere Belege gelten. Erst wenn geklärt ist, welches Verfahren die Frage überhaupt entscheiden kann, kommt man weiter. Ob ein Stoff Krebs heilt, lässt sich nur mit öffentlich überprüfbaren Daten, Beobachtungen und Experimenten klären: Intuition kann helfen einzuschätzen, ob man einer Person vertraut, aber nicht, ob ein Molekül einen Tumor heilt. Mehr Studien und Berichte zu sammeln ändert daran nichts, solange das Verfahren strittig ist. Die Geldgeber von Studien zu prüfen ist sonst ein guter Schritt, hier aber sind die Studien als unabhängig beschrieben, und die andere Seite lässt Studien ohnehin nicht als Maßstab gelten. Und eine Mittelposition hilft bei einer prüfbaren Sachfrage nicht, weil Entgegenkommen nicht entscheidet, ob ein Stoff wirkt.","coreRule":"⚡ Frag nicht nur „Was weißt du?“, sondern „Woher weißt du es?“ Wer über die Methode der Wahrheitsfindung streitet, streitet nicht mehr im Kreis.","beleg":"Werkstück A.16 (Kernidee; Kontext & Tiefe)","status":"entwurf","scenario":"","kurz":"Der Streit kommt erst voran, wenn beide klären, womit sich die Frage überhaupt entscheiden lässt. Solange eine Seite Daten, die andere Bauchgefühl und Autorität gelten lässt, ändern auch mehr Belege nichts.","prueffrage":"Was hat der bisherige Austausch von Argumenten bewirkt, und woran ist er jedes Mal hängengeblieben?","rueckmeldung":[{"option":0,"text":"Mehr Studien zu sammeln wirkt gründlich. Wer Bauchgefühl und Autorität als Maßstab gelten lässt, wird aber auch erdrückend viele Daten beiseiteschieben. Solange das Verfahren strittig ist, ändert zusätzliches Material nichts."},{"option":2,"text":"Geldgeber zu prüfen ist sonst ein guter Schritt, weil Finanzierung Ergebnisse färben kann. Hier sind die Studien aber als unabhängig beschrieben, und das Problem liegt tiefer: Die andere Seite lässt Studien ohnehin nicht als Maßstab gelten."},{"option":3,"text":"Eine Mitte zu suchen wirkt fair und entschärft den Streit. Ob ein Stoff Krebs heilt, ist aber eine prüfbare Sachfrage, und die klärt sich nicht durch Entgegenkommen. Ein „vielleicht ein wenig“ wäre eine Behauptung, die niemand belegt hat."}],"familie":"nach-weg-und-kriterium-fragen","fertigkeit":"F3","quellen":[{"typ":"url","kurz":"Hansson, S. O.: Science and Pseudo-Science. Stanford Encyclopedia of Philosophy","oeffentlich":true,"url":"https://plato.stanford.edu/entries/pseudo-science/","abruf":"2026-10-07"}],"thema":"Gesundheit","pruefung":{"lauf":"quiz-audit-v4","modell":"claude-sonnet-5-5","datum":"2026-10-14","urteil":"korrigieren","pruefsumme":"3449e15b53685717"}},{"id":"qx-a2-017","clusterId":"A","werkstueckRef":"A.16","stufe":2,"question":"Was ist jetzt der klügste nächste Schritt?","scenario":"Du diskutierst seit einer Stunde mit einem Bekannten über einen Verschwörungsmythos. Du bringst Studien, er winkt ab: „Die gehören doch alle zum System.“ Jede neue Quelle wird auf dieselbe Weise abgelehnt.","options":["Die aussagekräftigste Studie heraussuchen und ihre Methode Schritt für Schritt erklären, damit er die Belege endlich versteht und anerkennt.","Euch auf eine Mittelposition einigen, etwa dass an dem Mythos ein wahrer Kern sein könnte, damit das Gespräch freundlich endet.","Zuerst über die Methode sprechen: Welches Verfahren halten wir beide in dieser Frage für das verlässlichste, und was würde ihn umstimmen?","Nachzeichnen, wer den Mythos zuerst verbreitet hat und welche Interessen dahinterstanden, damit er die Herkunft der Behauptung einordnen kann."],"correctIndex":2,"explanation":"Wenn jede Gegenevidenz von vornherein als Teil der Verschwörung gilt, können weitere Fakten nichts bewirken: Ihr benutzt zwei verschiedene Verfahren, um zwischen wahr und falsch zu unterscheiden. Solange das nicht geklärt ist, redet ihr aneinander vorbei, weil jede Seite andere Beweise gelten lässt. Sinnvoll ist deshalb, zuerst die Methode zu besprechen: Wie lässt sich in dieser Art von Frage am verlässlichsten die Wahrheit herausfinden, und unter welchen Umständen würde er seine Meinung ändern? Eine einzelne Studie genauer zu erklären hilft nicht, denn er zweifelt nicht am Verständnis, sondern lehnt die Quellen als Gruppe ab. Eine Mittelposition passt nicht, weil es bei einer Sachfrage kein halbes Wahr gibt. Und die Herkunft des Mythos zu erzählen liefert nur weiteren Stoff, den er auf dieselbe Weise abtun würde.","coreRule":"⚡ Wenn Fakten nichts bewirken, klärt zuerst die Methode der Wahrheitsfindung.","quote":"","quoteLabel":"","beleg":"Werkstück A.16 (Anwendung; Red Flags; Anti-Denkmuster)","status":"entwurf","kurz":"Wenn jede Gegenevidenz schon als Teil der Verschwörung gilt, bewirken weitere Fakten nichts, denn ihr nutzt verschiedene Verfahren für wahr und falsch. Klärt deshalb zuerst die Methode und was ihn umstimmen würde.","prueffrage":"Wie hat er auf jede bisher genannte Studie reagiert, und hat sich daran im Lauf der Stunde etwas geändert?","rueckmeldung":[{"option":0,"text":"Eine gut erklärte Methode wirkt wie der Schlüssel zum Verständnis. Er zweifelt aber nicht am Verständnis, sondern lehnt Studien als Gruppe ab; auch die beste würde auf dieselbe Weise abgetan."},{"option":1,"text":"Ein freundliches Ende ist ein guter Wunsch. Bei einer Sachfrage gibt es aber kein halbes Wahr, und der Kompromiss ließe die zwei verschiedenen Verfahren unberührt, mit denen ihr wahr und falsch unterscheidet."},{"option":3,"text":"Wer den Ursprung eines Mythos kennt, kann ihn oft besser einordnen. Hier liefert die Herkunft aber nur weiteren Stoff, den er mit „gehört zum System“ genauso abtun würde wie die Studien."}],"familie":"nach-weg-und-kriterium-fragen","fertigkeit":"F3","quellen":[{"typ":"url","kurz":"Hansson, S. O.: Science and Pseudo-Science. Stanford Encyclopedia of Philosophy","oeffentlich":true,"url":"https://plato.stanford.edu/entries/pseudo-science/","abruf":"2026-10-07"}],"thema":"Zusammenleben","pruefung":{"lauf":"quiz-audit-v4","modell":"claude-sonnet-5-5","datum":"2026-10-14","urteil":"korrigieren","pruefsumme":"b1327fd91946ba97"}},{"id":"qx-a2-018","clusterId":"A","werkstueckRef":"A.16","stufe":3,"question":"Du steigst in ein Flugzeug und vertraust der Pilotin, ohne ihre Berechnungen nachzuprüfen. Ein Bekannter sagt: „Das ist doch genauso unkritisch wie der blinde Glaube an einen Guru. Wer wirklich rational ist, vertraut nur dem, was er selbst überprüft hat.“ Was ist an seinem Einwand fehlerhaft?","options":["Er setzt Vertrauen in Fachleute mit blindem Guruglauben gleich, obwohl entscheidend ist, ob eine Quelle nachprüfbar, korrigierbar und zur Frage passend ist (falsche Analogie).","Er stellt dein Vertrauen in die Pilotin als blinden Glauben dar, den du so gar nicht vertreten hast, und kritisiert dann dieses Zerrbild statt deiner Haltung (Strohmannargument).","Er legt selbst fest, wer „wirklich“ rational ist, und schließt damit Vertrauen ohne eigene Prüfung schon vorab aus der Vernunft aus (Kein-wahrer-Schotte-Argument).","Er verlangt, dass du dein Vertrauen erst durch eigene Prüfung belegst, statt selbst zu zeigen, was an der Pilotin fragwürdig sein soll (Umkehr der Beweislast)."],"correctIndex":0,"explanation":"Vertrauen ohne eigene Nachprüfung ist nicht automatisch ein Denkfehler. Einer erfahrenen Pilotin vertrauen wir, weil ihr Können geprüft wurde, ihre Arbeit kontrolliert wird und Fehler auffallen und korrigiert werden können. Beim Guru gilt dagegen oft: Zweifel ist verboten, und widersprüchliche Evidenz wird umgedeutet, bis sie wieder zur Lehre passt. Der Bekannte gleicht beide Fälle einander an, obwohl sie sich in genau diesen Merkmalen unterscheiden. Entscheidend ist also, ob die Quelle nachprüfbar und korrigierbar ist und ob die Methode zur Art der Frage passt. Problematisch wird es dort, wo Bauchgefühl oder unprüfbare Autorität Sachfragen beantworten sollen, etwa ob ein Molekül ein Krebsgeschwür heilt oder ob Impfungen sicher sind.","coreRule":"⚡ Vertrauen in Autorität und Intuition ist nicht per se falsch: Es kommt darauf an, ob die Quelle nachprüfbar und korrigierbar ist und zur Art der Frage passt. Fragen, die nur Daten beantworten, entscheiden weder Gefühl noch Guru.","beleg":"Werkstück A.16 (Der Kipppunkt)","status":"entwurf","scenario":"","kurz":"Vertrauen ohne eigene Nachprüfung ist nicht schon deshalb Guruglaube. Die Pilotin wird geprüft und kontrolliert, Fehler können auffallen und korrigiert werden; beim Guru ist Zweifel oft verboten. Der Einwand ebnet genau diesen Unterschied ein.","prueffrage":"Wie viel von dem, was der Bekannte täglich für wahr hält, hat er selbst überprüft?","rueckmeldung":[{"option":1,"text":"Der Vergleich mit dem Guru wirkt überzogen, deshalb liegt „Zerrbild“ nahe. Der Bekannte erfindet aber nichts hinzu, sondern setzt zwei verschiedene Fälle gleich. Der Fehler steckt in dieser Gleichsetzung, nicht in einer verdrehten Darstellung deiner Haltung."},{"option":2,"text":"„Wer wirklich rational ist“ klingt nach einer Definition, die Gegenbeispiele wegschiebt, und diese Formulierung ist tatsächlich angreifbar. Der zentrale Fehler liegt aber früher: Er gleicht Pilotin und Guru einander an, obwohl sie sich in Prüfbarkeit und Korrigierbarkeit unterscheiden."},{"option":3,"text":"Er verlangt zwar, dass du Prüfung nachweist, behauptet aber nichts über die Pilotin, das er belegen müsste. Eine Beweislast wird hier nicht verschoben. Der Fehler liegt darin, dass er Vertrauen ohne eigene Prüfung pauschal mit blindem Glauben gleichsetzt."}],"familie":"autoritaet-pruefen","fertigkeit":"F2","quellen":[{"typ":"url","kurz":"Stanford Encyclopedia of Philosophy: Epistemological Problems of Testimony (2021)","oeffentlich":true,"url":"https://plato.stanford.edu/entries/testimony-episprob/","abruf":"2026-10-12"},{"typ":"url","kurz":"Hansson, S. O.: Science and Pseudo-Science. Stanford Encyclopedia of Philosophy","oeffentlich":true,"url":"https://plato.stanford.edu/entries/pseudo-science/","abruf":"2026-10-07"}],"thema":"Geschichte und Wissenschaft","pruefung":{"lauf":"quiz-audit-v8","modell":"claude-sonnet-5-5","datum":"2026-10-15","urteil":"korrigieren","pruefsumme":"e3616c3c9cc1eeb3"}},{"id":"qx-a2-019","clusterId":"A","werkstueckRef":"A.16","stufe":4,"question":"Welche Frage deckt am besten auf, ob die Behauptung des Anbieters wissenschaftlich begründet ist oder nur so klingt?","options":["Wie anerkannt ist der Entwickler der Methode in seinem Fachgebiet, und seit wann ist er dort tätig?","Wie viele Kundinnen und Kunden haben die Methode angewendet, und wie zufrieden waren sie im Durchschnitt?","Wie schlüssig und widerspruchsfrei erklärt der Anbieter, warum die Methode wirken soll, und wie fachkundig klingt das?","Unter welchen Ergebnissen wäre die Methode widerlegt, und kann das jemand unabhängig vom Anbieter nachprüfen?"],"correctIndex":3,"explanation":"Entscheidend ist die Methode der Begründung, nicht das Vokabular. Der Anbieter ahmt die Sprache der Wissenschaft nach (Studien, Fachjargon), stützt sich aber auf Autorität (den Entwickler) und Intuition (die Erlebnisberichte der Kunden). Eine wissenschaftliche Begründung erkennt man an zwei Merkmalen: Sie ist falsifizierbar, man kann also sagen, welches Ergebnis sie widerlegen würde, und sie ist öffentlich überprüfbar, jeder kann die Prüfung wiederholen. Der Ruf eines Entwicklers ersetzt keine Prüfung, denn Ansehen ist Autorität und kein Beleg. Viele zufriedene Berichte sind Anekdoten, die jede Behauptung stützen können. Und eine schlüssig und fachkundig klingende Erklärung zeigt nur, dass der Anbieter die Sprache der Wissenschaft beherrscht, nicht dass die Methode wirkt.","coreRule":"⚡ Prüfe nicht den Jargon, sondern auf welcher Methode eine Behauptung wirklich ruht.","beleg":"Werkstück A.16 (Anwendung: Pseudowissenschaft; Weg 1 bis 3; Prinzipien Falsifizierbarkeit und öffentliche Überprüfbarkeit)","status":"entwurf","scenario":"Ein Anbieter wirbt für seine „Energie-Methode“. Er verweist auf „Studien“ und benutzt viel Fachjargon. Fragt man, warum die Methode wirkt, antwortet er: „So hat es der Entwickler der Methode festgelegt, und unsere Kundinnen und Kunden berichten begeistert von ihren Erfahrungen.“","kurz":"Wissenschaftlich begründet ist eine Behauptung, wenn sie sagt, was sie widerlegen würde, und andere die Prüfung unabhängig wiederholen können. Der Anbieter stützt sich dagegen auf Autorität und Erlebnisberichte und ahmt nur die Sprache der Wissenschaft nach.","prueffrage":"Welche Gründe nennt der Anbieter, wenn man ihn nach der Wirkung fragt, und woher stammt jeder davon?","rueckmeldung":[{"option":0,"text":"Wie anerkannt der Entwickler ist, sagt etwas über den Mann, aber nichts über die Methode. Ansehen ist Autorität und kein Beleg: Auch ein angesehener Entwickler muss zeigen, wie man seine Behauptung prüfen könnte."},{"option":1,"text":"Dass viele zufrieden sind, kann stimmen, und diese Erfahrungen sind echt. Erlebnisberichte sind aber Anekdoten ohne Vergleich: Sie können jede Behauptung stützen und zeigen nicht, dass die Methode die Ursache war."},{"option":2,"text":"Eine Erklärung, die in sich stimmig und fachkundig klingt, macht Eindruck. Sie zeigt aber nur, dass jemand die Fachsprache beherrscht. Ob die Methode wirkt, entscheidet sich erst an einer Prüfung, die widerlegen könnte."}],"familie":"nach-weg-und-kriterium-fragen","fertigkeit":"F3","quellen":[{"typ":"url","kurz":"Hansson, S. O.: Science and Pseudo-Science. Stanford Encyclopedia of Philosophy","oeffentlich":true,"url":"https://plato.stanford.edu/entries/pseudo-science/","abruf":"2026-10-07"}],"thema":"Gesundheit","pruefung":{"lauf":"quiz-audit-v4","modell":"claude-sonnet-5-5","datum":"2026-10-14","urteil":"ok","pruefsumme":"561df50db7d11725"}},{"id":"qx-a2-020","clusterId":"A","werkstueckRef":"A.17","stufe":1,"question":"Eine Studentin sagt: „Ich hab den Text zweimal gelesen, aber ich kapier ihn nicht, ich bin einfach schlecht in Statistik.“ Was würde jemand mit gutem Blick auf das eigene Denken stattdessen tun?","options":["Sie fragt sich, an welcher Stelle des Statistik-Textes sie den Faden verloren hat, und sucht gezielt eine einfachere Erklärung genau dafür.","Sie liest den Statistik-Text ein drittes Mal von vorn, diesmal langsamer und mit Stift in der Hand, weil Wiederholung das Verständnis festigt.","Sie legt fest, wie viele Seiten des Statistik-Textes sie pro Tag liest, und trägt feste Lesezeiten ein, damit sie den Stoff rechtzeitig schafft.","Sie ersetzt den Gedanken „Ich bin schlecht in Statistik“ durch „Ich kann das lernen“ und bleibt mit neuer Zuversicht an dem Text dran."],"correctIndex":0,"explanation":"„Ich hab’s nicht verstanden“ ist ein pauschales Urteil, aus dem sich nichts ableiten lässt. Wer das eigene Verstehen überwacht, benennt, wo genau es abgerissen ist, und sucht gezielt eine andere Quelle für genau diesen Abschnitt. Nochmaliges Lesen von vorn hilft, wenn man einen Text nur überflogen hat, hier hat sie ihn aber schon zweimal gelesen, ohne die Stelle zu finden. Zeitplanung regelt, wie viel sie liest, nicht ob sie es versteht.","coreRule":"⚡ Gutes Denken über das eigene Denken bedeutet: genau benennen, wo es hakt, und dann die Strategie wechseln, statt sich pauschal als „schlecht darin“ abzustempeln.","quote":"","quoteLabel":"","beleg":"Werkstück A.17 (Kernidee; Kontext & Tiefe)","status":"entwurf","scenario":"","kurz":"Aus „ich kapier’s nicht“ folgt noch nichts. Hilfreich wird es erst, wenn sie die Stelle benennt, an der der Faden riss, und dafür gezielt eine andere Erklärung sucht. Ein weiteres Lesen dagegen findet die Lücke nicht von selbst.","prueffrage":"Was hat die Studentin bisher unternommen, um den Text zu verstehen, und was hat sich zwischen erstem und zweitem Lesen geändert?","rueckmeldung":[{"option":1,"text":"Langsamer lesen mit Stift ist sinnvoll, und Wiederholung hilft oft, wenn man einen Text nur überflogen hat. Hier wurde er schon zweimal gelesen, ohne dass die Stelle auftaucht, an der es hakt, und ein dritter Durchgang von vorn sucht sie nicht gezielt."},{"option":2,"text":"Feste Lesezeiten helfen dabei, den Stoff rechtzeitig zu schaffen. Sie regeln aber nur, wie viel gelesen wird, nicht ob der Text verstanden wird. Die Lücke im Verständnis bleibt dabei unberührt."},{"option":3,"text":"Zuversicht kann helfen, dranzubleiben. Der neue Satz ist aber wie der alte ein pauschales Urteil: Er verrät nicht, an welcher Stelle das Verstehen abgerissen ist, und daraus ergibt sich kein nächster Schritt."}],"familie":"wissensgrenze-benennen","fertigkeit":"F5","quellen":[{"typ":"url","kurz":"O’Leary, A. J.; Sloutsky, V. M.: Carving metacognition at its joints: Protracted development of component processes. Child Development 88(3), 1015–1032 (PMC)","oeffentlich":true,"url":"https://pmc.ncbi.nlm.nih.gov/articles/PMC5397377/","abruf":"2026-10-12"},{"typ":"literatur","kurz":"Flavell, J. H. (1979): Metacognition and Cognitive Monitoring: A New Area of Cognitive-Developmental Inquiry. American Psychologist 34, 906–911","oeffentlich":false}],"thema":"Psychologie","pruefung":{"lauf":"quiz-audit-v8","modell":"claude-sonnet-5-5","datum":"2026-10-15","urteil":"korrigieren","pruefsumme":"11f4951a361152ad"}},{"id":"qx-a2-021","clusterId":"A","werkstueckRef":"A.17","stufe":2,"question":"Du liest einen Fachtext und verlierst im Abschnitt über Statistik den Faden. Welche Reaktion nutzt das Nachdenken über das eigene Lernen am besten?","scenario":"Du arbeitest dich durch einen Fachtext. Der Anfang war klar, doch im Abschnitt über Statistik kommst du nicht mehr mit. Du hast noch eine knappe Stunde Zeit.","options":["Du teilst die knappe Stunde in feste Zeitblöcke ein und liest in jedem Block ein festes Stück des Textes weiter.","Du benennst, bis wohin im Statistik-Abschnitt du folgen konntest, und gehst genau diesen Abschnitt noch einmal gezielt an.","Du beginnst den Text noch einmal von vorn und liest ihn Absatz für Absatz, bis du bei jeder Stelle sicher bist.","Du liest zügig bis zum Textende weiter, weil sich die Statistik später aus dem Zusammenhang erklären könnte, und prüfst erst am Ende."],"correctIndex":1,"explanation":"Wer sein eigenes Verständnis überwacht, merkt nicht nur, dass etwas nicht klappt, sondern kann genau sagen, wo es aussetzt. Erst diese Genauigkeit erlaubt eine passende Gegenmaßnahme: den fraglichen Abschnitt noch einmal ansehen oder eine einfachere Quelle suchen. Und Weiterlesen ohne Prüfung setzt nicht an der Stelle an, an der das Verständnis tatsächlich abbrach.","coreRule":"⚡ Benenne genau, wo dein Verständnis endet, und passe dann deine Strategie an.","beleg":"Werkstück A.17 (Anwendung: Beim Lernen & Verstehen; Red Flags)","status":"entwurf","kurz":"Wer genau benennen kann, wo das Verständnis aussetzt, kann gezielt gegensteuern. Bloßes Gefühl, nicht mitzukommen, führt dagegen zu ungezielten Reaktionen wie Neustart, Zeitplan oder Weiterlesen.","prueffrage":"Wie viel Zeit bleibt dir, und für welchen Teil des Textes brauchst du sie wirklich?","rueckmeldung":[{"option":0,"text":"Feste Zeitblöcke helfen, die Stunde zu nutzen. Sie sagen aber nichts darüber, ob du den Stoff verstanden hast, und lassen die Stelle unberührt, an der du den Faden verloren hast."},{"option":2,"text":"Gründlichkeit ist an sich gut. Doch ein Neustart verbraucht die knappe Stunde auch auf Abschnitte, die du längst verstanden hast, statt dort anzusetzen, wo es hakt."},{"option":3,"text":"Manchmal klärt sich Unklares im weiteren Text. Ohne Prüfung bleibt aber offen, ob das passiert, und die Lücke wächst eventuell, weil du nicht dort ansetzt, wo das Verständnis abbrach."}],"familie":"wissensgrenze-benennen","fertigkeit":"F5","quellen":[{"typ":"url","kurz":"O’Leary, A. J.; Sloutsky, V. M.: Carving metacognition at its joints: Protracted development of component processes. Child Development 88(3), 1015–1032 (PMC)","oeffentlich":true,"url":"https://pmc.ncbi.nlm.nih.gov/articles/PMC5397377/","abruf":"2026-10-12"},{"typ":"literatur","kurz":"Flavell, J. H. (1979): Metacognition and Cognitive Monitoring: A New Area of Cognitive-Developmental Inquiry. American Psychologist 34, 906–911","oeffentlich":false}],"thema":"Psychologie","pruefung":{"lauf":"quiz-audit-v5","modell":"claude-sonnet-5-5","datum":"2026-10-14","urteil":"ok","pruefsumme":"99761592859dd3ee"}},{"id":"qx-a2-022","clusterId":"A","werkstueckRef":"A.17","stufe":3,"question":"Was erklärt das am besten?","options":["Ihr fehlt im Spiel noch die Routine mit der neuen Selbstprüfung: Mit etwas Übung wird sie darin schneller, und das Zögern legt sich dann von selbst.","Die Selbstprüfung kommt am falschen Ort und zur falschen Zeit: Wo Sekundenbruchteile zählen, kostet sie Reaktionszeit, und die Torhüterin zögert.","Sie prüft im Spiel zu viel auf einmal: Beschränkte sie sich vor jedem Wurf auf eine einzige Prüffrage, bliebe sie nützlich, ohne dass sie zögert.","Die vielen Gegentore verunsichern sie, und deshalb prüft sie sich im Spiel so oft: Die Selbstprüfung ist dann eher Folge als Ursache des Problems."],"correctIndex":1,"explanation":"Nachdenken über das eigene Denken (Fachbegriff: Metakognition) kann in Situationen hinderlich sein, die schnelle, intuitive Entscheidungen erfordern; Sport und Notfälle sind typische Beispiele. Solche Selbstprüfung ist langsam und anstrengend: Wo Sekundenbruchteile zählen, kostet sie Zeit, man analysiert, statt zu reagieren, und zögert. Das Werkzeug an sich bleibt nützlich, es kommt auf den passenden Ort und Zeitpunkt an, etwa im Training oder in der Pause. Noch mehr Nachdenken im Spiel würde das Zögern verstärken, denn gerade die Prüfung vor jedem Wurf kostet Zeit. Mit Wettkampfdruck lässt sich die Unsicherheit nicht erklären, denn von Druck ist im Szenario keine Rede; sie entsteht, seit sie auch im Spiel jeden Wurf prüft. Und Training und Videoanalyse bringen ihr ja nachweislich viel, es fehlt also nicht an Übertragbarkeit, sondern am Zeitpunkt der Prüfung.","coreRule":"⚡ Selbstprüfung gehört in ruhige Momente; wo Sekundenbruchteile zählen, zählt das Handeln.","beleg":"Werkstück A.17 (Der Kipppunkt; Anwendung)","status":"entwurf","scenario":"Die Torhüterin einer Handballmannschaft will nach jedem Gegentor ihre Entscheidungen verbessern. Im Training, in der Halbzeitpause und bei der Videoanalyse prüft sie ihre Entscheidungen gründlich, und dort bringt ihr das viel. Inzwischen prüft sie auch im Spiel bei jedem Wurf zuerst, was sie gerade denkt und fühlt, welche Strategie sie nutzt und ob die zu ihr passt. Das Team kassiert viele Tore, sie wirkt unsicher.","quote":"","quoteLabel":"","kurz":"Nachdenken über das eigene Denken ist langsam: Wo Sekundenbruchteile zählen, kostet es Reaktionszeit, man analysiert, statt zu reagieren, und zögert. Im Training und in der Pause nützt dasselbe Werkzeug.","prueffrage":"Wie hat die Torhüterin gehalten, bevor sie im Spiel mit dieser Selbstprüfung begann, und wie seitdem?","rueckmeldung":[{"option":0,"text":"Übung macht vieles schneller, deshalb wirkt das plausibel. Doch die Prüfung vor jedem Wurf kostet immer Zeit, und mehr Nachdenken im Spiel verstärkt das Zögern eher. Nicht die Übung fehlt, sondern der passende Zeitpunkt."},{"option":2,"text":"Weniger Prüfung wäre tatsächlich besser als viel, und das Werkzeug bleibt nützlich. Aber auch eine einzige Frage vor jedem Wurf kostet Zeit, wo Sekundenbruchteile zählen. Nicht die Menge ist das Problem, sondern der Ort der Prüfung."},{"option":3,"text":"Viele Gegentore können verunsichern, deshalb klingt das stimmig. Im Szenario läuft es aber umgekehrt: Erst prüft sie jeden Wurf im Spiel, dann kommen Gegentore und Unsicherheit. Von Druck als Auslöser steht dort nichts."}],"familie":"wissensgrenze-benennen","fertigkeit":"F5","quellen":[{"typ":"url","kurz":"Worthy, D. A.; Markman, A. B.; Maddox, W. T. (2009): Choking and excelling under pressure in experienced classifiers. Attention, Perception & Psychophysics 71(4), 924–935 (PMC)","oeffentlich":true,"url":"https://pmc.ncbi.nlm.nih.gov/articles/PMC2708085/","abruf":"2026-10-12"},{"typ":"url","kurz":"Kahneman, D. (2002): Maps of Bounded Rationality. Nobel Prize Lecture, nobelprize.org","oeffentlich":true,"url":"https://www.nobelprize.org/uploads/2018/06/kahnemann-lecture.pdf","seite":"450","abruf":"2026-10-12"}],"thema":"Psychologie","pruefung":{"lauf":"quiz-audit-v8","modell":"claude-sonnet-5-5","datum":"2026-10-15","urteil":"korrigieren","pruefsumme":"c93feda89e3137e0"}},{"id":"qx-a2-023","clusterId":"A","werkstueckRef":"A.18","stufe":1,"question":"Zwei Personen reagieren auf eine neue Meldung: „Ein Präparat soll Erkältungen halbieren.“ Person A sagt: „Zeig mir eine kontrollierte Studie, die das belegt. Bis dahin halte ich die Aussage für unbewiesen. Wenn die Daten stimmen, ändere ich meine Meinung.“ Person B sagt: „Das ist Unsinn, das stimmt nie. Egal, welche Studie du bringst: Die ist gekauft.“ Was unterscheidet die beiden Haltungen im Kern?","options":["A macht sein Urteil von einer Studie abhängig und würde es ändern; B hat das Ergebnis festgelegt und wertet Studien vorab als gekauft ab.","A achtet bei Studien auf die Methode, B eher auf die Geldgeber; beide prüfen kritisch, nur schauen sie auf verschiedene Schwachstellen.","A und B halten die Meldung vorerst beide für unbelegt; sie begründen das nur verschieden, A mit fehlenden Daten, B mit Misstrauen.","A und B sind beide Skeptiker, nur verschieden streng: A genügt eine kontrollierte Studie, B verlangt deutlich mehr Belege, bevor er umdenkt."],"correctIndex":0,"explanation":"Person A legt fest, was sie überzeugen würde, und hält ihr Urteil bis dahin zurück. Das ist eine Methode: Die Stärke der Überzeugung richtet sich nach der Stärke der Belege. Person B hat die Schlussfolgerung schon gefasst und arbeitet sich rückwärts: Jeder widersprechende Beleg wird im Voraus abgewertet, damit das Ergebnis nicht gefährdet wird. Eine solche Position ist gegen Evidenz immun und deshalb keine Prüfung, sondern die Verteidigung eines fertigen Ergebnisses.","coreRule":"⚡ Ein Skeptiker prüft mit offener Methode und kann sagen, was ihn umstimmen würde; ein Leugner verteidigt ein fertiges Ergebnis.","quote":"","quoteLabel":"","beleg":"Werkstück A.18 (Kernidee; Kontext & Tiefe); Fn. ga-leugnung (Hansson 2017, Studies in History and Philosophy of Science 63, S. 39–47)","status":"entwurf","scenario":"","kurz":"A legt fest, was ihn überzeugen würde, und hält sein Urteil bis dahin zurück. B hat das Ergebnis schon gefasst und wertet jeden Beleg vorab ab. Die erste Haltung folgt den Belegen, die zweite verteidigt ein fertiges Urteil.","prueffrage":"Was sagt jede der beiden Personen über eine Studie, die es noch gar nicht gibt?","rueckmeldung":[{"option":1,"text":"Geldgeber zu hinterfragen ist ein berechtigter Prüfpunkt. B benennt aber keinen konkreten Mangel, sondern wertet jede Studie vorab als gekauft ab. Das ist keine andere Prüfung, sondern gar keine."},{"option":2,"text":"A hält die Aussage tatsächlich für unbewiesen. B hält sie aber nicht für unbelegt, sondern für falsch („stimmt nie“) und hat das Urteil schon gefällt. „Noch nicht belegt“ und „sicher falsch“ sind verschiedene Positionen."},{"option":3,"text":"Der Unterschied liegt nicht in der Strenge. Wer hohe Anforderungen stellt, kann durch Belege umdenken. B tut das nie, denn seine Position kann durch keine Studie mehr erreicht werden."}],"familie":"gewissheit-kalibrieren","fertigkeit":"F5","quellen":[{"typ":"url","kurz":"Hansson, S. O.: Science and Pseudo-Science. Stanford Encyclopedia of Philosophy","oeffentlich":true,"url":"https://plato.stanford.edu/entries/pseudo-science/","abruf":"2026-10-07"},{"typ":"doi","kurz":"Hansson, S. O. (2017): Science denial as a form of pseudoscience. Studies in History and Philosophy of Science Part A 63, 39–47","oeffentlich":false,"doi":"10.1016/j.shpsa.2017.05.002"}],"thema":"Gesundheit","pruefung":{"lauf":"quiz-audit-v8","modell":"claude-sonnet-5-5","datum":"2026-10-15","urteil":"ok","pruefsumme":"f28224e72b5ea089"}},{"id":"qx-a2-024","clusterId":"A","werkstueckRef":"A.18","stufe":2,"question":"Welche Frage prüft seine Behauptung am besten?","scenario":"Auf einer Feier erzählt dir ein Astrologe begeistert, die Stellung der Planeten sage seit Jahren zuverlässig voraus, was im Leben seiner Kundschaft geschieht.","options":["„Kannst du mir Fälle nennen, in denen deine Vorhersagen eingetroffen sind, und wie viele waren es?“","„Welche Ausbildung hast du, und in welchen Medien wurdest du als Experte zitiert?“","„Wie wirken die Planeten auf mich, und gibt es Tests mit Treffern über dem Zufall?“","„Wie lange gibt es die Astrologie schon, und in wie vielen Kulturen wird sie bis heute genutzt?“"],"correctIndex":2,"explanation":"Eine Behauptung wird geprüft, indem man fragt, welcher Mechanismus sie erklären soll und ob kontrollierte Studien zeigen, dass die Vorhersagen besser sind als reiner Zufall. Einzelne eingetroffene Vorhersagen sind kein Beleg, denn ohne Vergleich mit dem Zufall lässt sich nicht sagen, ob die Treffer mehr sind als Glück. Fragen nach Ausbildung oder Medienauftritten prüfen die Person, nicht die Behauptung. Alter und Verbreitung einer Praxis sagen nichts darüber, ob sie wirkt. Astrologie hat in kontrollierten Tests bisher keine Treffer über dem Zufall gezeigt. Die Frage nach solchen Tests lässt das Gegenüber selbst nachsehen, statt es nur abzuwerten.","coreRule":"⚡ Frag nach Mechanismus und kontrollierten Tests, nicht nach dem Ruf des Behauptenden.","beleg":"Werkstück A.18 (Anwendung: Gegenüber Pseudowissenschaft & Esoterik; Red Flags)","status":"entwurf","kurz":"Eine Behauptung prüft man, indem man nach einem erklärenden Mechanismus und nach kontrollierten Tests fragt, deren Treffer über dem Zufall liegen. Einzelne eingetroffene Vorhersagen, Titel oder Alter beweisen nichts, weil sie keinen Vergleich mit dem Zufall liefern.","prueffrage":"Welche Vorhersagen hat er in den letzten Jahren gemacht, und wurden sie aufgeschrieben, bevor sich zeigte, ob sie eintreffen?","rueckmeldung":[{"option":0,"text":"Nach konkreten Fällen zu fragen, wirkt greifbar und ist besser als blindes Vertrauen. Gezählt werden aber nur die Treffer, ohne Fehlschläge und ohne Vergleich mit dem Zufall. Bei vagen Vorhersagen trifft immer etwas ein, auch ohne Wirkung."},{"option":1,"text":"Ausbildung und Medienauftritte lassen sich leicht erfragen und klingen nach Seriosität. Sie sagen aber etwas über die Person und nicht darüber, ob die Vorhersagen besser sind als der Zufall. Die Behauptung selbst bleibt damit ungeprüft."},{"option":3,"text":"Alter und weite Verbreitung sind überprüfbare Tatsachen und beeindrucken leicht. Ob eine Praxis wirkt, sagt das jedoch nicht: Auch Irrtümer können sehr alt sein und in vielen Kulturen gepflegt werden."}],"familie":"wissenschaft-abgrenzen","fertigkeit":"F1","quellen":[{"typ":"url","kurz":"Dean, G.; Kelly, I. W. (2003): Is astrology relevant to consciousness and psi? (Nachdruck auf astrology-and-science.com)","oeffentlich":true,"url":"https://astrology-and-science.com/D-psia1.htm","abruf":"2026-10-12"},{"typ":"literatur","kurz":"Dean, G.; Kelly, I. W. (2003): Is astrology relevant to consciousness and psi? Journal of Consciousness Studies 10(6–7), 175–198","oeffentlich":false}],"thema":"Geschichte und Wissenschaft","pruefung":{"lauf":"quiz-audit-v4","modell":"claude-sonnet-5-5","datum":"2026-10-14","urteil":"korrigieren","pruefsumme":"aeaf8eb109ef871e"}},{"id":"qx-a2-025","clusterId":"A","werkstueckRef":"A.18","stufe":3,"question":"Jemand sagt: „Es gibt keine absolute Gewissheit, also ist die Kugelgestalt der Erde ebenso gut begründet wie die Scheibe.“ Was ist an diesem Schluss fehlerhaft?","options":["Er irrt schon in der Annahme, denn bei der Kugelgestalt der Erde gibt es sehr wohl absolute Gewissheit.","Er stellt eine Außenseitermeinung auf eine Stufe mit dem, was die Fachwelt mehrheitlich für richtig hält.","Er folgert aus fehlender absoluter Gewissheit, dass alle Behauptungen gleich gut begründet sind.","Er übersieht, dass die Beweislast bei dem liegt, der die Scheibe behauptet, und nicht bei der Kugel."],"correctIndex":2,"explanation":"Dass es keine absolute Gewissheit gibt, stimmt, aber daraus folgt nicht, dass alle Behauptungen gleich unsicher wären. Es gibt verlässliche Methoden, um gut begründetes, wenn auch vorläufiges Wissen zu gewinnen, und die Stärke einer Überzeugung sollte der Stärke der Belege entsprechen. Für die Kugelgestalt der Erde sprechen unabhängige Belege aus vielen Richtungen, etwa Satellitenbilder, Erdumrundungen und der runde Erdschatten bei Mondfinsternissen; für die Scheibe gibt es nichts Vergleichbares. Beide gleichzusetzen ist kein Skeptizismus, sondern gibt das Prüfen auf: Hier kippt der Zweifel in die Haltung, dass gar kein Wissen möglich sei. Ein echter Skeptiker fragt, welche Belege jeweils vorliegen, und stuft sein Vertrauen danach ab.","coreRule":"⚡ Skeptizismus misst Überzeugung an der Stärke der Belege; Gleichmacherei ist keiner.","beleg":"Werkstück A.18 (Der Kipppunkt; Kontext & Tiefe: Proportionalität)","status":"entwurf","quote":"","quoteLabel":"","kurz":"Fehlende absolute Gewissheit heißt nicht, dass alles gleich unsicher ist: Die Stärke einer Überzeugung sollte der Stärke der Belege folgen. Wer beide Ansichten gleichsetzt, prüft die Belege gar nicht mehr, und das ist kein Skeptizismus.","prueffrage":"Welche Belege lassen sich für jede der beiden Behauptungen tatsächlich nennen, und wie viele sind es?","rueckmeldung":[{"option":0,"text":"Hier steckt der Fehler nicht in der Annahme. Dass es bei empirischen Aussagen keine absolute Gewissheit gibt, stimmt. Auch die Kugelgestalt ist sehr gut belegt, aber vorläufig; der Fehler liegt erst im Schluss, der daraus gleiche Begründetheit macht."},{"option":1,"text":"Die Gleichsetzung ist tatsächlich unberechtigt, aber nicht, weil die Fachwelt mehrheitlich zustimmt. Entscheidend sind die unabhängigen Belege, die für die Kugel sprechen. Eine Mehrheit allein würde die Frage nach den Belegen nur verschieben."},{"option":3,"text":"Wer die Scheibe behauptet, hat tatsächlich viel zu belegen. Der Fehler im Satz liegt aber woanders: Er folgert aus fehlender absoluter Gewissheit, dass beide Ansichten gleich gut begründet seien, und das ist eine Frage der Belegstärke, nicht der Beweislastverteilung."}],"familie":"gewissheit-kalibrieren","fertigkeit":"F5","quellen":[{"typ":"url","kurz":"Hume, D.: An Enquiry Concerning Human Understanding, Sect. X „Of Miracles“, Part I (Project Gutenberg, Ausg. Selby-Bigge)","oeffentlich":true,"url":"https://www.gutenberg.org/files/9662/9662-h/9662-h.htm","abruf":"2026-10-12"}],"thema":"Geschichte und Wissenschaft","pruefung":{"lauf":"quiz-audit-v8","modell":"claude-sonnet-5-5","datum":"2026-10-15","urteil":"korrigieren","pruefsumme":"fac78c2878e3f0e7"}},{"id":"qx-a2-026","clusterId":"A","werkstueckRef":"A.18","stufe":4,"question":"Warum ist das Vorgehen von Prüfer B das methodisch bessere?","options":["Prüfer B legt Regeln und Erfolgskriterien vorab fest; so kann der Test eine echte Fähigkeit belegen oder die Behauptung scheitern lassen, ohne dass man das Ergebnis nachträglich zurechtbiegt.","Prüfer B legt die Bedingungen vorab gemeinsam fest; so kann der Mann ein Scheitern hinterher nicht als unfair abtun und muss das Urteil der Prüfer auch dann anerkennen, wenn es gegen ihn spricht.","Prüfer B gibt dem Test einen festen Rahmen; so ist die Sache in absehbarer Zeit entschieden, während Prüferin A womöglich sehr lange beobachten muss, bis sie den gesuchten Trick findet.","Prüfer B prüft unter festgelegten Bedingungen; so ließe sich ein möglicher Schwindel zuverlässiger aufdecken, als wenn Prüferin A allein und ohne Plan nach einem geschickten Trick sucht."],"correctIndex":0,"explanation":"Wer von vornherein weiß, dass jemand betrügt, und dann nur nach dem Trick sucht, kann nichts anderes finden als eine Bestätigung seiner Annahme. Das mag als Entlarvung brillant sein, ist aber keine Untersuchung, denn die Schlussfolgerung stand schon fest. Ein vorab vereinbarter, fairer Test ist ergebnisoffen: Besteht der Prüfling unter kontrollierten Bedingungen, muss man die eigene Meinung ändern; besteht er nicht, bleibt die Behauptung unbewiesen, und kein Prüfer hat sich sein Urteil nachträglich zurechtgelegt. So arbeitete auch der Zauberkünstler James Randi, dessen Millionen-Dollar-Herausforderung nach diesem Prinzip aufgebaut war und bis zu ihrem Ende 2015 von niemandem bestanden wurde.","coreRule":"⚡ Echte Skepsis lässt dem Behauptenden eine faire Chance, sich zu bewähren.","beleg":"Werkstück A.18 (Einstiegsgeschichte); Fn. ga-randi (Houdini † 1926, Randi * 1928; Zuspitzung, keine wörtlich belegte Aussage)","status":"entwurf","scenario":"Ein Mann behauptet, er könne mit einer Wünschelrute Wasseradern unter der Erde aufspüren. Zwei Prüfer sollen die Behauptung untersuchen. Prüferin A sagt: „Das ist Schwindel. Ich beobachte ihn, bis ich den Trick finde, mit dem er die Leute täuscht.“ Prüfer B sagt: „Wir legen vorab gemeinsam fest, was als Erfolg zählt, schließen Tricks aus und testen ihn unter diesen Bedingungen.“","kurz":"Wer schon weiß, dass jemand betrügt, findet bei der Suche nach dem Trick nur Bestätigung. Ein vorab vereinbarter Test ist dagegen ergebnisoffen: Er kann die Behauptung belegen oder scheitern lassen, ohne dass jemand sein Urteil nachträglich zurechtbiegt.","prueffrage":"Was genau soll der Mann bei Prüfer B tun, und woran liest man danach ab, ob er Erfolg hatte?","rueckmeldung":[{"option":1,"text":"Klare Regeln vorab erschweren tatsächlich spätere Ausreden. Das ist aber nur eine Begleiterscheinung; zudem kann niemand ihn zwingen, ein Urteil anzuerkennen. Entscheidend ist, dass der Test offen lässt, wie er ausgeht."},{"option":2,"text":"Ein fester Rahmen spart Zeit, und endloses Beobachten ohne Plan kostet viel davon. Das ist jedoch ein praktischer Vorteil, kein methodischer Grund: Auch ein schneller Test taugt nichts, wenn das Ergebnis schon feststeht."},{"option":3,"text":"Kontrollierte Bedingungen schließen Tricks aus, doch der Test soll nicht darauf zielen, einen Schwindel zu finden. Das übernimmt die feste Annahme von Prüferin A. Ein guter Test lässt ebenso zu, dass der Mann besteht."}],"familie":"fair-testen","fertigkeit":"F1","quellen":[{"typ":"url","kurz":"Wikipedia: One Million Dollar Paranormal Challenge","oeffentlich":true,"url":"https://en.wikipedia.org/wiki/One_Million_Dollar_Paranormal_Challenge","abruf":"2026-10-04"}],"thema":"Geschichte und Wissenschaft","pruefung":{"lauf":"quiz-audit-v8","modell":"claude-sonnet-5-5","datum":"2026-10-15","urteil":"korrigieren","pruefsumme":"7c4676daa20cddff"}},{"id":"qx-a2-027","clusterId":"A","werkstueckRef":"A.19","stufe":1,"question":"Bevor du am Abend deinem Bauchgefühl folgst: Welche Frage hilft dir am meisten zu beurteilen, ob es für diese Entscheidung verlässlich ist?","options":["Wie stark und eindeutig fühlt sich mein Bauchgefühl bei Wahl und Behandlung an, und wie lange hält dieses Gefühl schon an?","Wie gut könnte ich meine Entscheidung bei Wahl und Behandlung vor anderen begründen, und wäre ich bereit, sie öffentlich zu vertreten?","Wie hoch sind die Kosten eines Irrtums bei Wahl oder Behandlung, und ist das ein Bereich, in dem sich mein Bauchgefühl bewährt hat?","Wie viele andere Menschen würden in dieser Lage wohl genauso entscheiden wie ich, und wie sicher wirken sie dabei?"],"correctIndex":2,"explanation":"Schnelle Faustregeln wie das Bauchgefühl sind nützlich, wenn ein Fehler wenig kostet: Wer bei Marmelade danebengreift, verliert kaum etwas. Bei einer Wahl oder einer Behandlung kann ein Irrtum dagegen schwere Folgen haben; je mehr auf dem Spiel steht, desto weniger sollte man sich ungeprüft auf eine Faustregel verlassen. Deshalb prüfst du zuerst, was auf dem Spiel steht und ob sich dein Bauchgefühl in diesem Bereich schon bewährt hat. Ist der Einsatz hoch und fehlt diese Bewährung, lohnt sich eine langsamere, gründlichere Prüfung anhand von Daten und Alternativen. Weder ein starkes, lang anhaltendes Gefühl der Sicherheit noch die Zahl der Menschen, die genauso entscheiden würden, zeigt, ob das Bauchgefühl richtigliegt. Auch die Frage, wie gut sich die Entscheidung vor anderen begründen lässt, ist als Rechenschaft sinnvoll, sagt aber nichts darüber, ob das Gefühl in diesem Bereich treffsicher ist.","coreRule":"⚡ Faustregeln sind meist gut genug, aber je höher die Kosten eines Fehlers, desto eher lohnt die langsame Prüfung.","quote":"Der Kipppunkt ist die Relevanz der Entscheidung.","quoteLabel":"Zum Weiterdenken:","beleg":"Werkstück A.19 (Kernidee; Kontext & Tiefe); Fn. ga-heuristiken (Tversky/Kahneman 1974, Science 185, S. 1124)","status":"entwurf","scenario":"Zwei Situationen am selben Tag: Im Supermarkt greifst du ohne Nachdenken zur Marmeladensorte, die du kennst. Am Abend soll dein Bauchgefühl entscheiden, ob du einem Kandidaten bei einer wichtigen Wahl deine Stimme gibst oder einer teuren medizinischen Behandlung zustimmst.","kurz":"Entscheidend ist, was bei einem Irrtum auf dem Spiel steht und ob sich dein Gefühl in diesem Bereich schon bewährt hat. Bei Marmelade kostet ein Fehlgriff wenig, bei Wahl oder Behandlung kann er schwer wiegen; dann braucht es mehr als ein bloß starkes Gefühl.","prueffrage":"Wie oft hast du bei Marmelade und wie oft bei Wahlen oder Behandlungen schon aus dem Bauch entschieden, und wie ging es aus?","rueckmeldung":[{"option":0,"text":"Ein starkes, lang anhaltendes Gefühl fühlt sich nach Verlässlichkeit an, doch die Stärke misst nur, wie sicher du dich fühlst. Ob das Gefühl in diesem Bereich schon einmal richtiglag, zeigt sie nicht."},{"option":1,"text":"Eine Entscheidung begründen zu können, ist als Rechenschaft sinnvoll. Es sagt aber nicht, ob dein Bauchgefühl in diesem Bereich treffsicher ist, und genau darum geht es hier."},{"option":3,"text":"Dass viele andere ähnlich entscheiden würden und dabei sicher wirken, beruhigt leicht. Es zeigt aber nicht, ob das Bauchgefühl richtigliegt, und ersetzt nicht die Frage nach Einsatz und Bewährung."}],"familie":"faustregel-oder-rechnen","fertigkeit":"F4","quellen":[{"typ":"url","kurz":"Kahneman, D.; Klein, G. (2009): Conditions for intuitive expertise: a failure to disagree. American Psychologist 64(6), 515–526 (PubMed-Abstract)","oeffentlich":true,"url":"https://pubmed.ncbi.nlm.nih.gov/19739881/","abruf":"2026-10-12"},{"typ":"url","kurz":"Kahneman, D. (2002): Maps of Bounded Rationality. Nobel Prize Lecture, nobelprize.org","oeffentlich":true,"url":"https://www.nobelprize.org/uploads/2018/06/kahnemann-lecture.pdf","seite":"465","abruf":"2026-10-12"},{"typ":"doi","kurz":"Tversky, A.; Kahneman, D. (1974): Judgment under Uncertainty: Heuristics and Biases. Science 185(4157), 1124–1131","oeffentlich":false,"doi":"10.1126/science.185.4157.1124","seite":"1124"}],"thema":"Psychologie","pruefung":{"lauf":"quiz-audit-v4","modell":"claude-sonnet-5-5","datum":"2026-10-14","urteil":"korrigieren","pruefsumme":"aed1ef92f4b7e549"}},{"id":"qx-a2-028","clusterId":"A","werkstueckRef":"A.19","stufe":2,"question":"Warum ist es hier vernünftig, einfach die bekannte Marke zu nehmen, statt alle Sorten zu vergleichen?","scenario":"Im Supermarkt stehst du vor einem Regal mit 50 Marmeladensorten und greifst ohne langes Nachdenken zu deiner gewohnten Marke.","options":["Die gewohnte Marke hat dir bisher geschmeckt, also ist sie unter den 50 Sorten vermutlich auch die beste.","Ein Fehlgriff kostet wenig, ein Vergleich aller 50 Sorten dagegen unverhältnismäßig viel Zeit und Mühe.","Beim schnellen Griff ist auf das Bauchgefühl meist mehr Verlass als auf ein langes Abwägen aller Sorten.","Eine andere Sorte könnte dir schlechter schmecken, und dieses Risiko vermeidest du mit der gewohnten Marke."],"correctIndex":1,"explanation":"Faustregeln sind mentale Abkürzungen, die in den meisten Fällen „gut genug“ sind, aber nicht optimal und nicht fehlerfrei. Entscheidend ist das Verhältnis von Aufwand und Einsatz: Bei der Marmelade ist ein möglicher Fehler trivial, während ein vollständiger Vergleich aller 50 Sorten viel Zeit und Energie kostet. Wer vor jedem Regal alles durchrechnen wollte, käme im Alltag kaum zum Handeln. Anders sieht es aus, wenn viel auf dem Spiel steht, etwa bei einer medizinischen Entscheidung: Dort lohnt sich der Wechsel zum langsamen, genauen Prüfen, weil ein Fehler teuer wäre. Der eigene Geschmack klingt nach einem guten Maßstab, sagt aber nichts über die 49 Sorten, die du nie probiert hast.","coreRule":"⚡ Bei geringem Einsatz ist die Faustregel klug, bei hohem Einsatz lohnt das genaue Rechnen.","beleg":"Werkstück A.19 (Das Adaptive Talent; Der Kipppunkt)","status":"entwurf","kurz":"Der Fehlgriff wäre bei Marmelade trivial, der Vergleich aller 50 Sorten dagegen aufwendig. Die Faustregel ist hier „gut genug“, nicht optimal. Anders ist es, wenn viel auf dem Spiel steht, etwa bei einer medizinischen Entscheidung.","prueffrage":"Wie oft hat dich die gewohnte Marke schon enttäuscht, und was hast du dann getan?","rueckmeldung":[{"option":0,"text":"Dass dir die Marke schmeckt, stimmt. Über die 49 Sorten, die du nie probiert hast, sagt es aber nichts, also auch nicht, ob deine die beste ist. Sie ist nur gut genug, und das genügt hier."},{"option":2,"text":"Schnelle Entscheidungen fühlen sich oft sicher an. Der Grund für den raschen Griff liegt aber nicht im Bauchgefühl, sondern im geringen Einsatz. Auch Abkürzungen machen Fehler, und wenn viel auf dem Spiel steht, lohnt sich genaues Prüfen."},{"option":3,"text":"Das Risiko, dass eine andere Sorte schlechter schmeckt, besteht tatsächlich. Es ist aber klein und folgenlos, und genau darum ist der Griff zur bekannten Marke vernünftig. Entscheidend ist das Verhältnis von Aufwand und Einsatz, nicht das Vermeiden jeden Risikos."}],"familie":"faustregel-oder-rechnen","fertigkeit":"F4","quellen":[{"typ":"url","kurz":"Stanford Encyclopedia of Philosophy: Bounded Rationality (überarb. 2024)","oeffentlich":true,"url":"https://plato.stanford.edu/entries/bounded-rationality/","abruf":"2026-10-12"},{"typ":"url","kurz":"Kahneman, D. (2002): Maps of Bounded Rationality. Nobel Prize Lecture, nobelprize.org","oeffentlich":true,"url":"https://www.nobelprize.org/uploads/2018/06/kahnemann-lecture.pdf","seite":"483","abruf":"2026-10-12"}],"thema":"Psychologie","pruefung":{"lauf":"quiz-audit-v8","modell":"claude-sonnet-5-5","datum":"2026-10-15","urteil":"korrigieren","pruefsumme":"4f73e9de39a4ffd9"}},{"id":"qx-a2-029","clusterId":"A","werkstueckRef":"A.19","stufe":3,"question":"Wozu rätst du ihr in dieser Lage?","options":["Sie ist sich absolut sicher; dieses starke Gefühl zeigt, dass die Faustregel hier trägt, also kann sie den Vertrag noch heute unterschreiben.","Sie hat schon viele Verträge abgeschlossen; ihr Bauchgefühl speist sich aus Erfahrung, also kann sie auf Vergleichsangebote verzichten.","Sie hat noch zwei Wochen Zeit; statt fünf Minuten sollte sie eine Stunde in Ruhe über den Vertrag nachdenken und dann ihrem Gefühl folgen.","Der Vertrag bindet die Firma für Jahre, und die Frist lässt Zeit; also sollte sie die Details prüfen und Vergleichsangebote einholen."],"correctIndex":3,"explanation":"Faustregeln sind schnell und meist gut genug, aber ihre Fehler sind vorhersagbar. Ob du ihnen trauen darfst, hängt davon ab, was ein Fehler kostet: Beim Marmeladenkauf ist er trivial, bei einem Vertrag, der die Firma jahrelang bindet, kann er schwer wiegen. Dann lohnt sich der Wechsel ins langsame, analytische Denken, zumal die Frist von zwei Wochen Zeit zum Prüfen lässt. Ein starkes Sicherheitsgefühl spricht nicht für die Faustregel: Gerade wer bei einer schnellen Entscheidung in komplexer Lage absolut sicher ist, sollte misstrauisch werden. Auch viel Erfahrung ändert nichts daran, dass hier ein Fehler teuer wäre und eine Prüfung möglich ist; das Bauchgefühl ersetzt sie nicht. Und eine Stunde Grübeln hilft wenig, denn es kommt nicht auf die Dauer an, sondern auf die Art der Prüfung: Daten, Vergleiche, Gegenfragen.","coreRule":"⚡ Je höher der Einsatz, desto weniger darfst du dich auf die schnelle Faustregel verlassen.","beleg":"Werkstück A.19 (Der Kipppunkt; Red Flags)","status":"entwurf","scenario":"Eine Kollegin will in fünf Minuten über einen Vertrag entscheiden, der die Firma mehrere Jahre bindet. Sie hat schon viele Verträge abgeschlossen und sagt: „Ich habe sofort ein gutes Gefühl dabei, das passt. Ich bin mir absolut sicher.“ Detailprüfung oder Vergleichsangebote gab es nicht. Die Frist für die Unterschrift endet erst in zwei Wochen.","quote":"","quoteLabel":"","kurz":"Bei einem Vertrag, der die Firma jahrelang bindet, wäre ein Fehler teuer, und zwei Wochen Frist erlauben eine echte Prüfung. Das starke Gefühl ist dabei kein Gegenargument, es ersetzt Details und Vergleiche nicht.","prueffrage":"Was würde ein Fehler bei dieser Unterschrift kosten, und wie viel Zeit bleibt, ihn zu vermeiden?","rueckmeldung":[{"option":0,"text":"Große Sicherheit fühlt sich wie ein gutes Zeichen an. Sie sagt aber nur etwas über das Gefühl, nicht über den Vertrag, und bei einer schnellen Entscheidung in komplexer Lage ist sie eher ein Grund für Misstrauen."},{"option":1,"text":"Erfahrung macht das Bauchgefühl durchaus wertvoller als bei Anfängern. Sie ändert aber nichts daran, dass ein Fehler hier teuer wäre und eine Prüfung möglich ist; das Gefühl ersetzt keine Vergleiche."},{"option":2,"text":"Mehr Zeit zu nehmen und die Frist zu nutzen ist ein Fortschritt gegenüber fünf Minuten. Entscheidend ist aber nicht, wie lange man nachdenkt, sondern was man prüft: Daten, Vergleiche, Gegenfragen. Eine Stunde Grübeln mit anschließendem Gefühlsurteil leistet das nicht."}],"familie":"faustregel-oder-rechnen","fertigkeit":"F4","quellen":[{"typ":"url","kurz":"Kahneman, D.; Klein, G. (2009): Conditions for intuitive expertise: a failure to disagree. American Psychologist 64(6), 515–526 (PubMed-Abstract)","oeffentlich":true,"url":"https://pubmed.ncbi.nlm.nih.gov/19739881/","abruf":"2026-10-12"},{"typ":"url","kurz":"Kahneman, D. (2002): Maps of Bounded Rationality. Nobel Prize Lecture, nobelprize.org","oeffentlich":true,"url":"https://www.nobelprize.org/uploads/2018/06/kahnemann-lecture.pdf","seite":"465, 472","abruf":"2026-10-12"}],"thema":"Psychologie","pruefung":{"lauf":"quiz-audit-v4","modell":"claude-sonnet-5-5","datum":"2026-10-14","urteil":"korrigieren","pruefsumme":"e713df9ad09b12d8"}},{"id":"qx-a2-030","clusterId":"A","werkstueckRef":"A.19","stufe":4,"question":"Welcher Denkfehler steckt im Argument des Freundes?","options":["Er hält eine andere Erklärung für ausgeschlossen, ohne einen Beleg zu nennen, der gegen sie spricht.","Er übernimmt die Behauptung, die gerade die Runde macht, und fragt nicht, welche Belege es für sie gibt.","Er lässt nur zwei Möglichkeiten gelten, großen Plan oder reinen Zufall, und übersieht Erklärungen dazwischen.","Er schließt von der Größe des Ereignisses auf eine ebenso große, geordnete Ursache, ohne diese zu prüfen."],"correctIndex":3,"explanation":"Der Freund verlässt sich auf eine Faustregel: Ein großes Ereignis muss auch eine ebenso große Ursache haben. Geplant war der Anschlag zwar, aber von al-Qaida mit 19 Attentätern und nicht von allmächtigen Hintermännern im Verborgenen. Die gewaltigen Folgen sagen also wenig darüber, wie groß und mächtig die Urheber sind; das Gefühl, eine riesige Wirkung verlange eine riesige Ursache, ersetzt keine Prüfung an Belegen.","coreRule":"⚡ Wenn eine Erklärung überzeugt, weil sie so groß ist wie das Ereignis, frage nach Belegen statt nach Stimmigkeit.","beleg":"Werkstück A.19 (Anwendung: Bei Verschwörungsmythen; Kontext & Tiefe: Repräsentativitätsheuristik)","status":"entwurf","scenario":"Nach dem Anschlag vom 11. September 2001 verbreitet sich die Behauptung, dahinter müsse ein langfristig geplanter, geheimer Plan mächtiger Hintermänner stecken. Ein Freund sagt: „So etwas Riesiges kann doch unmöglich einfach so passiert sein.“","kurz":"Aus der Größe eines Ereignisses folgt nicht, dass auch seine Ursache groß und mächtig sein muss. Der Anschlag war geplant, aber von al-Qaida mit 19 Attentätern, nicht von allmächtigen Hintermännern. Ob mehr dahinter steckt, zeigen nur Belege.","prueffrage":"Was müsste man über die Täter eines Anschlags wissen, um zu beurteilen, wie mächtig und gut organisiert sie waren?","rueckmeldung":[{"option":0,"text":"Der Freund nennt tatsächlich keinen Beleg, doch das trifft vieles. Sein besonderer Fehler ist, die Größe der Wirkung als Maß für die Größe der Ursache zu nehmen. Von anderen Erklärungen spricht er gar nicht."},{"option":1,"text":"Dass die Behauptung gerade die Runde macht, ist im Szenario zwar der Anlass. Sein Argument stützt sich aber nicht darauf, dass er sie zuerst gehört hat, sondern allein darauf, wie gewaltig das Ereignis war."},{"option":2,"text":"Das klingt nach einem falschen Entweder-oder, ist aber nicht sein Muster. Der Anschlag war ja geplant, nur eben nicht von allmächtigen Hintermännern. Zufall steht gar nicht zur Wahl, sein Schluss kommt aus der Größe."}],"familie":"deutung-von-fakten-trennen","fertigkeit":"F2","quellen":[{"typ":"url","kurz":"Brotherton, R.; French, C. C. (2014): Belief in Conspiracy Theories and Susceptibility to the Conjunction Fallacy. Applied Cognitive Psychology 28, 238–248 (Repositorium Goldsmiths)","oeffentlich":true,"url":"https://eprints-gro.gold.ac.uk/10794/1/acp2995.pdf","seite":"238","abruf":"2026-10-12"},{"typ":"url","kurz":"National Commission on Terrorist Attacks Upon the United States: The 9/11 Commission Report, Executive Summary","oeffentlich":true,"url":"https://www.9-11commission.gov/report/911Report_Exec.htm","abruf":"2026-10-12"}],"thema":"Geschichte und Wissenschaft","pruefung":{"lauf":"quiz-audit-v9","modell":"claude-sonnet-5-5","datum":"2026-10-15","urteil":"korrigieren","pruefsumme":"1e9f10c00cd16525"}},{"id":"qx-a2-031","clusterId":"A","werkstueckRef":"A.20","stufe":1,"question":"Welche Antwort erklärt am besten, warum die Ärzte damals Semmelweis’ Idee nicht prüften, sondern als „sinnlosen Lärm“ abtaten?","options":["Die Idee der Leichenteilchen passte nicht in den unausgesprochenen Rahmen aus Miasmen und Säftelehre, den alle für selbstverständlich hielten, und galt nicht als ernsthafte Hypothese.","Die Forderung unterstellte den Ärzten, die Krankheit selbst mit ihren eigenen Händen zu übertragen; diese Kränkung ihres Standes ließ sie die Idee abwehren, statt sie nüchtern zu prüfen.","Die Leichenteilchen waren unsichtbar, und eine Ursache, die man mit keinem Mittel sehen konnte, hielten die Ärzte für bloße Spekulation, die eine ernsthafte Prüfung nicht lohnte.","Der Urheber war ein junger Arzt, und die erfahrenen Kollegen gaben der Idee eines so jungen Kollegen von vornherein wenig Gewicht, sodass sie seine Aussagen gar nicht erst ernst nahmen."],"correctIndex":0,"explanation":"Die Ablehnung lässt sich am sparsamsten so erklären: Ein System selbstverständlicher Annahmen (Krankheit durch Miasmen oder Säfteungleichgewicht) bestimmt, was überhaupt als sinnvolle Idee zählt. Innerhalb dieses Rahmens war „Leichenteilchen an den Händen“ keine falsche Hypothese, sondern unverständlich. Solche Rahmen sind meist unbewusst, die Beteiligten halten sie schlicht für „normal“. Das erklärt auch, warum Fakten allein den Streit nicht entschieden: Erst Jahrzehnte später, mit Pasteurs Keimtheorie, wurde Semmelweis’ Idee bestätigt. Ganz unschuldig war Semmelweis allerdings nicht: Er veröffentlichte spät, konnte die Wirkung des Chlorkalks nicht erklären und beschimpfte Kritiker. Auch gekränkter Stolz und Standesdenken der Ärzte spielten mit; das Paradigma erklärt vor allem, warum die Idee als absurd galt. Dass der Urheber jung war, kann mitgespielt haben, erklärt aber nicht, warum die Idee selbst als absurd galt, nämlich weil sie dem Weltbild widersprach.","coreRule":"⚡ Ein Paradigma ist die unsichtbare Karte, nach der ein Fach navigiert: Es entscheidet mit, was als sinnvolle Idee gilt, noch bevor jemand prüft.","beleg":"Werkstück A.20 (Kernidee; Kontext & Tiefe); Fn. ga-kuhn (Kuhn 1962, The Structure of Scientific Revolutions)","status":"entwurf","scenario":"Wien, 1847: Viele Wöchnerinnen sterben am Kindbettfieber. Ein junger Arzt behauptet, unsichtbare Leichenteilchen an den Händen der Ärzte seien die Ursache, und verlangt, dass sich alle vor jeder Untersuchung die Hände in Chlorkalklösung waschen. Seine Kollegen halten das für absurd und beleidigend. Dabei sind sie weder dumm noch unehrlich, sondern erfahrene Ärzte, die sich an dem orientieren, was zu ihrer Zeit als gesichertes Wissen gilt: Krankheiten entstehen durch schlechte Luft (Miasmen) oder ein Ungleichgewicht der Körpersäfte.","quote":"","quoteLabel":"","kurz":"Im Weltbild aus Miasmen und Säften galt „Leichenteilchen an den Händen“ nicht als falsche, sondern als unverständliche Idee. Wer einen Rahmen für selbstverständlich hält, prüft nicht, was ihm widerspricht, und wehrt es als Unsinn ab.","prueffrage":"Wofür hielten die Kollegen die Forderung, und wie würdest du reagieren, wenn du nur ihr damaliges Wissen hättest?","rueckmeldung":[{"option":1,"text":"Gekränkter Stolz und Standesdenken spielten tatsächlich mit. Er erklärt aber nur, warum man sich wehrte, nicht, warum die Idee als absurd und nicht bloß als falsch galt; das liegt am Weltbild der Zeit."},{"option":2,"text":"Unsichtbarkeit wirkt wie ein guter Grund für Skepsis. Doch Miasmen und Säfteungleichgewicht waren ebenso unsichtbar und galten trotzdem als gesichert. Entscheidend war also, was ins Weltbild passte, nicht was man sehen konnte."},{"option":3,"text":"Das jugendliche Alter kann dazu beigetragen haben, dass man ihm weniger zuhörte. Es erklärt aber nicht, warum der Inhalt selbst als sinnlos galt: Er widersprach dem Weltbild, und das hätte auch bei einem älteren Arzt gegolten."}],"familie":"weltsicht-sichtbar-machen","fertigkeit":"F2","quellen":[{"typ":"url","kurz":"Bird, A.: Thomas Kuhn. Stanford Encyclopedia of Philosophy (überarb. 2025)","oeffentlich":true,"url":"https://plato.stanford.edu/entries/thomas-kuhn/","abruf":"2026-10-07"},{"typ":"doi","kurz":"Best, M.; Neuhauser, D. (2004): Ignaz Semmelweis and the birth of infection control. Quality & Safety in Health Care 13(3), 233–234","oeffentlich":true,"doi":"10.1136/qshc.2004.010918","seite":"233–234","abruf":"2026-10-12"},{"typ":"doi","kurz":"Schreiner, S. (2020): Ignaz Semmelweis: a victim of harassment? Wiener Medizinische Wochenschrift 170(11–12), 293–302","oeffentlich":true,"doi":"10.1007/s10354-020-00738-1","abruf":"2026-10-12"}],"thema":"Geschichte und Wissenschaft","pruefung":{"lauf":"quiz-audit-v8","modell":"claude-sonnet-5-5","datum":"2026-10-15","urteil":"korrigieren","pruefsumme":"c12f657806f5f2fe"}},{"id":"qx-a2-033","clusterId":"A","werkstueckRef":"A.20","stufe":3,"question":"Wie ist das Verhalten dieser Fachgesellschaft zu beurteilen, und welcher Schritt wäre sinnvoll?","options":["Das Verhalten ist problematisch, weil die seit Jahren gehäuften Abweichungen ohne Prüfung als Messfehler wegerklärt und die Forscherin ausgegrenzt werden. Sinnvoll wäre, die Daten unabhängig nachzuprüfen.","Das Verhalten ist unproblematisch, weil die Theorie im Alltag gut funktioniert und die meisten Mitglieder gern damit arbeiten. Sinnvoll wäre, die Abweichungen weiter als Messfehler zu verbuchen.","Das Verhalten ist verständlich, weil eine bewährte Theorie nicht bei jeder unpassenden Messung in Frage gestellt werden sollte. Sinnvoll wäre, abzuwarten, ob sich die Abweichungen weiter häufen.","Das Verhalten ist problematisch, weil eine Forscherin wegen ihrer Fragen als Querulantin gilt und ausgegrenzt wird. Sinnvoll wäre, sie wieder zu Tagungen einzuladen, damit ihre Sicht auf die Daten gehört wird."],"correctIndex":0,"explanation":"Ein gemeinsamer Theorierahmen ist nützlich: Er erspart es, bei jeder Beobachtung die Grundlagen neu zu verhandeln, und macht die Arbeit an Detailproblemen effizient. Dass die Theorie meist funktioniert und von vielen geteilt wird, spricht also nicht gegen sie, aber auch nicht gegen die Prüfung von Abweichungen. Problematisch wird ein Rahmen, wenn Abweichungen nicht mehr untersucht, sondern ungeprüft wegerklärt und Kritiker nicht mehr als Herausforderer, sondern als Feinde behandelt werden: Dann erstarrt er zum Dogma. Genau das passiert hier: Die Daten werden ungeprüft abgetan, die Forscherin wird ausgegrenzt. Sinnvoll ist deshalb, die Daten unabhängig nachzuprüfen; ob die Theorie angepasst oder gar ersetzt werden muss, zeigt erst diese Prüfung. Dass die Theorie im Alltag funktioniert, klingt nach einem guten Grund zum Weitermachen, doch ohne Nachprüfung ist „Messfehler“ nur eine Vermutung.","coreRule":"⚡ Ein Rahmen wird zum Dogma, wenn er Abweichungen und Kritiker bekämpft, statt sie zu untersuchen.","beleg":"Werkstück A.20 (Der Kipppunkt; Das Adaptive Talent; Kontext & Tiefe; Einleitung zu Semmelweis)","status":"entwurf","scenario":"In einer Fachgesellschaft häufen sich seit Jahren Messergebnisse, die zur herrschenden Theorie nicht passen. Der Vorstand erklärt sie regelmäßig zu Messfehlern, ohne die Daten nachzuprüfen. Eine Forscherin, die die Abweichungen systematisch untersuchen will, gilt als Querulantin; ihre Beiträge werden nicht mehr zu Tagungen eingeladen. Im Alltag funktioniert die Theorie sonst gut, und die meisten Mitglieder arbeiten gern damit.","kurz":"Die Abweichungen wurden seit Jahren nie geprüft, sondern nur als „Messfehler“ abgetan; das ist eine Vermutung, kein Befund. Wer Kritikerinnen ausgrenzt, statt die Daten unabhängig nachzuprüfen, lässt einen nützlichen Rahmen zum Dogma erstarren.","prueffrage":"Wie lange häufen sich die Abweichungen schon, und was ist mit der Forscherin geschehen, die sie untersuchen wollte?","rueckmeldung":[{"option":1,"text":"Dass die Theorie im Alltag meist gut funktioniert, spricht tatsächlich nicht gegen sie. Es sagt aber nichts darüber, ob die abweichenden Daten stimmen: Ohne Nachprüfung bleibt „Messfehler“ eine bloße Vermutung."},{"option":2,"text":"Eine bewährte Theorie sollte nicht bei jeder einzelnen unpassenden Messung ins Wanken geraten. Hier häufen sich die Abweichungen aber schon seit Jahren, und ohne Untersuchung lässt sich gar nicht beurteilen, ob sich etwas häuft oder nur Rauschen vorliegt."},{"option":3,"text":"Die Ausgrenzung der Forscherin ist ein echtes Warnzeichen, und sie wieder einzuladen wäre ein guter Schritt. Er genügt aber nicht: Solange niemand die Daten selbst nachprüft, bleibt offen, ob die Abweichungen Messfehler sind oder nicht."}],"familie":"weltsicht-sichtbar-machen","fertigkeit":"F2","quellen":[{"typ":"url","kurz":"Bird, A.: Thomas Kuhn. Stanford Encyclopedia of Philosophy (überarb. 2025)","oeffentlich":true,"url":"https://plato.stanford.edu/entries/thomas-kuhn/","abruf":"2026-10-07"}],"thema":"Geschichte und Wissenschaft","pruefung":{"lauf":"quiz-audit-v8","modell":"claude-sonnet-5-5","datum":"2026-10-15","urteil":"korrigieren","pruefsumme":"683e4aa65a595cd2"}},{"id":"qx-a2-034","clusterId":"A","werkstueckRef":"A.20","stufe":4,"question":"Ein Anbieter wirbt für sein „neues Paradigma“ und sagt: „Wer zweifelt, ist noch im alten Denken gefangen.“ Wie bewertest du das?","options":["Als Warnzeichen: Eine Neuerung überzeugt durch bessere Erklärungen; der Satz macht den Anspruch gegen Kritik unangreifbar.","Als berechtigten Hinweis: Wer ein neues Modell fair prüfen will, muss sich zuerst von seinen alten Denkgewohnheiten lösen.","Als übliche Werbesprache: Der Satz spitzt zu, sagt aber über den Wert des neuen Paradigmas weder etwas dafür noch etwas dagegen.","Als Hinweis auf Mut: Neue Ideen stoßen anfangs oft auf Ablehnung, und der Widerstand spricht daher eher für den Anbieter."],"correctIndex":0,"explanation":"Wer Zweifel als Zeichen von Befangenheit abwertet, macht seine Behauptung unprüfbar: Jeder Einwand wird zum Beweis, dass der Kritiker „es nicht verstanden hat“. Eine echte Neuerung in der Wissenschaft setzt sich anders durch: Sie erklärt Beobachtungen, an denen das Alte scheitert, und leistet dabei fast alles, was das Alte leistete. Selbst dann gehen manchmal einzelne Erklärungen verloren, aber nicht der Großteil des Bewährten. Entscheidend ist, ob eine Neuerung mehr erklärt und prüfbar ist. Dass Neues anfangs auf Widerstand stößt, stimmt oft, ist aber kein Gütezeichen: Auch Semmelweis’ Idee setzte sich erst später durch, als sie erklärt werden konnte.","coreRule":"⚡ Eine Neuerung überzeugt durch bessere Erklärungen, nicht dadurch, Kritik zu entwerten.","beleg":"Werkstück A.20 (Anwendung: Bei Pseudowissenschaften & Esoterik; Red Flags: „Kritik wird als Beweis dafür abgetan, dass der Kritiker noch im alten Paradigma gefangen ist“); Fn. ga-kuhn (Kuhn 1962; Bird, SEP „Thomas Kuhn“, Abschn. 2: Kuhn-loss)","status":"entwurf","kurz":"Der Satz macht den Anspruch unangreifbar: Jeder Einwand gilt dann als Beweis, dass der Kritiker „es nicht verstanden hat“. Eine echte Neuerung überzeugt anders, indem sie mehr erklärt und sich prüfen lässt.","prueffrage":"Was erfährt man aus dem Satz des Anbieters über sein Produkt selbst, und was nur über die Zweifler?","rueckmeldung":[{"option":1,"text":"Neues vorurteilsfrei anzusehen ist sinnvoll. Der Satz verlangt aber etwas anderes: Er behandelt den Zweifel selbst als Fehler. Fair prüfen heißt, Belege zu verlangen, nicht, auf Einwände zu verzichten."},{"option":2,"text":"Der Satz belegt tatsächlich nichts über den Wert des Paradigmas. Er ist aber mehr als bloße Zuspitzung: Er wertet jeden Einwand im Voraus ab und macht den Anspruch so unprüfbar, was ein Warnzeichen ist."},{"option":3,"text":"Neue Ideen stoßen oft zunächst auf Widerstand, etwa Semmelweis’ Einsicht. Widerstand allein ist aber kein Gütezeichen, denn auch schwache Ideen werden abgelehnt. Semmelweis setzte sich durch, als seine Idee erklärt werden konnte."}],"familie":"weltsicht-sichtbar-machen","fertigkeit":"F2","quellen":[{"typ":"url","kurz":"Bird, A.: Thomas Kuhn. Stanford Encyclopedia of Philosophy (überarb. 2025), Abschn. 2","oeffentlich":true,"url":"https://plato.stanford.edu/entries/thomas-kuhn/","abruf":"2026-10-07"}],"thema":"Geschichte und Wissenschaft","pruefung":{"lauf":"quiz-audit-v8","modell":"claude-sonnet-5-5","datum":"2026-10-15","urteil":"korrigieren","pruefsumme":"5110356c5a9a7b16"}},{"id":"qx-a2-035","clusterId":"A","werkstueckRef":"A.21","stufe":1,"question":"Du bekommst eine Wette angeboten: Münzwurf, bei Kopf gewinnst du 150 Euro, bei Zahl verlierst du 100 Euro. Du lehnst ab, obwohl du bei vielen Wiederholungen im Schnitt Geld gewinnen würdest. Wie lässt sich deine Ablehnung am besten erklären?","options":["Ein Vorsprung von 25 Euro erscheint dir zu knapp für die Summe, die bei einem Wurf auf dem Spiel steht, obwohl der Durchschnitt positiv ist.","Dir zählt bei einem einzelnen Wurf allein, dass du dabei ebenso gut verlieren wie gewinnen kannst, obwohl der Durchschnitt positiv ist.","Du richtest dich nach dem ungünstigsten Ausgang, also dem Verlust von 100 Euro, statt nach beiden Ausgängen, obwohl der Durchschnitt positiv ist.","Ein möglicher Verlust von 100 Euro wiegt für dich schwerer als ein möglicher Gewinn von 150 Euro, obwohl der Durchschnitt positiv ist."],"correctIndex":3,"explanation":"Der Durchschnittswert der Wette liegt bei +25 Euro (0,5 × 150 − 0,5 × 100). Trotzdem lehnen die meisten Menschen ab, weil ein möglicher Verlust von 100 Euro stärker wiegt als ein gleich großer Gewinn. Das ist Verlustaversion, ein Kernstück der Prospect Theory von Kahneman und Tversky: Entschieden wird nicht über absolute Endzustände, sondern über Gewinne und Verluste relativ zu einem Referenzpunkt (dem, was man schon hat). In der Messung von 1992 zählte ein Verlust etwa doppelt so stark wie ein gleich hoher Gewinn. Die Scheu vor unbekannten Chancen klingt vorsichtig, scheitert aber daran, dass die Münze fair ist und die Chancen bekannt sind. Die Überschätzung kleiner Wahrscheinlichkeiten ist ein bekannter Effekt, passt aber nicht, weil 50 Prozent keine kleine Wahrscheinlichkeit sind. Die Gegenwartsverzerrung klingt einleuchtend, doch Gewinn wie Verlust träten sofort ein.","coreRule":"⚡ Verluste wiegen meist schwerer als gleich große Gewinne (in der klassischen Messung etwa doppelt), deshalb lehnen viele auch Wetten mit positivem Durchschnitt ab.","beleg":"Werkstück A.21 (Einstiegsgeschichte; Kernidee); Fn. ga-prospect (Kahneman/Tversky 1979, Econometrica 47(2), S. 279; Tversky/Kahneman 1992, S. 311)","status":"entwurf","scenario":"Eine Freundin schlägt dir vor: „Wir werfen eine faire Münze. Bei Kopf zahle ich dir 150 Euro, bei Zahl zahlst du mir 100 Euro.“ Du merkst, dass du eigentlich keine Lust darauf hast, obwohl du nachrechnest, dass du im Durchschnitt 25 Euro pro Wurf gewinnen würdest.","kurz":"Der mögliche Verlust von 100 Euro wiegt psychologisch schwerer als ein möglicher Gewinn von 150 Euro. Verluste zählen etwa doppelt so stark wie gleich große Gewinne, daher kann die Wette trotz +25 Euro im Schnitt abschreckend wirken.","prueffrage":"Was ergibt 0,5 × 150 − 0,5 × 100, und reicht dieses Ergebnis, damit du zusagst?","rueckmeldung":[{"option":0,"text":"Ein Vorsprung von 25 Euro kann bei hohem Einsatz tatsächlich mager wirken. Doch bei 150 Euro Gewinnchance gegen 100 Euro Verlust ist der Vorteil nicht klein; die Ablehnung kommt eher daher, dass der Verlust stärker zählt als der Gewinn."},{"option":1,"text":"Dass du bei einem Wurf auch verlieren kannst, ist richtig, gilt aber ebenso für den Gewinn. Das bloße Risiko erklärt die Ablehnung nicht. Erst die ungleiche Gewichtung, bei der der Verlust schwerer wiegt, macht die Wette unattraktiv."},{"option":2,"text":"Die Sorge vor dem schlechtesten Fall liegt nahe und würde zur Ablehnung führen. Ganz ausgeblendet wird der Gewinn aber nicht: Beide Ausgänge fließen ein, nur zählt der Verlust etwa doppelt so stark, ein Unterschied in der Gewichtung."}],"familie":"verlust-und-gewinn-abwaegen","fertigkeit":"F4","quellen":[{"typ":"url","kurz":"Kahneman, D. (2002): Maps of Bounded Rationality. Nobel Prize Lecture, nobelprize.org","oeffentlich":true,"url":"https://www.nobelprize.org/uploads/2018/06/kahnemann-lecture.pdf","seite":"461–462","abruf":"2026-10-12"},{"typ":"doi","kurz":"Tversky, A.; Kahneman, D. (1992): Advances in Prospect Theory: Cumulative Representation of Uncertainty. Journal of Risk and Uncertainty 5(4), 297–323","oeffentlich":false,"doi":"10.1007/BF00122574","seite":"311"}],"thema":"Geld und Zahlen","pruefung":{"lauf":"quiz-audit-v8","modell":"claude-sonnet-5-5","datum":"2026-10-15","urteil":"korrigieren","pruefsumme":"702a670cef1dcfaa"}},{"id":"qx-a2-036","clusterId":"A","werkstueckRef":"A.21","stufe":2,"question":"Ein Anleger hat zwei Aktien: eine liegt 30 % im Plus, die andere 30 % im Minus. Er muss eine davon verkaufen und sagt: „Die Gewinneraktie nehme ich mit, die Verliererin behalte ich, die erholt sich schon wieder.“ Welche Erklärung für dieses Verhalten passt zu dem, was die Prospect Theory über Entscheidungen unter Unsicherheit beschreibt?","scenario":"Ein Anleger besitzt zwei Aktien: Die eine liegt 30 % im Plus, die andere 30 % im Minus. Er muss eine verkaufen und entscheidet sich für die Gewinneraktie. Die Verliereraktie behält er und sagt: „Die erholt sich schon wieder.“","options":["Er handelt in beiden Fällen vorsichtig: Den Gewinn nimmt er sicher mit, und beim Verlust wartet er lieber ab, statt ihn voreilig und endgültig festzuschreiben.","Im Plus will er den sicheren Gewinn festhalten, im Minus wagt er lieber das Risiko eines noch größeren Verlusts, um die Chance auf Rückkehr zum Einstandskurs zu wahren.","Er gibt der unsicheren Aussicht auf eine Erholung mehr Gewicht, als ihre Wahrscheinlichkeit hergibt, und hält darum an der Verliereraktie mit ihren 30 % Minus fest.","Was er besitzt, schätzt er höher ein, als er es heute kaufen würde; deshalb fällt es ihm so schwer, sich von der Verliereraktie mit ihren 30 % Minus zu trennen."],"correctIndex":1,"explanation":"Die Prospect Theory beschreibt ein asymmetrisches Risikoverhalten: Im Bereich der Gewinne bevorzugen Menschen den sicheren, kleineren Gewinn, im Bereich der Verluste nehmen sie lieber ein größeres Risiko in Kauf, um den Verlust vielleicht ganz zu vermeiden. Der Referenzpunkt ist dabei der Einstandskurs. Deshalb werden Gewinne oft zu früh realisiert und Verluste zu lange gehalten. Der Satz „die erholt sich schon wieder“ ist selbst ein Warnzeichen: Er begründet das Festhalten mit der Hoffnung, nicht mit einer Prüfung der Aussichten. Die klärende Frage lautet: „Würde ich diese Aktie heute zu diesem Kurs neu kaufen?“ Wenn nicht, spricht wenig fürs Halten. Wenn ja, ist das Halten begründet, aber dann nicht wegen des Verlusts.","coreRule":"⚡ Gewinne sichern wir zu früh, Verluste halten wir zu lange.","beleg":"Werkstück A.21 (Kontext & Tiefe, Pfeiler 3; Anwendung: finanzielle Entscheidungen); Fn. ga-prospect-gewichtung (Kahneman/Tversky 1979, S. 268–269)","status":"entwurf","kurz":"Im Plus wählt man eher den sicheren Gewinn, im Minus eher das Risiko, den Verlust doch noch auszugleichen. Der Einstandskurs dient dabei als Maßstab, und „die erholt sich schon“ ist oft Hoffnung statt Prüfung.","prueffrage":"Was tut der Anleger mit der Gewinneraktie, was mit der Verliererin, und womit begründet er das Halten?","rueckmeldung":[{"option":0,"text":"Beim Gewinn stimmt das: Er wird gesichert. Das Festhalten am Verlust ist aber keine Vorsicht, sondern eine Wette: Wer abwartet, riskiert einen noch größeren Verlust, um den Einstandskurs vielleicht wieder zu erreichen."},{"option":2,"text":"Hoffnung auf Erholung spielt hier tatsächlich eine Rolle. Das Szenario nennt aber keine Wahrscheinlichkeit, und die Antwort erklärt nicht, warum er den Gewinn sichert, den Verlust aber nicht: Es fehlt der Wechsel im Risikoverhalten ab dem Einstandskurs."},{"option":3,"text":"Dass man Besitz höher bewertet, gibt es wirklich, es ist aber ein anderer Effekt. Er erklärt nicht, warum die Gewinneraktie so leicht verkauft wird, und lässt den Einstandskurs als Maßstab für Gewinn und Verlust außen vor."}],"familie":"verlust-und-gewinn-abwaegen","fertigkeit":"F4","quellen":[{"typ":"url","kurz":"Kahneman, D. (2002): Maps of Bounded Rationality. Nobel Prize Lecture, nobelprize.org","oeffentlich":true,"url":"https://www.nobelprize.org/uploads/2018/06/kahnemann-lecture.pdf","seite":"461–462","abruf":"2026-10-12"},{"typ":"url","kurz":"Odean, T.: Are Investors Reluctant to Realize Their Losses? (Autorenseite, UC Berkeley)","oeffentlich":true,"url":"https://faculty.haas.berkeley.edu/odean/papers/disposition/disposition.html","abruf":"2026-10-12"},{"typ":"doi","kurz":"Kahneman, D.; Tversky, A. (1979): Prospect Theory: An Analysis of Decision under Risk. Econometrica 47(2), 263–291","oeffentlich":false,"doi":"10.2307/1914185","seite":"268"}],"thema":"Geld und Zahlen","pruefung":{"lauf":"quiz-audit-v8","modell":"claude-sonnet-5-5","datum":"2026-10-15","urteil":"korrigieren","pruefsumme":"d541b12f0dca87bf"}},{"id":"qx-a2-037","clusterId":"A","werkstueckRef":"A.21","stufe":3,"question":"Was ist an der Aussage des Kollegen fehlerhaft?","scenario":"Eine Beraterin legt einem Kunden zwei Aufgaben vor. Aufgabe 1: Du erhältst zuerst 1.000 € und wählst dann zwischen A) garantiert weiteren 500 € und B) Münzwurf: bei Kopf weitere 1.000 €, bei Zahl nichts. Aufgabe 2: Du erhältst zuerst 2.000 € und wählst dann zwischen C) garantiert 500 € Verlust und D) Münzwurf: bei Kopf 1.000 € Verlust, bei Zahl nichts. In einem Test wählt die Mehrheit bei Aufgabe 1 die sichere Option A und bei Aufgabe 2 den Münzwurf D. Ein Kollege sagt: „Die Leute haben eben zwei unterschiedliche Situationen bewertet, das ist völlig vernünftig.“","options":["Er übersieht, dass A und C beide sicher 1.500 € ergeben und B und D beide je zur Hälfte 1.000 € oder 2.000 €; nur die Rahmung als Gewinn oder Verlust unterscheidet die Aufgaben.","Er übersieht, dass die Startbeträge verschieden sind: Wer schon 2.000 € erhalten hat, kann sich einen Münzwurf eher leisten als jemand, der erst 1.000 € bekommen hat.","Er übersieht nichts Wesentliches: Ein Verlust fühlt sich schlimmer an als ein entgangener Gewinn, deshalb dürfen die Leute die beiden Aufgaben durchaus verschieden behandeln.","Er übersieht, dass dieselbe Mehrheit einmal Sicherheit und einmal Risiko wählt; das zeigt bloß schwankende Launen, die mit dem Aufbau der Aufgaben nichts zu tun haben."],"correctIndex":0,"explanation":"Rechne die Endzustände durch: Bei A hast du garantiert 1.000 € + 500 € = 1.500 €, bei C garantiert 2.000 € − 500 € = 1.500 €. Bei B ergibt sich je zur Hälfte 2.000 € oder 1.000 €, bei D je zur Hälfte 1.000 € oder 2.000 €, also im Schnitt jeweils 1.500 €. Aufgabe 1 und Aufgabe 2 sind daher in der Sache identisch. Trotzdem wählen die meisten bei der Gewinnrahmung die sichere Option und bei der Verlustrahmung den Münzwurf. Das ist kein vernünftiger Unterschied in der Lage, sondern ein Rahmungseffekt: Wer von einem Referenzpunkt aus in Gewinnen denkt, meidet Risiko; wer in Verlusten denkt, geht es ein, um den sicheren Verlust zu vermeiden. Wäre die Wahl rein vom Endzustand bestimmt, müsste sie in beiden Aufgaben gleich ausfallen.","coreRule":"⚡ Gleiche Fakten, andere Rahmung: Prüfe zuerst die Endzustände. Ändert sich die Entscheidung nur durch die Formulierung als Gewinn oder Verlust, steuert der Referenzpunkt dein Risikoverhalten.","beleg":"Werkstück A.21 (Das Härten im Feuer: Die Schmiede-Übung; Red Flags)","status":"entwurf","kurz":"Rechnet man die Endzustände durch, sind beide Aufgaben identisch: sicher 1.500 € oder je zur Hälfte 1.000 € bzw. 2.000 €. Der naheliegende Fehler ist, die Aufgaben nach ihrer Darstellung als Gewinn oder Verlust zu bewerten statt nach dem, was am Ende herauskommt.","prueffrage":"Mit welchem Betrag gehst du in jeder der vier Varianten nach der Entscheidung nach Hause?","rueckmeldung":[{"option":1,"text":"Die Startbeträge unterscheiden sich tatsächlich, nur zählt am Ende die Summe. Wer 2.000 € bekommt und 500 € verliert, steht bei 1.500 €, genau wie nach 1.000 € plus 500 €. Das Mehr an Startgeld ändert also nichts."},{"option":2,"text":"Dass Verluste stärker wirken als gleich große Gewinne, stimmt. Das erklärt aber nur, warum die Wahl kippt, es macht sie nicht vernünftig: Bei gleichem Endzustand müsste die Entscheidung gleich ausfallen. Genau das ist der Fehler."},{"option":3,"text":"Der Wechsel zwischen Sicherheit und Risiko ist richtig beobachtet. Er ist aber keine Laune, sondern folgt der Darstellung: Bei Gewinnen wird das Risiko gemieden, bei Verlusten gesucht. Der Aufbau der Aufgaben steuert die Wahl also doch."}],"familie":"rahmen-wechseln","fertigkeit":"F2","quellen":[{"typ":"url","kurz":"Kahneman, D. (2002): Maps of Bounded Rationality. Nobel Prize Lecture, nobelprize.org","oeffentlich":true,"url":"https://www.nobelprize.org/uploads/2018/06/kahnemann-lecture.pdf","seite":"461–463","abruf":"2026-10-12"},{"typ":"doi","kurz":"Kahneman, D.; Tversky, A. (1979): Prospect Theory: An Analysis of Decision under Risk. Econometrica 47(2), 263–291","oeffentlich":false,"doi":"10.2307/1914185","seite":"268"}],"thema":"Geld und Zahlen","pruefung":{"lauf":"quiz-audit-v9","modell":"claude-sonnet-5-5","datum":"2026-10-15","urteil":"ok","pruefsumme":"cc263e1bcbe75dc3"}},{"id":"qx-a2-038","clusterId":"A","werkstueckRef":"A.21","stufe":4,"question":"Wie sollte das Team jetzt vorgehen?","options":["Den Verlust-Slogan sofort für alle Besucher einführen, weil die Theorie gut belegt ist und Vorsorge-Studien nichts über Käufe aussagen.","Den Gewinn-Slogan behalten, weil die Auswertung der Vorsorge-Studien einen Vorteil der Gewinn-Version zeigt, der auch für Käufe gilt.","Beide Slogans an zufällig geteilten Besuchergruppen testen, weil die Theorie für diesen Shop nur eine plausible Erwartung liefert.","Den Verlust-Slogan einführen und die Verkäufe vorher und nachher vergleichen, weil sich so seine Wirkung im echten Shop zeigt."],"correctIndex":2,"explanation":"Aus einer gut belegten Theorie über Entscheidungen unter Unsicherheit folgt nicht automatisch, dass ein bestimmter Werbesatz besser verkauft. Zwischen Theorie und Anwendung liegen viele Zwischenschritte: Wie nehmen Menschen die Botschaft wahr, wie viel Aufmerksamkeit schenken sie ihr, welche Alternativen haben sie? Die Metaanalyse, auf die die Kollegin anspielt (O'Keefe und Jensen 2007, 93 Studien mit 21.656 Teilnehmenden zu Vorsorge-Botschaften, also nicht zu Werbung), fand einen sehr kleinen Vorteil des Gewinn-Frames (r = 0,03). Das lässt sich nicht direkt auf Kaufverhalten übertragen, zeigt aber, dass Frame-Effekte klein und uneinheitlich sein können. Die Erwartung des Teams ist daher eine plausible Hypothese, keine gesicherte Wirkung; da der Shop beide Versionen zufällig verteilen kann, lässt sie sich mit einem Vergleichstest messen. Dass die Vorsorge-Befunde nicht übertragbar sind, stimmt zwar, macht die Theorie aber noch nicht zur gemessenen Wirkung. Umgekehrt gilt auch der winzige Gewinn-Vorteil aus der Gesundheitsforschung nicht einfach für Käufe.","coreRule":"⚡ Was eine Theorie nahelegt, muss sich in der Praxis erst messen lassen.","beleg":"Werkstück A.21 (Anwendung: Im Marketing); Fn. ga-framing-persuasion (O'Keefe/Jensen 2007, Journal of Health Communication 12(7), S. 623–644)","status":"entwurf","scenario":"Ein Marketingteam will im Onlineshop den Slogan „Jetzt kaufen und 20 % sparen!“ durch „Verpass nicht die Chance, 20 % zu sparen!“ ersetzen. Begründung: Bei Entscheidungen unter Risiko wiegen Verluste nachweislich schwerer als gleich hohe Gewinne. Eine Kollegin wendet ein, eine Auswertung vieler Studien zu Botschaften über Krankheitsvorsorge habe kaum einen Unterschied zwischen beiden Formulierungen gefunden, eher einen winzigen Vorteil für die Gewinn-Version. Der Shop kann jeden Slogan einem zufällig ausgewählten Teil der Besucher zeigen.","kurz":"Die Theorie liefert für diesen Shop nur eine plausible Erwartung, keine gemessene Wirkung, und Frame-Effekte können klein sein. Der Fehler wäre, von der Theorie direkt auf den Slogan zu schließen; ein Test mit zufällig geteilten Gruppen zeigt die Wirkung.","prueffrage":"Wer hat den Unterschied zwischen beiden Slogans an genau diesen Besuchern und ihren Käufen schon einmal gemessen?","rueckmeldung":[{"option":0,"text":"Dass sich die Vorsorge-Studien nicht einfach übertragen lassen, stimmt. Eine gut belegte Theorie ist damit aber noch keine gemessene Wirkung im Shop, und Frame-Effekte fallen oft klein und uneinheitlich aus. Ohne Test bleibt die Einführung eine Wette."},{"option":1,"text":"Die Auswertung zeigt nur einen winzigen Vorteil (r = 0,03) und betrifft Vorsorge-Botschaften, nicht Werbung. Ihn auf Käufe zu übertragen, ist dieselbe ungeprüfte Übertragung wie bei der Theorie, nur mit umgekehrtem Vorzeichen."},{"option":3,"text":"Echte Verkaufszahlen zu nutzen ist richtig. Ein Vorher-Nachher-Vergleich trennt aber nicht, was der Slogan bewirkt und was etwa Saison oder andere Aktionen in derselben Zeit verändern. Zufällig geteilte Gruppen leisten das, und der Shop kann sie bilden."}],"familie":"befund-reichweite","fertigkeit":"F1","quellen":[{"typ":"url","kurz":"O’Keefe, D. J.; Jensen, J. D. (2007): The relative persuasiveness of gain-framed and loss-framed messages for encouraging disease prevention behaviors: a meta-analytic review. Journal of Health Communication 12(7), 623–644 (PubMed-Abstract)","oeffentlich":true,"url":"https://pubmed.ncbi.nlm.nih.gov/17934940/","abruf":"2026-10-12"},{"typ":"doi","kurz":"O’Keefe, D. J.; Jensen, J. D. (2007), Verlagsfassung","oeffentlich":false,"doi":"10.1080/10810730701615198"}],"thema":"Netz und Medien","pruefung":{"lauf":"quiz-audit-v8","modell":"claude-sonnet-5-5","datum":"2026-10-15","urteil":"korrigieren","pruefsumme":"ab29943aa833d74a"}},{"id":"qx-a2-039","clusterId":"A","werkstueckRef":"A.22","stufe":1,"question":"Ein Video-Kommentar zu einer Termitenburg lautet: „So ein Bauwerk mit Belüftungsschächten und Kühlsystem braucht zwingend einen Gesamtplan. Irgendwo muss der gespeichert sein, sonst wäre das reiner Zufall.“ Was ist an dieser Schlussfolgerung fehlerhaft?","options":["Sie übersieht, dass komplexe Ordnung keinen zentralen Plan braucht. Sie kann aus einfachen Regeln und Wechselwirkungen vieler Tiere entstehen, ohne dass ein Gesamtplan existiert.","Sie übersieht, dass die Duftsignale den Plan weitertragen. Jede Termite meldet ihren Nachbarn, wo gebaut werden soll, und so verteilt sich der Gesamtplan über die ganze Kolonie.","Sie übersieht, dass der Plan im Erbgut jeder Termite gespeichert ist und Schritt für Schritt in Bauverhalten übersetzt wird. Er liegt also nicht an einem Ort, sondern in Tausenden Tieren.","Sie übersieht, dass das zuerst abgelegte Material die Form vorgibt, an der die übrigen Tiere weiterbauen. So steckt der Plan von Beginn an im entstehenden Bauwerk selbst."],"correctIndex":0,"explanation":"Der Schluss „komplexes Ergebnis, also muss es einen Plan geben“ ist ein Fehlschluss. Einzelne Tiere folgen simplen Regeln und kennen weder Belüftungsschacht noch Gesamtform. Erst das Zusammenspiel vieler Individuen erzeugt Strukturen auf der höheren Ebene, die man aus der Untersuchung eines einzelnen Tieres nicht vorhersagen könnte. Das nennt man Emergenz. Ein zentraler Plan ist dafür nicht nötig. Eine sinnvolle Gegenprobe ist die Frage, welche einfachen Regeln und Wechselwirkungen das Ergebnis erzeugen könnten. Der Verallgemeinerungseinwand klingt nach einem bekannten Denkfehler, trifft aber nicht, denn der Kommentar spricht über dieses eine Bauwerk. Ein Plan im Erbgut klingt nach einem gespeicherten Bauplan, widerspricht aber der Beschreibung, dass jedes Tier nur einfachen Reaktionsregeln folgt. Der Gedanke, der Zweck sei nur hineingelesen, klingt nach einem bekannten Fehler, doch Belüftung und Temperaturregelung sind im Szenario als tatsächliche Leistung des Baus beobachtet.","coreRule":"⚡ Komplexe Ordnung braucht keinen zentralen Plan: Sie kann aus den Beziehungen einfacher Teile entstehen.","beleg":"Werkstück A.22 (Einstiegsgeschichte; Kernidee)","status":"entwurf","scenario":"Eine Termitenkolonie besteht aus Tausenden Tieren. Jedes folgt nur einfachen Reaktionsregeln, etwa „Lege Material ab, wo schon Material liegt“ oder „Folge dem Duftsignal der Nachbarn“. Beobachtet wird: Das Gesamtbauwerk ist komplex und zweckmäßig, etwa mit Belüftung und Temperaturregelung.","kurz":"Aus einem komplexen Ergebnis folgt nicht, dass ein Gesamtplan existiert. Wenn viele Tiere einfachen Regeln folgen, kann sich beim Zusammenspiel Ordnung bilden, die kein einzelnes Tier kennt. Der Denkfehler: Komplexität wird mit Planung gleichgesetzt.","prueffrage":"Weiß eine einzelne Termite, wie der fertige Bau aussehen soll, und woran würdest du das erkennen?","rueckmeldung":[{"option":1,"text":"Dass Duftsignale eine Rolle spielen, steht im Szenario. Sie dienen aber als Reiz, auf den jedes Tier reagiert, und melden keinen Bauplan weiter. Sie sind Teil der Wechselwirkung, aus der die Ordnung entsteht, ohne dass ein Gesamtplan nötig ist."},{"option":2,"text":"Ein im Erbgut gespeicherter Bauplan würde bedeuten, dass jedes Tier die Gesamtform kennt. Laut Szenario folgt aber jedes nur einfachen Reaktionsregeln. Das Bauwerk entsteht erst aus dem Zusammenspiel vieler Tiere, nicht aus einem verteilten Plan."},{"option":3,"text":"Dass abgelegtes Material die Stelle für weiteres Material festlegt, stimmt: So lautet eine der Regeln. Daraus folgt aber keine vorgegebene Gesamtform. Belüftung und Kühlung ergeben sich erst aus dem Zusammenspiel vieler Tiere und ihrer Regeln."}],"familie":"auslese-statt-plan","fertigkeit":"F1","quellen":[{"typ":"doi","kurz":"Calovi, D. S. u. a. (2019): Surface curvature guides early construction activity in mound-building termites. Phil. Trans. R. Soc. B 374","oeffentlich":true,"doi":"10.1098/rstb.2018.0374","abruf":"2026-10-12"},{"typ":"url","kurz":"O'Connor, T.: Emergent Properties. Stanford Encyclopedia of Philosophy","oeffentlich":true,"url":"https://plato.stanford.edu/entries/properties-emergent/","abruf":"2026-10-12"},{"typ":"url","kurz":"Reynolds, C. W.: Boids (Background and Update), red3d.com","oeffentlich":true,"url":"https://www.red3d.com/cwr/boids/","abruf":"2026-10-12"}],"thema":"Natur und Klima","pruefung":{"lauf":"quiz-audit-v8","modell":"claude-sonnet-5-5","datum":"2026-10-15","urteil":"korrigieren","pruefsumme":"cecbdceafb3d38fa"}},{"id":"qx-a2-040","clusterId":"A","werkstueckRef":"A.22","stufe":2,"question":"Ein Redner sagt: „Wasser ist nass, obwohl weder Wasserstoff noch Sauerstoff nass sind. Das beweist, dass man nichts verstehen kann, wenn man nur die Einzelteile untersucht.“ Wo liegt der Fehler in dieser Schlussfolgerung?","options":["Er irrt in der Sache: Die Nässe steckt schon in Wasserstoff und Sauerstoff selbst; man muss die Einzelteile nur genau genug untersuchen, um sie dort abzulesen.","Er geht zu weit: Dass sich die Nässe des Wassers nicht aus Wasserstoff und Sauerstoff allein ablesen lässt, heißt nicht, dass die Einzelteile unwichtig sind.","Er hat im Kern recht und drückt sich nur zu scharf aus: Am Wasser zeigt sich, dass man das Ganze von oben betrachten muss statt von seinen Teilen her.","Er verallgemeinert vorschnell: Für das Wasser mag sein Befund gelten, doch ein einziges Beispiel trägt noch kein Urteil über alle anderen Stoffe."],"correctIndex":1,"explanation":"Die Beobachtung stimmt: Wasserstoff ist ein brennbares Gas, Sauerstoff nährt Feuer, aber Wasser ist flüssig, hat Oberflächenspannung und macht Dinge nass. Ein einzelnes H₂O-Molekül ist nicht nass; die Eigenschaft zeigt sich erst im Zusammenspiel unzähliger Moleküle, die über Wasserstoffbrücken aneinander haften. Der Fehler liegt im Sprung von „nicht an einem einzelnen Teil ablesbar“ zu „Teile untersuchen bringt nichts“. Gerade die Kräfte zwischen den Molekülen erklären, warum Wasser Tropfen bildet und Oberflächen benetzt: Nässe widerspricht der Chemie nicht, sie baut auf ihr auf. Wer verstehen will, muss also die Teile und ihr Zusammenspiel untersuchen, nicht das eine statt des anderen. Der Zusammensetzungsfehlschluss klingt nach einem bekannten Denkfehler, trifft aber nicht: Der Redner schließt nicht von den Gasen auf das Wasser, er betont ja gerade den Unterschied. Der Vorwurf der Mehrdeutigkeit klingt scharfsinnig, doch „nass“ wird durchgehend im selben Sinn verwendet. Die Hoffnung auf Rechenleistung klingt nach dem Programm der Reduktion, scheitert aber daran, dass sich Nässe aus einem einzelnen Molekül nicht ablesen lässt, so viel man auch rechnet.","coreRule":"⚡ Eine emergente Eigenschaft steckt in den Beziehungen der Teile, nicht in den Teilen selbst, und sie baut auf den Gesetzen der Teile auf, statt ihnen zu widersprechen.","beleg":"Werkstück A.22 (Einstiegsgeschichte, Das Wasser; Anti-Denkmuster: Konsistenz)","status":"entwurf","scenario":"","kurz":"Dass sich Nässe nicht an einem einzelnen Teil ablesen lässt, stimmt, beweist aber nicht, dass Teile untersuchen nichts bringt. Gerade die Kräfte zwischen den Molekülen erklären die Nässe: Man braucht Teile und Zusammenspiel.","prueffrage":"Woher stammt das heutige Wissen darüber, warum Wasser Tropfen bildet und Oberflächen benetzt?","rueckmeldung":[{"option":0,"text":"Dass die Nässe aus den Teilen erklärbar ist, trifft zu, aber sie steckt nicht in ihnen: Weder die Gase noch ein einzelnes Molekül sind nass. Sie zeigt sich erst im Zusammenspiel vieler Moleküle, und das lässt sich auch mit genauerer Untersuchung der Einzelteile nicht ablesen."},{"option":2,"text":"Daran stimmt: Nässe ist an einem einzelnen Teil nicht ablesbar. Daraus folgt aber nicht, dass man die Teile durch eine Sicht von oben ersetzen muss. Erklärt wird die Nässe gerade durch die Teile und ihre Kräfte, beides gehört zusammen."},{"option":3,"text":"Die Zahl der Beispiele ist hier nicht der Knackpunkt, denn das Wasserbeispiel selbst stimmt. Der Fehler liegt im Sprung von „nicht am einzelnen Teil ablesbar“ zu „Teile untersuchen bringt nichts“, und der wäre auch mit hundert weiteren Beispielen unbegründet."}],"familie":"auslese-statt-plan","fertigkeit":"F1","quellen":[{"typ":"url","kurz":"USGS Water Science School: Adhesion and Cohesion Water","oeffentlich":true,"url":"https://www.usgs.gov/special-topics/water-science-school/science/adhesion-and-cohesion-water","abruf":"2026-10-12"},{"typ":"url","kurz":"USGS Water Science School: Surface Tension and Water","oeffentlich":true,"url":"https://www.usgs.gov/special-topics/water-science-school/science/surface-tension-and-water","abruf":"2026-10-12"},{"typ":"url","kurz":"O'Connor, T.: Emergent Properties. Stanford Encyclopedia of Philosophy","oeffentlich":true,"url":"https://plato.stanford.edu/entries/properties-emergent/","abruf":"2026-10-12"}],"thema":"Geschichte und Wissenschaft","pruefung":{"lauf":"quiz-audit-v8","modell":"claude-sonnet-5-5","datum":"2026-10-15","urteil":"korrigieren","pruefsumme":"8bea760f9e8e475d"}},{"id":"qx-a2-041","clusterId":"A","werkstueckRef":"A.22","stufe":3,"question":"Du hörst in einer Diskussion diese Erklärung: „Wie die Methode wirkt? Das ist eine emergente Eigenschaft des Quantenfeldes.“ Was ist an dieser Antwort der entscheidende Schwachpunkt?","options":["Die Antwort benennt keinen Mechanismus: Es bleibt offen, welche Wechselwirkungen welcher Teile die behauptete Wirkung erzeugen sollen.","Die Antwort ist in Fachsprache gehalten: Wer Begriffe wie Emergenz und Quantenfeld nicht kennt, kann gar nicht beurteilen, ob sie zutrifft.","Die Antwort stützt sich auf die Quantenphysik: Ein Gebiet, das selbst noch nicht ganz verstanden ist, kann eine Heilmethode kaum sicher erklären.","Die Antwort stammt von der Anbieterin selbst: Eine Erklärung derjenigen, die die Methode anbietet, ersetzt keine unabhängige Prüfung."],"correctIndex":0,"explanation":"Emergenz beschreibt nur, dass auf einer höheren Ebene Eigenschaften auftauchen, die einzelne Teile nicht zeigen. Sie erklärt nichts, solange offen bleibt, wie das geschieht. Ein Verkehrsforscher kann die Regeln nennen, nach denen aus dem Verhalten einzelner Fahrer ein Stau entsteht. Wer dagegen nur sagt „Das ist emergent“, ersetzt den Mechanismus durch ein Etikett und beendet die Diskussion, statt sie zu beginnen. Prüffragen: Welche Interaktionen zwischen welchen Komponenten erzeugen die Wirkung? Und widerspricht sie bekannten physikalischen Gesetzen? Echte Emergenz baut auf den Gesetzen der unteren Ebene auf und bricht sie nicht.","coreRule":"⚡ „Es ist emergent“ ist keine Erklärung, solange kein Mechanismus benannt wird.","quote":"Das ist eine emergente Eigenschaft des Quantenfeldes.","quoteLabel":"Beispielantwort:","beleg":"Werkstück A.22 (Anwendung: Pseudowissenschaftlicher Missbrauch; Der Kipppunkt; Aktivierungs-Frage 1)","status":"entwurf","scenario":"Eine Anbieterin von „Energieheilung“ wird gefragt, wie ihre Methode funktioniert. Sie antwortet: „Das ist eine emergente Eigenschaft des Quantenfeldes.“ Danach geht das Gespräch zu einem anderen Thema über.","kurz":"Wer nur sagt „Das ist emergent“, setzt ein Etikett an die Stelle des Mechanismus. Gerade das „Wie“, welche Teile wie wechselwirken und die Wirkung erzeugen, bleibt offen, und so endet die Diskussion, statt zu beginnen.","prueffrage":"Was sagt die Anbieterin nach diesem Satz noch über ihre Methode, und was weiß man danach mehr als vorher?","rueckmeldung":[{"option":1,"text":"Fachwörter können einschüchtern, doch man muss sie nicht kennen, um zu bemerken, dass kein Wirkweg genannt wird. Man kann nachfragen. Schwach ist die Antwort, weil das „Wie“ fehlt, nicht weil die Wörter schwer sind."},{"option":2,"text":"Offene Fragen gibt es in der Quantenphysik tatsächlich, doch ihre Anwendungen sind sehr gut bestätigt. Unvollständiges Wissen erlaubt nicht jede Behauptung. Entscheidend ist, dass die Antwort keinen Mechanismus nennt."},{"option":3,"text":"Eigenaussagen von Anbietenden ersetzen tatsächlich keine unabhängige Prüfung. Das Problem liegt aber in der Antwort selbst: Sie liefert ein Etikett statt eines Mechanismus, ganz gleich, wer sie gibt."}],"familie":"mechanismus-verlangen","fertigkeit":"F1","quellen":[{"typ":"url","kurz":"Craver, C.; Tabery, J.; Illari, P.: Mechanisms in Science. Stanford Encyclopedia of Philosophy","oeffentlich":true,"url":"https://plato.stanford.edu/entries/science-mechanisms/","abruf":"2026-10-12"},{"typ":"url","kurz":"O'Connor, T.: Emergent Properties. Stanford Encyclopedia of Philosophy","oeffentlich":true,"url":"https://plato.stanford.edu/entries/properties-emergent/","abruf":"2026-10-12"},{"typ":"url","kurz":"Reynolds, C. W.: Boids (Background and Update), red3d.com","oeffentlich":true,"url":"https://www.red3d.com/cwr/boids/","abruf":"2026-10-12"}],"thema":"Gesundheit","pruefung":{"lauf":"quiz-audit-v8","modell":"claude-sonnet-5-5","datum":"2026-10-15","urteil":"korrigieren","pruefsumme":"b61be36c96677397"}},{"id":"qx-a2-042","clusterId":"A","werkstueckRef":"A.22","stufe":4,"question":"Ein Anbieter erklärt, sein „energetisiertes“ Wasser heile Beschwerden. Auf die Rückfrage nach dem Wirkmechanismus sagt er: „Das ist eine emergente Eigenschaft des Wassers, die man nicht auf einzelne Moleküle zurückführen kann.“ Welche Rückfrage prüft diese Behauptung am besten?","options":["Welche Wechselwirkungen zwischen welchen Bestandteilen des Wassers sollen die Heilwirkung erzeugen, und passt das zu den bekannten Gesetzen der Physik?","Wie viele Kundinnen und Kunden haben das energetisierte Wasser schon gekauft, und wie zufrieden äußern sie sich über die Wirkung auf ihre Beschwerden?","Welche anerkannten Fachleute haben das Wort „emergent“ schon einmal für Eigenschaften von Wasser verwendet, und wie wurde es dort gebraucht?","Lässt sich die behauptete Heilwirkung durch genaue Untersuchung eines einzelnen Wassermoleküls vorhersagen, und wie genau müsste man dazu messen?"],"correctIndex":0,"explanation":"Das Wort „emergent“ beschreibt nur, dass auf höherer Ebene etwas Neues entsteht; es erklärt nichts. Seriöse Forschung fragt deshalb nach den Interaktionen, die eine emergente Eigenschaft erzeugen. Nässe ist ein Beispiel: Sie entsteht aus dem Zusammenspiel unzähliger Wassermoleküle und ihrer Wasserstoffbrückenbindungen und widerspricht der Chemie nicht. Ein Verkehrsforscher kann die Regeln nennen, aus denen ein Stau entsteht. Wer „Emergenz“ ruft, aber keinen Mechanismus nennen kann oder ein Phänomen behauptet, das bekannten Gesetzen widerspricht, benutzt das Wort als Diskussionsende statt als Forschungsfrage. Die Rückfrage nach Mechanismus und Vereinbarkeit mit den Gesetzen trennt beides. Die Frage nach Kundenzahl und Zufriedenheit klingt nach einer Praxisprüfung, sagt aber nichts über den Mechanismus. Die Frage nach Fachleuten, die das Wort benutzt haben, klingt nach Absicherung, doch dass andere es benutzen, beweist nichts. Die Untersuchung eines einzelnen Moleküls klingt gründlich, wäre aber der falsche Test, weil emergente Eigenschaften gerade nicht aus einer einzelnen Komponente ablesbar sind.","coreRule":"⚡ „Emergent“ ist eine Beschreibung, keine Erklärung: Verlange den Mechanismus und prüfe, ob er den bekannten Gesetzen widerspricht.","beleg":"Werkstück A.22 (Red Flags; Anti-Denkmuster, Aktivierungs-Frage 2)","status":"entwurf","scenario":"","kurz":"„Emergent“ benennt nur, dass auf höherer Ebene etwas Neues entsteht, und erklärt nichts. Deshalb muss man nach den Wechselwirkungen fragen, die den Effekt erzeugen, und danach, ob das zur Physik passt. Wer das Wort ruft, ohne das zu können, beendet damit die Diskussion.","prueffrage":"Was genau müsste im Wasser anders sein, damit sich ein Unterschied zu gewöhnlichem Wasser nachweisen ließe?","rueckmeldung":[{"option":1,"text":"Viele zufriedene Kunden wirken wie ein Praxistest, doch Zufriedenheit kann auch von Erwartung oder vom natürlichen Verlauf der Beschwerden kommen. Über den Mechanismus, um den es hier geht, sagt sie nichts."},{"option":2,"text":"Dass Fachleute das Wort „emergent“ benutzen, ist an sich nicht ungewöhnlich, belegt aber nichts über dieses Wasser. Ein Wort wird nicht dadurch erklärend, dass andere es verwenden; entscheidend ist, ob der Anbieter den Effekt selbst begründen kann."},{"option":3,"text":"Genaues Messen am einzelnen Molekül klingt gründlich, setzt aber voraus, dass sich die Eigenschaft aus einer Komponente ablesen lässt. Emergente Eigenschaften wie Nässe entstehen jedoch erst aus dem Zusammenspiel vieler Teile, dieser Test sucht also an der falschen Stelle."}],"familie":"mechanismus-verlangen","fertigkeit":"F1","quellen":[{"typ":"url","kurz":"Craver, C.; Tabery, J.; Illari, P.: Mechanisms in Science. Stanford Encyclopedia of Philosophy","oeffentlich":true,"url":"https://plato.stanford.edu/entries/science-mechanisms/","abruf":"2026-10-12"},{"typ":"url","kurz":"O'Connor, T.: Emergent Properties. Stanford Encyclopedia of Philosophy","oeffentlich":true,"url":"https://plato.stanford.edu/entries/properties-emergent/","abruf":"2026-10-12"},{"typ":"url","kurz":"USGS Water Science School: Adhesion and Cohesion Water","oeffentlich":true,"url":"https://www.usgs.gov/special-topics/water-science-school/science/adhesion-and-cohesion-water","abruf":"2026-10-12"}],"thema":"Gesundheit","pruefung":{"lauf":"quiz-audit-v4","modell":"claude-sonnet-5-5","datum":"2026-10-14","urteil":"korrigieren","pruefsumme":"2fffeb627fbf7683"}},{"id":"qx-a2-043","clusterId":"A","werkstueckRef":"A.23","stufe":1,"question":"Eine Analystin sagt über diese Aktie: „Der Kurs steigt seit Wochen gleichmäßig, jede Woche um etwa zwei Prozent. Das System ist stabil, also wird das noch lange so weitergehen.“ Welche Frage prüft am besten, ob dieses System kurz vor einem Umschlag stehen könnte?","options":["Wie stark schwankt der Kurs im Vergleich zu den Wochen davor, und wie schnell erholt er sich von kleinen Rückschlägen?","Wer treibt im Forum die Stimmung an, und verdient diese Person daran, wenn weitere Anleger die Aktie kaufen?","Wie wahrscheinlich ist es, dass ein so gleichmäßiger Anstieg allein durch Zufall entsteht, und wie sicher ist der Trend?","Welche Nachricht aus dem Unternehmen erklärt den Anstieg, und lässt sich diese Nachricht aus einer unabhängigen Quelle bestätigen?"],"correctIndex":0,"explanation":"Ein stetiger Anstieg beweist keine Stabilität: Systeme verändern sich oft lange gleichmäßig und kippen dann in einem Sprung, wie ein Glas, das zentimeterweise über den Tisch geschoben wird, bis die Kante erreicht ist. Die Schilderung zeigt typische Zutaten: Ein verstärkender Motor läuft (die Angst, etwas zu verpassen, treibt neue Käufer an), die Bremsen versagen (Gegenstimmen werden ausgegrenzt) und die Spannung wächst (Kredite machen das System anfällig). Wie nah die Kante ist, zeigt sich aber am besten am Verhalten des Systems selbst: Nahe an einem Umschlag erholt es sich oft langsamer von kleinen Störungen, und die Schwankungen nehmen zu. Schwankung und Erholung verraten allerdings nicht, wann das System kippt, und sie können Fehlalarm geben. Ein Blick auf die Interessen hinter der Stimmung ist ein guter Quellencheck, sagt aber nichts über die Nähe zum Umschlag. Ob ein so gleichmäßiger Anstieg Zufall sein könnte, ist hier nicht die Frage, denn es geht um die Stabilität eines Anstiegs, der schon wochenlang sichtbar ist. Und eine Nachricht, die den Anstieg erklärt, klärt seine Ursache, aber nicht, wie nah die Kante ist.","coreRule":"⚡ Stetig heißt nicht stabil: Frag nach Motoren, Bremsen und Spannung, und beobachte, wie schnell sich das System von kleinen Störungen erholt.","beleg":"Werkstück A.23 (Kontext & Tiefe: Indikatoren 1 bis 3)","status":"entwurf","scenario":"Im Chat eines Anlegerforums zu einer bestimmten Aktie wächst die Zahl der Beiträge, in denen Leute schreiben, sie wollten „auf keinen Fall den Zug verpassen“. Kritische Stimmen werden dort ausgelacht oder gesperrt. Viele Mitglieder haben Kredite aufgenommen, um zu kaufen.","quote":"","quoteLabel":"","kurz":"Ein gleichmäßiger Anstieg beweist keine Stabilität: Systeme driften oft lange stetig und kippen dann abrupt. Nahe an einem Umschlag erholt sich das System oft langsamer von kleinen Störungen, und die Schwankungen nehmen zu. Das zeigt sich am Kursverhalten selbst.","prueffrage":"Was weiß die Analystin über den Kursverlauf, außer dass er im Durchschnitt zwei Prozent pro Woche steigt?","rueckmeldung":[{"option":1,"text":"Wer die Stimmung antreibt und davon profitiert, ist ein guter Quellencheck für die Beiträge im Forum. Er sagt aber nichts darüber, wie nah das System an einem Umschlag ist, und die Stabilität des Anstiegs bleibt offen."},{"option":2,"text":"Ob ein so gleichmäßiger Anstieg Zufall sein könnte, ist hier nicht die Frage: Der Anstieg ist seit Wochen sichtbar. Gefragt ist, wie stabil er ist, und das sagt eine Zufallsabschätzung nicht."},{"option":3,"text":"Eine bestätigte Nachricht erklärt, warum der Kurs steigt, und das ist eine sinnvolle Prüfung. Sie sagt aber nicht, wie nah die Kante ist: Auch ein gut begründeter Anstieg kann kippen."}],"familie":"systemisch-denken","fertigkeit":"F4","quellen":[{"typ":"url","kurz":"Dakos, V. (2011): Expecting the Unexpected. Indicators of Resilience as Early-Warning Signals for Critical Transitions. Diss. Wageningen University (Kap. 2 = Scheffer u. a. 2009)","oeffentlich":true,"url":"https://edepot.wur.nl/168815","seite":"31","abruf":"2026-10-12"},{"typ":"url","kurz":"Scheffer, M. u. a. (2009): Early-warning signals for critical transitions. Nature 461, 53–59 (Abstract)","oeffentlich":true,"doi":"10.1038/nature08227","url":"https://pubmed.ncbi.nlm.nih.gov/19727193/","abruf":"2026-10-12"},{"typ":"url","kurz":"Meadows, D.: Leverage Points: Places to Intervene in a System. Donella Meadows Project","oeffentlich":true,"url":"https://donellameadows.org/archives/leverage-points-places-to-intervene-in-a-system/","abruf":"2026-10-12"}],"thema":"Geld und Zahlen","pruefung":{"lauf":"quiz-audit-v4","modell":"claude-sonnet-5-5","datum":"2026-10-14","urteil":"korrigieren","pruefsumme":"f53fd6ead47c4d23"}},{"id":"qx-a2-044","clusterId":"A","werkstueckRef":"A.23","stufe":2,"question":"Was übersieht die Nutzerin, wenn man den Wandel der Gruppe als instabiler werdendes System betrachtet?","scenario":"In einer Nachbarschaftsgruppe fielen früher Gerüchte schnell in sich zusammen, weil ein paar besonnene Leute sie einordneten. Die sind inzwischen ausgetreten. Seitdem schaukelt sich der Ton bei jedem Gerücht rasch hoch. Eine Nutzerin sagt: „Das Problem sind nur die Gerüchte selbst. Wenn die nicht wären, wäre alles ruhig.“","options":["Dass hitzige Antworten weitere hitzige Antworten nach sich ziehen und sich der Ton so von ganz allein hochschaukelt.","Dass die besonnene Einordnung weggefallen ist, die solche Aufschaukelungen in der Gruppe früher gedämpft hat.","Dass nicht die Gerüchte selbst die Unruhe ausmachen, sondern erst die hitzigen Antworten, die jeweils darauf folgen.","Dass Gerüchte in einer offenen Gruppe kaum zu verhindern sind und ein Zustand ganz ohne sie deshalb unrealistisch ist."],"correctIndex":1,"explanation":"Gerüchte gab es in der Gruppe schon vorher. Geändert hat sich vor allem, dass eine ausgleichende Schleife weggefallen ist: Die besonnene Einordnung wirkte als Bremse, die hitzige Reaktionen abgefangen hat. Systeme kippen oft dann, wenn solche Bremsen überlastet, ausgehebelt oder entfernt werden, etwa wenn Normen, Gesetze oder Peer Review wegfallen. Wer nur auf den Auslöser schaut, sieht nur den Funken und übersieht die fehlende Bremse; deshalb lohnt es sich, nicht nur nach den Antrieben zu fragen, sondern auch nach den Bremsen. Dass sich Gerüchte in großen Gruppen schneller verbreiten, stimmt im Schnitt, doch von einem Wachstum der Gruppe ist hier keine Rede. Dass Wiederholung ein Gerücht glaubwürdiger wirken lässt, ist ebenfalls richtig, erklärt aber nicht, warum der Ton erst nach dem Weggang der Besonnenen kippt. Und Gerüchte, die Ängste ansprechen, verbreiten sich leichter, doch Gerüchte gab es auch früher, ohne dass sich der Ton aufschaukelte.","coreRule":"⚡ Frag nicht nur, was antreibt, sondern auch, welche Bremse fehlt.","beleg":"Werkstück A.23 (Kontext & Tiefe: Indikator 2)","status":"entwurf","kurz":"Gerüchte gab es auch früher. Neu ist, dass die besonnene Einordnung als Bremse fehlt. Wer nur auf den Auslöser schaut, sieht den Funken und übersieht, dass die Bremse weggefallen ist, die ihn früher gelöscht hat.","prueffrage":"Gab es in der Gruppe auch früher schon Gerüchte, und wie lange hielten sie sich damals?","rueckmeldung":[{"option":0,"text":"Dass hitzige Antworten weitere nach sich ziehen, beschreibt einen echten Antrieb. Es erklärt aber nicht, warum das früher nicht passierte: Dieselben Gerüchte blieben folgenlos, solange es eine Bremse gab."},{"option":2,"text":"Die Unruhe entsteht tatsächlich erst durch die hitzigen Reaktionen, und die Nutzerin schaut zu eng auf den Auslöser. Offen bleibt, warum diese Reaktionen früher abgefangen wurden und jetzt nicht mehr."},{"option":3,"text":"Gerüchte ganz zu verhindern ist tatsächlich kaum möglich, und es gab sie in der Gruppe auch früher. Die Frage zielt aber auf etwas anderes: was sich im System verändert hat, sodass derselbe Auslöser jetzt anders wirkt."}],"familie":"systemisch-denken","fertigkeit":"F4","quellen":[{"typ":"url","kurz":"Meadows, D.: Leverage Points: Places to Intervene in a System. Donella Meadows Project","oeffentlich":true,"url":"https://donellameadows.org/archives/leverage-points-places-to-intervene-in-a-system/","abruf":"2026-10-12"}],"thema":"Netz und Medien","pruefung":{"lauf":"quiz-audit-v9","modell":"claude-sonnet-5-5","datum":"2026-10-15","urteil":"korrigieren","pruefsumme":"90d0efce1231e1a4"}},{"id":"qx-a2-045","clusterId":"A","werkstueckRef":"A.23","stufe":3,"question":"Eine Analystin hat gelernt, nach verstärkenden Rückkopplungen, versagenden Bremsen und aufgestauter Spannung zu suchen. Sie sieht inzwischen in jedem Kursausschlag, jedem Streit im Team und jedem Ausreißer in einer Statistik den Beginn eines Zusammenbruchs. Was ist an ihrem Vorgehen das Problem?","options":["Sie deutet gewöhnliche Schwankungen bei Kursen, Teamstimmung und Kundenzahlen als Vorboten eines Zusammenbruchs und macht ihre Warnungen so durch keine Beobachtung mehr widerlegbar.","Sie warnt so häufig vor einem Kollaps bei Kursen, Teamstimmung und Kundenzahlen, dass man ihr bald nicht mehr zuhört und eine berechtigte Warnung im Lärm untergehen würde.","Sie arbeitet mit einem zu groben Raster für Kurse, Teamstimmung und Kundenzahlen und bräuchte schärfere Prüffragen, um echte Zusammenbrüche verlässlich vorherzusagen.","Sie beurteilt Kurse, Teamstimmung und Kundenzahlen Woche für Woche, also so kurzfristig, dass kleine Ausschläge größer wirken, als sie über Monate betrachtet wären."],"correctIndex":0,"explanation":"Ein Denkwerkzeug wird unbrauchbar, wenn es überall anschlägt. Wer harmlose Schwankungen als Beweis für den nahenden Zusammenbruch liest, erkennt Muster im Rauschen (Apophenie). Ihr Satz „Das zeigt nur, wie knapp es war“ macht die Behauptung zusätzlich unwiderlegbar: Tritt der Kollaps ein, hatte sie recht, tritt er nicht ein, war es eben knapp. Eine Behauptung, die durch kein Ergebnis widerlegt werden kann, sagt nichts mehr aus. Dazu kommt: Auch seriöse Frühwarnsignale zeigen nur, dass ein System näher an die Kante rückt, nicht wann es kippt, und sie schlagen mitunter falschen Alarm. Brauchbar ist das Raster deshalb zur Beschreibung der Dynamik hinter einer Entwicklung (Motoren, Bremsen, Spannung, möglicher Auslöser), nicht als Prophezeiung.","coreRule":"⚡ Ein Prüfraster zeigt Architektur, keine Prophezeiung: Wer überall Kipppunkte sieht und jedes Ausbleiben als „knapp“ umdeutet, sieht Muster im Rauschen.","beleg":"Werkstück A.23 (Der Kipppunkt (Von der Nützlichkeit zur Gefahr); Red Flags: Langsameres Zurückfedern); Fn. ga-fruehwarnung (Scheffer u. a. 2009, Nature 461, S. 53–59) und Fn. ga-fruehsignale (Scheffer u. a. 2009, S. 54–58; Dakos 2011, S. 17–32)","status":"entwurf","scenario":"Eine Analystin nutzt ein Prüfraster für Kipppunkte. Sie fragt: Wo verstärkt sich etwas selbst? Welche Bremsen versagen? Wie viel Spannung hat sich aufgestaut? Seit sie damit arbeitet, warnt sie fast wöchentlich vor einem bevorstehenden Kollaps, ob bei Aktienkursen, Teamstimmung oder Kundenzahlen. Bisher ist keine ihrer Warnungen eingetreten, aber sie sagt: „Das zeigt nur, wie knapp es jedes Mal war.“","kurz":"Wer jede gewöhnliche Schwankung als Vorbote des Kollapses liest und ein Ausbleiben mit „war eben knapp“ erklärt, kann durch kein Ergebnis mehr widerlegt werden. Eine solche Behauptung sagt nichts mehr aus.","prueffrage":"Wie viele ihrer Warnungen sind bisher eingetreten, und wie erklärt die Analystin die übrigen?","rueckmeldung":[{"option":1,"text":"Dass häufige Alarme abstumpfen können, stimmt. Das Problem liegt aber vorher: Die Analystin kann durch nichts mehr widerlegt werden, weil „knapp“ jedes Ergebnis rettet. Selbst seltener gesprochen bliebe ihre Behauptung leer."},{"option":2,"text":"Schärfere Fragen klingen nach einer Lösung, aber auch gute Frühwarnsignale zeigen nur, dass ein System näher an die Kante rückt, nicht wann es kippt. Das Raster beschreibt Dynamik, es ist kein Vorhersageinstrument."},{"option":3,"text":"Ein kurzer Blickwinkel kann Ausschläge tatsächlich größer wirken lassen. Über Monate gesehen bliebe der Fehler jedoch: Auch dann würde „war knapp“ jeden Ausgang zu ihren Gunsten umdeuten."}],"familie":"muster-im-zufall","fertigkeit":"F4","quellen":[{"typ":"url","kurz":"Dakos, V. (2011): Expecting the Unexpected. Indicators of Resilience as Early-Warning Signals for Critical Transitions. Diss. Wageningen University","oeffentlich":true,"url":"https://edepot.wur.nl/168815","seite":"31","abruf":"2026-10-12"},{"typ":"url","kurz":"Thornton, S.: Karl Popper. Stanford Encyclopedia of Philosophy","oeffentlich":true,"url":"https://plato.stanford.edu/entries/popper/","abruf":"2026-10-12"}],"thema":"Geschichte und Wissenschaft","pruefung":{"lauf":"quiz-audit-v8","modell":"claude-sonnet-5-5","datum":"2026-10-15","urteil":"korrigieren","pruefsumme":"5be8f83d744927a8"}},{"id":"qx-a2-046","clusterId":"A","werkstueckRef":"A.23","stufe":4,"question":"Ein Team beobachtet über Monate ein Ökosystem. Die Messwerte zeigen: Nach kleinen Störungen erholt es sich immer langsamer, die Schwankungen werden größer, und jeder Zustand gleicht stärker dem vorigen. Eine Kollegin sagt: „Dann kippt das System in den nächsten Wochen, das ist jetzt sicher.“ Was ist die beste Einschätzung?","options":["Die Signale sprechen dafür, dass die Kante näher rückt, doch ob und wann das System in den nächsten Wochen kippt, sagen sie nicht verlässlich voraus.","Die Signale sprechen dafür, dass das System in den nächsten Wochen kippt, auch wenn der genaue Tag offen bleibt, denn solche Muster treten meist kurz vor dem Umbruch auf.","Die Signale sprechen eher dafür, dass das System bereits gekippt ist, denn ein System, das sich nur noch langsam erholt, steckt meist schon im neuen Zustand.","Die Signale sagen nur etwas über die Ursache der Störungen: Ohne bekannte Quelle lässt sich aus der langsamen Erholung nichts über die Nähe zur Kante schließen."],"correctIndex":0,"explanation":"Wenn sich ein System nahe einer Schwelle langsamer von kleinen Störungen erholt, stärker schwankt und jeder Zustand dem vorigen ähnlicher wird, rückt die Kante näher. Das ist ein allgemeines Muster, das in Modellen, in Klimadaten der Erdgeschichte, bei befischten Beständen und vor epileptischen Anfällen gefunden wurde. Es sagt aber nur etwas über die Nähe, nicht über den Zeitpunkt: Solche Signale schlagen mitunter falschen Alarm oder bleiben vor einem echten Umbruch stumm. Die Kollegin schließt also zu viel aus einem Warnsignal. Ein Anlass, genauer hinzusehen und Vorsorge zu treffen, ist es, aber keine Prognose mit Datum. Der Schluss auf einen Umbruch in den nächsten Wochen klingt nach einer Folgerung aus dem Muster, doch die Signale sagen nur etwas über die Nähe, nicht über den Zeitpunkt. Dass das System schon gekippt sei, klingt konsequent, widerspricht aber den Messwerten, denn es erholt sich ja noch, nur langsamer. Dass sich aus Messwerten allein keine Ursache ablesen lässt, stimmt, doch die Signale zeigen die Nähe zur Schwelle unabhängig davon, woher die Störungen kommen.","coreRule":"⚡ Frühwarnsignale zeigen die Nähe der Kante, nicht den Zeitpunkt des Sturzes.","beleg":"Werkstück A.23 (Red Flags: Langsameres Zurückfedern); Fn. ga-fruehsignale (Scheffer u. a. 2009, Nature 461(7260), S. 53–59, nach Dakos 2011, S. 21, 24, 27–29, 31)","status":"entwurf","scenario":"","kurz":"Langsamere Erholung, größere Schwankungen und wachsende Ähnlichkeit aufeinanderfolgender Zustände zeigen, dass die Kante näher rückt, nicht wann das System kippt. Wer aus dem Warnsignal einen Termin ableitet, schließt zu viel: Solche Signale schlagen mitunter falschen Alarm.","prueffrage":"Welche drei Veränderungen hat das Team gemessen, und wie würde sich ein stabiles System nach kleinen Störungen verhalten?","rueckmeldung":[{"option":1,"text":"Dass solche Muster oft vor Umbrüchen auftreten, stimmt. Daraus folgt aber nur, dass die Kante näher rückt, nicht, dass es in Wochen passiert: Die Signale schlagen mitunter falschen Alarm oder bleiben vor einem echten Umbruch stumm."},{"option":2,"text":"Das klingt konsequent, passt aber nicht zu den Messwerten: Das System erholt sich ja noch von Störungen, nur langsamer. Es steckt also noch im alten Zustand und rückt an die Schwelle heran, ohne sie schon überschritten zu haben."},{"option":3,"text":"Dass sich aus Messwerten allein keine Ursache ablesen lässt, stimmt. Die Signale sagen aber auch nichts über Ursachen, sondern zeigen am System selbst, wie nah es der Schwelle ist, ganz gleich, woher die Störungen kommen."}],"familie":"systemisch-denken","fertigkeit":"F4","quellen":[{"typ":"url","kurz":"Dakos, V. (2011): Expecting the Unexpected. Indicators of Resilience as Early-Warning Signals for Critical Transitions. Diss. Wageningen University (Kap. 2 = Scheffer u. a. 2009)","oeffentlich":true,"url":"https://edepot.wur.nl/168815","seite":"31","abruf":"2026-10-12"},{"typ":"doi","kurz":"Dakos, V. u. a. (2008): Slowing down as an early warning signal for abrupt climate change. PNAS 105(38), 14308–14312","oeffentlich":true,"doi":"10.1073/pnas.0802430105","abruf":"2026-10-12"},{"typ":"url","kurz":"Scheffer, M. u. a. (2009): Early-warning signals for critical transitions. Nature 461, 53–59 (Abstract)","oeffentlich":true,"doi":"10.1038/nature08227","url":"https://pubmed.ncbi.nlm.nih.gov/19727193/","abruf":"2026-10-12"}],"thema":"Natur und Klima","pruefung":{"lauf":"quiz-audit-v4","modell":"claude-sonnet-5-5","datum":"2026-10-14","urteil":"ok","pruefsumme":"7820c08e317dd998"}},{"id":"qx-a2-047","clusterId":"A","werkstueckRef":"A.24","stufe":1,"question":"Eine Forscherin sieht sich ihre Messdaten erst an und stellt dann fest, dass sich in einer Untergruppe ein „signifikanter“ Effekt zeigt. In ihrer Veröffentlichung schreibt sie, genau diesen Effekt habe sie von Anfang an erwartet. Welche Maßnahme hätte dieses Vorgehen am wirksamsten verhindert?","options":["Hypothese, Stichprobengröße und Auswertungsplan vor der Datenerhebung mit Zeitstempel hinterlegen; spätere Funde als explorativ kennzeichnen.","Die Stichprobe deutlich vergrößern, damit die Teststärke auch in den Untergruppen reicht; kleine echte Effekte würden dann sicher erkannt.","Die Auswertung verblinden, damit die Auswertenden nicht wissen, welche Teilnehmer zu welcher Gruppe gehören; so prägt keine Erwartung das Ergebnis.","Nach Erscheinen der Studie prüfen, wie viele vergleichbare Studien nie veröffentlicht wurden; diese unveröffentlichten Studien im Bericht vermerken."],"correctIndex":0,"explanation":"Wer erst die Daten ansieht und dann die Hypothese formuliert (HARKing), findet bei genügend Variablen und Untergruppen fast immer etwas: Es ist, als würde man erst schießen und dann die Zielscheibe malen. Dagegen hilft nur, die Wette vorher zu versiegeln. Wenn Hypothese und Plan vor den Daten feststehen und belegbar sind, lässt sich nachprüfen, ob das Ergebnis erwartet oder nachträglich zurechtgelegt wurde. Alles, was später zusätzlich auftaucht, bleibt erlaubt, zählt aber als Idee für die nächste Studie und nicht als Beweis. Eine Auswertung großer US-Herz-Kreislauf-Studien stützt das: Vor 2000, ohne Pflicht zur vorherigen Festlegung der Zielgröße, meldeten 17 von 30 Studien (57 Prozent) einen Nutzen, danach 2 von 25 (8 Prozent). Die Autoren halten für möglich, dass die Registrierung dazu beitrug.","coreRule":"⚡ Erst die Wette versiegeln, dann die Karten aufdecken: Hypothese vor den Daten.","quote":"Alles, was danach zusätzlich gefunden wird, ist erlaubt -- aber als *explorativ* zu kennzeichnen, als Idee für die nächste Studie, nicht als Beweis in dieser.","quoteLabel":"Merksatz:","beleg":"Werkstück A.24 (Werkzeug 2: Präregistrierung); Fn. ga-praeregistrierung (Kaplan/Irvin 2015, PLOS ONE 10(8), e0132382; Kerr 1998)","status":"entwurf","scenario":"Eine Studie wertet viele Variablen und Untergruppen aus. Bei genügend Auswertungswegen liefert der Zufall fast immer irgendwo ein „signifikantes“ Muster. Im Bericht steht später, die Hypothese sei von Anfang an klar gewesen.","kurz":"Nur eine vorab hinterlegte Hypothese samt Auswertungsplan lässt später prüfen, ob ein Effekt wirklich erwartet war. Wer erst die Daten ansieht, findet bei vielen Untergruppen fast immer etwas, wie beim Schießen und anschließenden Zielscheibenmalen.","prueffrage":"In wie vielen Untergruppen hat die Forscherin nach einem Effekt gesucht, und in wie vielen ist sie fündig geworden?","rueckmeldung":[{"option":1,"text":"Mehr Teilnehmende erhöhen die Teststärke und sind oft nützlich. Das Problem ist aber ein anderes: Wer viele Untergruppen auswertet, findet auch in großen Stichproben zufällige Muster und kann sie hinterher als erwartet ausgeben."},{"option":2,"text":"Verblindung schützt tatsächlich davor, dass Erwartungen die Auswertung färben. Sie legt aber nicht fest, was vorher behauptet wurde, und verhindert daher nicht, dass eine Hypothese erst nach dem Blick auf die Daten entsteht."},{"option":3,"text":"Unveröffentlichte Studien zu zählen macht Verzerrungen bei der Veröffentlichung sichtbar. Hier liegt das Problem aber früher: Die Hypothese wurde erst nach den Daten formuliert, und eine spätere Zählung verhindert das nicht."}],"familie":"muster-im-zufall","fertigkeit":"F4","quellen":[{"typ":"doi","kurz":"Nosek, B. A.; Ebersole, C. R.; DeHaven, A. C.; Mellor, D. T. (2018): The preregistration revolution. PNAS 115(11), 2600–2606","oeffentlich":true,"doi":"10.1073/pnas.1708274114","abruf":"2026-10-12"},{"typ":"doi","kurz":"Kaplan, R. M.; Irvin, V. L. (2015): Likelihood of Null Effects of Large NHLBI Clinical Trials Has Increased over Time. PLOS ONE 10(8), e0132382","oeffentlich":true,"doi":"10.1371/journal.pone.0132382","abruf":"2026-10-12"},{"typ":"literatur","kurz":"Kerr, N. L. (1998): HARKing: Hypothesizing After the Results are Known. Personality and Social Psychology Review 2(3), 196–217","oeffentlich":false}],"thema":"Geschichte und Wissenschaft","pruefung":{"lauf":"quiz-audit-v5","modell":"claude-sonnet-5-5","datum":"2026-10-14","urteil":"korrigieren","pruefsumme":"a9b265f0eea8d803"}},{"id":"qx-a2-048","clusterId":"A","werkstueckRef":"A.24","stufe":2,"question":"Eine Zeitung titelt: „Mittel wirkt nicht: Ergebnis nicht signifikant (p = 0,06).“ Welche Überlegung ist hier am sinnvollsten?","options":["Ein p-Wert von 0,06 bedeutet, dass die Wirkung mit 94 Prozent Wahrscheinlichkeit echt ist, und die Zeitung hätte diese hohe Wahrscheinlichkeit nennen müssen.","Ein p-Wert knapp über 0,05 spricht dafür, dass der Effekt klein ist, denn ein großer Effekt hätte die Schwelle von 0,05 sicher unterschritten.","Die Schwelle von 0,05 ist eine Konvention, und eine Wirkung bleibt mit den Daten vereinbar, solange das Konfidenzintervall sie nicht ausschließt.","Ein p-Wert von 0,06 liegt so nah an der Schwelle von 0,05, dass er praktisch als signifikant gilt und die Zeitung „Mittel wirkt“ hätte titeln müssen."],"correctIndex":2,"explanation":"„Nicht signifikant“ heißt nicht „kein Effekt“. Es heißt nur, dass die Daten die Annahme „gar keine Wirkung“ nicht deutlich genug widerlegen. Die Schwelle von 5 Prozent ist eine Konvention, kein Naturgesetz: Ein Ergebnis mit p = 0,06 und eines mit p = 0,04 unterscheiden sich kaum, werden aber als „wirkt nicht“ und „wirkt“ verkauft. Auch ein signifikantes Ergebnis schließt den Zufall nicht aus, und ein nicht signifikantes beweist keine Wirkungslosigkeit. Die American Statistical Association warnte 2016 vor genau diesem Gebrauch des p-Werts, und 2019 forderten über 800 Forschende in Nature, „statistisch signifikant“ nicht länger als Ja-Nein-Urteil zu verwenden. Sinnvoll ist es, das Konfidenzintervall zu lesen: Es zeigt, welche Effektgrößen mit den Daten vereinbar sind, und damit auch, ob eine bedeutsame Wirkung noch möglich ist. Die Deutung von p = 0,06 als 94-prozentige Wahrscheinlichkeit für eine echte Wirkung klingt nach einer einfachen Übersetzung, verwechselt aber die Frage, wie gut die Daten zu „keine Wirkung“ passen, mit der Frage, wie wahrscheinlich die Wirkung ist. Dass ein großer Effekt die Schwelle sicher unterschritten hätte, klingt logisch, doch der p-Wert hängt auch von der Teilnehmerzahl ab, sodass selbst ein großer Effekt bei einer kleinen Studie knapp scheitern kann. Die Überschrift „Mittel wirkt“ kehrt den Fehler der Zeitung nur um, denn bei p = 0,06 ist die Wirkung ebenso wenig belegt wie ihr Fehlen.","coreRule":"⚡ Lies das Intervall, nicht nur das Etikett „signifikant“ oder „nicht signifikant“.","beleg":"Werkstück A.24 (Werkzeug 3: Konfidenzintervall); Fn. ga-signifikanz (Wasserstein/Lazar 2016, The American Statistician 70(2), S. 131–132; Amrhein u. a. 2019, Nature 567, S. 305–307)","status":"entwurf","scenario":"In der Meldung steht nur der p-Wert. Zur Größe des Effekts oder zu einem Konfidenzintervall wird nichts gesagt.","kurz":"„Nicht signifikant“ heißt nicht „kein Effekt“: Die Schwelle von 0,05 ist eine Konvention, und das Konfidenzintervall zeigt, welche Wirkungen die Daten noch zulassen. Der Fehler ist, aus einer knapp verfehlten Schwelle ein Ja-Nein-Urteil zu machen.","prueffrage":"Würde die Schlagzeile umgekehrt lauten, wenn p = 0,04 herausgekommen wäre, und wie groß wäre dieser Unterschied in den Daten?","rueckmeldung":[{"option":0,"text":"Die Rechnung „1 minus 0,06“ liegt nahe, beantwortet aber eine andere Frage. Der p-Wert sagt, wie gut die Daten zu „keine Wirkung“ passen, nicht, wie wahrscheinlich die Wirkung echt ist."},{"option":1,"text":"Ein kleiner Effekt würde zu p = 0,06 passen, aber ebenso ein großer: Der p-Wert hängt auch von der Teilnehmerzahl ab, und bei einer kleinen Studie kann selbst ein großer Effekt die Schwelle knapp verfehlen."},{"option":3,"text":"Dass sich p = 0,06 und p = 0,04 kaum unterscheiden, stimmt. Daraus folgt aber nicht, dass man die Schwelle großzügiger anwenden sollte: Auch „Mittel wirkt“ wäre bei p = 0,06 nicht belegt und kehrt den Fehler nur um."}],"familie":"studie-genau-lesen","fertigkeit":"F4","quellen":[{"typ":"url","kurz":"American Statistical Association (2016): ASA releases statement on statistical significance and p-values (Pressemitteilung, 7. März 2016)","oeffentlich":true,"url":"https://www.amstat.org/asa/files/pdfs/p-valuestatement.pdf","abruf":"2026-10-12"},{"typ":"literatur","kurz":"Wasserstein, R. L.; Lazar, N. A. (2016): The ASA Statement on p-Values: Context, Process, and Purpose. The American Statistician 70(2), 129–133","oeffentlich":false,"doi":"10.1080/00031305.2016.1154108"},{"typ":"literatur","kurz":"Amrhein, V.; Greenland, S.; McShane, B. (2019): Scientists rise up against statistical significance. Nature 567, 305–307","oeffentlich":false,"doi":"10.1038/d41586-019-00857-9"}],"thema":"Geschichte und Wissenschaft","pruefung":{"lauf":"quiz-audit-v4","modell":"claude-sonnet-5-5","datum":"2026-10-14","urteil":"korrigieren","pruefsumme":"c98a634c62fe775d"}},{"id":"qx-a2-049","clusterId":"A","werkstueckRef":"A.24","stufe":3,"question":"Was folgt aus diesen Angaben?","options":["Der Effekt ist eher eine Laborwirkung, weil die Feeds gezielt manipuliert wurden und die Stimmung so nicht im gewohnten Alltag gemessen ist.","Der Effekt ist wahrscheinlich ein Zufallsfund, weil bei 689.003 Teilnehmern und vielen Auswertungen irgendein Unterschied signifikant wird.","Der Effekt ist nachweisbar, aber mit d = 0,001 bis 0,02 praktisch winzig, weil Signifikanz nichts über die Größe eines Effekts aussagt.","Der Effekt ist groß, weil der p-Wert extrem klein ist und ein kleinerer p-Wert bei 689.003 Teilnehmern auf einen größeren Effekt hinweist."],"correctIndex":2,"explanation":"Mit einer hinreichend großen Stichprobe wird jeder noch so winzige Unterschied signifikant. Signifikanz sagt nur, dass die Daten schlecht zur Annahme „gar kein Effekt“ passen, nicht, wie groß der Effekt ist. Die gemeldeten Werte (d = 0,001 bis 0,02) liegen deutlich unter der Konvention für einen kleinen Effekt (ab d = 0,2) und sind im Alltag eines einzelnen Nutzers unsichtbar. Die Schlagzeile verwechselt „nachweisbar“ mit „bedeutend“. Die prüfende Frage lautet: Wie groß ist der Effekt in einer Einheit, die ich mir vorstellen kann?","coreRule":"⚡ Signifikanz beantwortet „Gibt es etwas?“, die Effektstärke „Wie viel?“.","beleg":"Werkstück A.24 (Werkzeug 4: Effektstärke); Fn. ga-effektstaerke (Kramer u. a. 2014, PNAS 111(24), S. 8788–8790; Cohen 1988)","status":"entwurf","scenario":"Eine Schlagzeile lautet: „Studie beweist: Gefühle stecken über soziale Netzwerke an.“ Im Studienbericht steht: Bei 689.003 Teilnehmern „steckte“ die Stimmung durch manipulierte Nachrichtenfeeds messbar an; das Ergebnis ist hochsignifikant (p-Wert extrem klein), die Effektstärke d liegt zwischen 0,001 und 0,02. Als Faustregel gilt: Ab d = 0,2 spricht man von einem kleinen, ab 0,5 von einem mittleren und ab 0,8 von einem großen Effekt.","kurz":"Ein extrem kleiner p-Wert zeigt nur, dass der Effekt wohl nicht null ist, nicht wie groß er ist. Bei 689.003 Teilnehmern wird auch ein winziger Unterschied signifikant, und d = 0,001 bis 0,02 liegt weit unter einem kleinen Effekt.","prueffrage":"Wie viel Stimmungsänderung steckt in diesem Wert, wenn du ihn in etwas Greifbares umrechnest?","rueckmeldung":[{"option":0,"text":"Ob die Manipulation der Feeds den Alltag abbildet, ist eine berechtigte Frage, betrifft aber die Übertragbarkeit. Die Angaben sagen nichts darüber, wie groß der Effekt ist, und darum ging es hier."},{"option":1,"text":"Bei so vielen Teilnehmern ist ein signifikanter Befund gerade kein Zufallsbefund: Die Daten passen schlecht zu „gar kein Effekt“. Das Problem liegt nicht darin, ob es einen Effekt gibt, sondern darin, wie klein er ist."},{"option":3,"text":"Ein winziger p-Wert wirkt wie ein Zeichen für Stärke, zeigt aber nur, dass ein Effekt kaum null sein dürfte. Gerade bei sehr großen Stichproben wird auch ein winziger Effekt extrem signifikant, und d liegt hier weit unter 0,2."}],"familie":"studie-genau-lesen","fertigkeit":"F4","quellen":[{"typ":"doi","kurz":"Kramer, A. D. I.; Guillory, J. E.; Hancock, J. T. (2014): Experimental evidence of massive-scale emotional contagion through social networks. PNAS 111(24), 8788–8790","oeffentlich":true,"doi":"10.1073/pnas.1320040111","abruf":"2026-10-12"},{"typ":"url","kurz":"American Statistical Association (2016): ASA releases statement on statistical significance and p-values (Pressemitteilung)","oeffentlich":true,"url":"https://www.amstat.org/asa/files/pdfs/p-valuestatement.pdf","abruf":"2026-10-12"},{"typ":"literatur","kurz":"Cohen, J. (1988): Statistical Power Analysis for the Behavioral Sciences. 2. Aufl. Hillsdale: Erlbaum","oeffentlich":false}],"thema":"Netz und Medien","pruefung":{"lauf":"quiz-audit-v8","modell":"claude-sonnet-5-5","datum":"2026-10-15","urteil":"ok","pruefsumme":"542b5dc8c441c2d7"}},{"id":"qx-a2-050","clusterId":"A","werkstueckRef":"A.24","stufe":4,"question":"Welche Frage prüft diesen Schluss am besten?","options":["Wie sieht das Verhältnis aus, wenn man Geimpfte und Ungeimpfte innerhalb derselben Altersgruppe vergleicht?","Wie zuverlässig wurde in den Krankenhäusern der Impfstatus der Schwerkranken erfasst, und wie vollständig sind die Meldungen?","Wie viele Schwerkranke wurden insgesamt gezählt, und reicht diese Zahl aus, um verlässliche Aussagen zu treffen?","Wer hat die Zahlen erhoben und veröffentlicht, und hat diese Stelle ein erkennbares Interesse an einem bestimmten Ergebnis?"],"correctIndex":0,"explanation":"Die Gesamtzahl vermischt Gruppen, die sich im Risiko stark unterscheiden. Sind die Gefährdetsten zugleich fast alle geimpft, stellen Geimpfte einen großen Teil der Schwerkranken, selbst wenn die Impfung das Risiko in jeder Altersgruppe deutlich senkt. Ein solcher Zusammenhang, der in der Gesamtheit anders aussieht als in den Teilgruppen, heißt Simpson-Paradox. Ein berühmtes Beispiel: Berkeley 1973 ließ 44 Prozent der männlichen, aber nur 35 Prozent der weiblichen Bewerber zu. Nach Fachbereichen aufgeschlüsselt zeigte sich kein Nachteil für Frauen, weil sie sich häufiger in Fächern mit niedrigen Zulassungsquoten beworben hatten. Der Vergleich innerhalb gleicher Gruppen entscheidet also, was die Zahlen aussagen. Vorsicht in der Gegenrichtung: Nicht jede Aufteilung ist die richtige, und welche gilt, verraten die Zahlen allein nicht. Die Erfassung des Impfstatus zu prüfen ist ein sinnvoller Datencheck, ändert aber nichts daran, dass die Gesamtzahl Gruppen mischt. Die Fallzahl schützt vor Zufallsschwankungen, nicht vor der Vermischung unterschiedlicher Risikogruppen. Und die Frage nach dem Interesse hinter den Zahlen betrifft die Quelle, nicht die Rechnung.","coreRule":"⚡ Teile die Gruppen auf, aber frag, welche Aufteilung der Zusammenhang wirklich verlangt.","beleg":"Werkstück A.24 (Werkzeug 5: Das Simpson-Paradox); Fn. ga-simpson (Bickel/Hammel/O'Connell 1975, Science 187(4175), S. 398–404; Morris 2021; Pearl 2014, The American Statistician 68(1), S. 8–13)","status":"entwurf","scenario":"In einem Land mit hoher Impfquote meldet eine Zeitung: „Mehr als die Hälfte der Schwerkranken im Krankenhaus ist geimpft. Die Impfung schützt also kaum.“ Bekannt ist außerdem: Die Ältesten sind fast vollständig geimpft und zugleich am stärksten gefährdet, schwer zu erkranken.","kurz":"Die Gesamtzahl mischt Gruppen mit sehr verschiedenem Risiko: Sind die am stärksten Gefährdeten fast alle geimpft, stellen Geimpfte viele Schwerkranke, auch wenn die Impfung in jeder Altersgruppe schützt. Erst der Vergleich innerhalb gleicher Gruppen zeigt, was die Zahlen aussagen.","prueffrage":"Unterscheiden sich die Geimpften und die Ungeimpften im Land außer durch die Impfung noch in etwas, das ihr Risiko für eine schwere Erkrankung beeinflusst?","rueckmeldung":[{"option":1,"text":"Zu prüfen, wie sauber der Impfstatus erfasst wurde, ist ein sinnvoller Datencheck. Selbst lückenlose Daten ließen die Gesamtzahl aber Gruppen mit sehr unterschiedlichem Risiko vermengen, und genau dort liegt der Schwachpunkt des Schlusses."},{"option":2,"text":"Eine ausreichende Fallzahl schützt vor Zufallsschwankungen, und danach zu fragen ist berechtigt. Hier liegt das Problem aber nicht im Zufall: Auch eine sehr große Zahl bliebe irreführend, wenn sie Gruppen mit unterschiedlichem Risiko zusammenwirft."},{"option":3,"text":"Nach der Quelle und ihrem Interesse zu fragen, ist grundsätzlich klug, betrifft aber die Herkunft der Zahlen, nicht die Rechnung. Auch bei einer völlig neutralen Stelle bliebe der Schluss aus der Gesamtzahl fragwürdig."}],"familie":"studie-genau-lesen","fertigkeit":"F4","quellen":[{"typ":"url","kurz":"Morris, J. (2021): Israeli data: How can efficacy vs. severe disease be strong when 60% of hospitalized are vaccinated? Covid Data Science","oeffentlich":true,"url":"https://www.covid-datascience.com/post/israeli-data-how-can-efficacy-vs-severe-disease-be-strong-when-60-of-hospitalized-are-vaccinated","abruf":"2026-10-12"},{"typ":"url","kurz":"Pearl, J. (2013): Understanding Simpson's Paradox. UCLA Technical Report R-414 (Vorfassung zu The American Statistician 68(1), 2014)","oeffentlich":true,"url":"https://ftp.cs.ucla.edu/pub/stat_ser/r414.pdf","abruf":"2026-10-12"},{"typ":"literatur","kurz":"Bickel, P. J.; Hammel, E. A.; O'Connell, J. W. (1975): Sex Bias in Graduate Admissions: Data from Berkeley. Science 187(4175), 398–404","oeffentlich":false}],"thema":"Gesundheit","pruefung":{"lauf":"quiz-audit-v4","modell":"claude-sonnet-5-5","datum":"2026-10-14","urteil":"ok","pruefsumme":"025f407a1fd5c307"}}]`);export{t as n,n as t};